SELECT 'moj-all-verified-judgments-review-002-chunk-019' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"5af13e6a-1e2c-55e0-a713-fcf41abe47f4","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب اجلد حضانة أوالد ابنه -زواج املرأة -موافقة زوجها على حضانتها ألوالدها من الزوج السابق -النظر يف احلضانة ملصلحة احملضون -صرف النظر عن طلب اجلد حضانة أوالد ابنه.","document_number":"34271962","case_number":"3441277","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/18","year":"1434","subject":"حضانة -طلب اجلد حضانة أوالد ابنه -زواج املرأة -موافقة زوجها على حضانتها ألوالدها من الزوج السابق -النظر يف احلضانة ملصلحة احملضون -صرف النظر عن طلب اجلد حضانة أوالد ابنه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34271962 :‬تاريخه ‪1434/7/18 :‬هـ‬\n                     ‫رقم الدعوى ‪3441277:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34294900‬تاريخه‪1434/8/13 :‬هـ‬\n\n\n‫حضانــة ‪ -‬طلــب اجلــد حضانــة أوالد ابنــه ‪ -‬زواج املــرأة ‪ -‬موافقــة زوجهــا‬\n‫علــى حضانتهــا ألوالدهــا مــن الــزوج الســابق ‪ -‬النظــر يف احلضانــة‬\n‫ملصلحــة احملضــون ‪ -‬صــرف النظــر عــن طلــب اجلــد حضانــة أوالد ابنــه‪.‬‬\n\n\n\n\n‫‪ .1‬قــال ابــن القيــم ‪ -‬رحمــه اهلل ‪ -‬يف زاد املعــاد ( ‪ ( : ) 484/5‬أن الــزوج إذا‬\n‫رضــي باحلضانــة وآثــر كــون الطفــل يف حجــره لــم تســقط احلضانــة‬\n                                                         ‫هــذا هــو الصحيــح )‪.‬‬\n                                   ‫‪ .2‬قاعدة‪ ( :‬احلضانة حق للمحضون )‪.‬‬\n\n\n\n\n‫حضــر اجلــد ويطلــب حضانــة أوالد ابنــه املتوفــى وهــم ‪ ...‬و‪ ...‬و‪ ...‬وقــد تــويف‬\n‫والدهــم واألوالد يف حضانــة أمهــم املدعــى عليهــا وقــد تزوجــت ويطلــب‬\n‫نقــل احلضانــة إليــه ‪ -‬أقــرت املدعــى عليهــا بأنهــا كانــت زوج ـ ًة البــن‬\n‫املدعــي وأن األوالد الذيــن ذكرهــم هــم أوالدهــا منــه وأقــرت بالــزواج‬\n‫مــن رجــل آخــر ولكــن رفضــت نقــل احلضانــة إلــى املدعــي نظــر ًا لكبــر‬\n‫ســنه وال يســتطيع إدارة شــوؤنهم‪ ،‬مت ســؤال املدعــي هــل تطعــن بحضانــة‬\n‫األم بشــيء فأجــاب بقولــه ال‪ ،‬حضــر زوج املدعــى عليهــا وقــرر أنــه ال‬\n‫مانــع مــن بقــاء أوالد زوجتــه عنــده وحتــت حضانــة أمهــم ‪ -‬ظهــر للقاضــي‬\n\n                                                                                       ‫‪208‬‬\n\f      ‫أن بقــاء األوالد مجتمعــن عنــد أمهــم فيــه مصلحــة لهــم‪ ،‬احلكــم بصرف‬\n      ‫النظــر عــن دعــوى املدعــي وبقــاء حضانــة األوالد للمدعــى عليهــا‪ ،‬قــرر‬\n      ‫املدعــي اعتراضــه علــى احلكــم بالئحــة اعتراضيــة‪ ،‬صــدق احلكــم مــن‬\n                                                          ‫محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 3441277‬وتاريــخ‬\n      ‫‪ 1434/01/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34201473‬وتاريــخ‬\n      ‫‪ 1434/01/24‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/07/10‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي ‪ .......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .......‬وحضــرت حلضــوره املدعــى عليهــا‬\n      ‫‪ .......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬وادعــى‬\n      ‫املدعــي قائــا ان املدعــى عليهــا كانــت زوج ابنــي ‪ .......‬وقــد اجنبــت‬\n      ‫منــه ثالثــة اوالد وهــم ‪ ...‬املولــودة يف ‪1426/10/17‬ه ـ ‪ .......‬املولــود يف‬\n      ‫‪1429/10/17‬ه ـ ‪ .......‬املولــودة يف ‪1431/9/9‬ه ـ ال وارث لــه ســواهم‬\n      ‫وقــد تــويف ابنــي بتاريــخ ‪1432/8/16‬ه ـ مبوجــب صــك حصــر الورثــة‬\n      ‫رقــم ‪ .......‬وتاريــخ ‪1432/9/17‬ه ـ الصــادر مــن هــذه احملكمــة ومنــذ‬\n      ‫وفــاة ابنــي واالوالد عنــد امهــم وقــد تزوجــت بتاريــخ ‪1434/01/29‬ه ـ‬\n      ‫اطلــب نقــل حضانهــم لــي هــذه دعــواى وبعــرض ذلــك علــى املدعــى عليهــا‬\n      ‫اجابــت قائلــة ماذكــره املدعــي مــن أن ابنــه كان زوجــي وأنــي اجنبــت‬\n      ‫مــن ابنــه ثالثــة أوالد هــم املذكــورون اعــاه وانــي تزوجــت بعــد وفــاة‬\n\n‫‪209‬‬\n\f‫ابنــه فصحيــح واوالدي عنــدي منــذ وفــاة ابيهــم وأنــا املســؤلة عنهــم ووليــة‬\n‫عليهــم ايضــا مبوجــب صــك الواليــة رقــم ‪ .......‬وتاريــخ ‪1432/10/09‬ه ـ‬\n‫الصــادرة مــن احملكمــة العامــة بجــدة واملدعــي جدهــم كبيــر يف‬\n‫الســن واليســتطيع ادارة شــؤونهم مثلــي لــذا اطلــب بقــاء حضانــة اوالدي‬\n‫عنــدي هكــذا اجابــت وبســؤال املدعــي هــل تطعــن يف حضانــة املدعــى‬\n‫عليهــا بشــئ اجــاب قائــا ال اطعــن فيهــا بشــىء واريــد حضانتهــم عنــدي‬\n‫هكــذا اجــاب والجــل التأمــل رفعــت اجللســة وبــاهلل التوفيــق ‪ ،‬ويف‬\n‫جلســة اخــرى حضــر املدعــي ‪ .......‬وحضــرت حلضــوره املدعــى عليهــا‬\n‫‪ .......‬برفقــة والدهــا ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ .......‬كمــا حضــر زوج املدعــى عليهــا ‪ .......‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .......‬وقــرر أنــه ال مانــع مــن بقــاء اوالد زوجتــه عنــده‬\n‫وحتــت حضانــة أمهــم فبنــاء علــى ماتقــدم مــن الدعــوى واالجابــة ومبــا ان‬\n‫املدعــي وهــو جدهــم يطالــب بحضانــة أوالد أبنــه ومبــا أن احلضانــة ينظــر‬\n‫فيهــا إلــى مصلحــة احملضــون فقــط ومصلحــة االوالد بقاؤهــم مجتمعــن‬\n‫عنــد أمهــم حتافــظ عليهــم وترعــى شــئونهم وحيــث قــد حضــر زوج االم‬\n‫وقــرر موافقتــه علــى بقــاء االوالد حتــت حضانــة زوجتــه ويف بيتــه ومبــا أن‬\n‫املدعــي جدهــم كبيــر يف الســن وال يســتطيع القيــام علــى شــئونهم مثــل‬\n‫أمهــم قــال أبــن القيــم رحمــه اهلل بعــد ذكــره لبعــض األحــكام املأخــوذة‬\n‫مــن حديــث البــراء بــن عــازب يف قصــة ابنــة حمــزة‪ .‬الثالثــة ( أن الــزوج إذا‬\n‫رضــي باحلضانــة واثــر كــون الطفــل عنــده يف حجــره لــم تســقط احلضانــة‬\n‫هــذا هــو الصحيــح ) زاد املعــاد ‪ 484/5‬لــذا فقــد صرفــت النظــر عــن‬\n‫دعــوى املدعــي وأبقيــت حضانــة االوالد عنــد أمهــم وأفهمــت املدعــي أن‬\n‫لــه حــق الزيــارة فقــط هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى‬\n\n\n                                                                                         ‫‪210‬‬\n\f      ‫املدعــي قــرر عــدم قناعتــه باحلكــم واســتعد بتقــدمي الئحتــه االعتراضيــة‬\n      ‫خــال املــدة النظاميــة وهــي ثالثــون يومــا وافهمتــه بتعليمــات االســتئناف‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف ‪1434/07/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 3441277‬وتاريــخ‬\n      ‫‪ 1434/01/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34201473‬وتاريــخ‬\n      ‫‪ 1434/01/24‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/07/30‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 12.00‬فقــد مت اإلطــاع علــى الالئحــة اإلعتراضيــة‬\n      ‫املقدمــة مــن املدعــي ‪ .......‬واملكونــة مــن ورقــة واحــدة ولــم أجــد مايؤثــر‬\n      ‫علــى ماحكمــت بــه لــذا قــررت رفــع املعاملــة حملكمــة اإلســتئناف‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                  ‫‪1434/07/30‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمة العامة مبحافظة جدة برقم ‪ 3441277‬وتاريخ ‪1434/01/24‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 34201473‬وتاريــخ ‪ 1434/01/24‬ه ـ‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف بخطــاب رئيســها رقــم‬\n      ‫‪ 34201473‬وتاريــخ ‪1434/08/22‬ه ـ املرفــق بــه قــرار التصديــق رقــم‬\n      ‫‪ 34294900‬وتاريــخ ‪1434/08/13‬ه ـ بخصــوص دعــوى ‪ .......‬ضــد‬\n      ‫‪ .......‬املتضمــن‪ :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم بصــرف النظــر عــن طلــب املدعــي واهلل‬\n\n\n‫‪211‬‬\n\f‫املوفــق وصلــى اهلل وســلم علــى ســيدنا محمــد وعلــى الــه وصحبــه وســلم‬\n‫‪ ،،،،‬انته ـ ـ ـ ــى وللواقــع جــرى إثباتــه وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/28‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 34/201473‬وتاريــخ ‪1434/8/2‬ه ـ‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ .......‬القاضي باحملكمة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 34271962‬وتاريــخ ‪1434/7/18‬هــ‪،‬‬\n‫املتضمــن دعــوى ‪ .......‬ضــد املــرأة ‪ .......‬يف حضانــة أوالد املدعــى عليهــا‪،‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم بصــرف النظــر عــن طلــب املدعــي‪ ،‬واهلل املوفــق ‪ .‬وصلــى‬\n                          ‫اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪212‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":208,"source_page_end":212,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5bc8ca269340ba22211fcbadc4180dee562e3caed2e9cf8970f26670323cc7ba","normalized_text_hash":"dbd3010658259dc23421e5501e6e8969c6076dc08778a43473f692807448526c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p208-34271962"},{"id":"21b856fe-72de-56e3-801f-a88d03ff2952","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب األم حضانة األوالد مع بقاء عقد الزوجية -وجود األوالد مع األب -األم أحق باحلضانة ما لم تنكح -األم أشفق على أوالدها -أحقية األم باحلضانة واإللزام بالتسليم -احلكم بالنفاذ املعجل يف احلضانة .","document_number":"3449875","case_number":"14695","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":"الدائرة ختمه وتوقيعه) وباهلل التوفيق وصلى اهلل وسلم على نبينا","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/27","year":"1434","subject":"حضانة -طلب األم حضانة األوالد مع بقاء عقد الزوجية -وجود األوالد مع األب -األم أحق باحلضانة ما لم تنكح -األم أشفق على أوالدها -أحقية األم باحلضانة واإللزام بالتسليم -احلكم بالنفاذ املعجل يف احلضانة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3449875 :‬تاريخه ‪1434/2/27 :‬هـ‬\n                            ‫رقم الدعوى ‪14695 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34216424‬تاريخه‪1434/05/19 :‬هـ‬\n\n\n      ‫حضانــة ‪ -‬طلــب األم حضانــة األوالد مــع بقــاء عقــد الزوجيــة‪ -‬وجــود‬\n      ‫األوالد مــع األب‪ -‬األم أحــق باحلضانــة مــا لــم تنكــح‪ -‬األم أشــفق علــى‬\n      ‫أوالدهــا‪ -‬أحقيــة األم باحلضانــة واإللــزام بالتســليم‪ -‬احلكــم بالنفــاذ‬\n                                                          ‫املعجــل يف احلضانــة ‪.‬‬\n\n\n\n                ‫‪ .1‬قوله صلى اهلل عليه وسلم ( أنت أحق به ما لم تنكحي ) ‪.‬‬\n                              ‫‪ .2‬املادة ( ‪ ) 199‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n      ‫ادعــت املدعيــة بأنهــا زوجــة للمدعــى عليــه وقــد ســاءت العشــرة بينهمــا‬\n      ‫وقــد خرجــت مــن بيــت زوجهــا ولهــا منــه ثالثــة أوالد ‪ :‬بنــت وعمرهــا‬\n      ‫ســبع ســنوات ‪ ،‬وابــن وعمــره ثــاث ســنوات‪ ،‬وبنــت وعمرهــا ســنة‬\n      ‫واحــدة وتطلــب احلكــم لهــا بحضانــة أوالدهــا‪ ،‬صــادق املدعــى عليــه‬\n      ‫علــى دعــوى املــرأة وأن األوالد اآلن عنــده وهــو غيــر مســتعد إلعادتهــم‬\n      ‫لوالدتهــم املدعيــة‪ ،‬ونظــر ًا لقولــه صلــى اهلل عليــه وســلم (أنــت أحــق بــه‬\n      ‫مــا لــم تنكحــي)‪ ،‬ولكــون األم أشــفق علــى أوالدهــا‪ ،‬احلكــم للمدعيــة‬\n      ‫بحضانــة أوالدهــا املذكوريــن يف الدعــوى واحلكــم علــى املدعــى عليــه‬\n      ‫بتســليمهم للمدعيــة مــع النفــاذ املعجــل‪ ،‬قرر املدعــى عليه اعتراضه على‬\n\n‫‪213‬‬\n\f‫احلكــم بالئحــة اعتراضيــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بالرياض‬\n‫ففــي يــوم الثالثــاء املوافــق‪ 1434/02/26‬ه ـ حضــرت ســعودية اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم () واملعــرف بهــا مــن قبــل أخيهــا حامــل‬\n‫الســجل املدنــي رقــم‪ :‬وادعــت علــى احلاضــر معهــا حامــل الســجل املدنــي‬\n‫رقــم‪ :‬قائلــة يف دعواهــا‪ :‬إن املدعــى عليــه زوجــي وقــد ســاءت العشــرة‬\n‫بيننــا فخرجــت مــن بيتــه قبــل شــهرين ومعــي أوالده منــه ‪ ....‬وعمرهــا‬\n‫ســبع ســنوات ‪ ....‬وعمــره ثــاث ســنوات ‪ ....‬وعمرهــا ســنة وقــد أخذهــم‬\n‫منــي بالقــوة وأطلــب احلكــم لــي بحضانــة أوالدي املذكوريــن وإلزامــه‬\n‫بتســليمهم لــي هــذه دعــواي وباســتجواب املدعــى عليــه قــال‪ :‬مــا ذكرتــه‬\n‫املدعيــة مــن أننــي زوجهــا وأن لــي منهــا األوالد املذكوريــن وأنهــم عنــدي‬\n‫حاليــا فصحيــح ومــا ذكرتــه مــن أنهــا خرجــت مــن بيتي قبل شــهرين وأن‬\n‫العشــرة بيننــا قــد ســاءت وأنــي أخــذت أوالدي منهــا بالقــوة فغيــر صحيــح‬\n‫والصحيــح أنهــا خرجــت مــن بيتــي قبــل ثالثــة أســابيع وأخــذت أوالدي‬\n‫معهــا ثــم ســلمتهم لــي ولســت مســتعدا بإعادتهــم لهــا‪ ،‬هكــذا أجــاب‪،‬‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولقــول النبــي صلــى اهلل عليــه‬\n‫وســلم(أنت أحــق بــه مالــم تنكحــي) ولكــون األم أشــفق علــى أوالدهــا‬\n‫وهــي التــي تعلــم بناتهــا أمــور النســاء وبنــاء علــى املــادة التاســعة والتســعني‬\n‫بعــد املائــة مــن نظــام املرافعــات الشــرعية لــذا فقــد حكمــت للمدعيــة‬\n‫بحضانــة أوالدهــا املذكوريــن يف الدعــوى وحكمــت علــى املدعــى عليــه‬\n‫بتســليمهم للمدعيــة مــع النفــاذ املعجــل بــدون كفالــة وبعــرض احلكــم‬\n\n                                                                                           ‫‪214‬‬\n\f      ‫علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب االســتئناف فأجبتــه لطلبــه‬\n      ‫وأفهمتــه بــأن عليــه املراجعــة يــوم األربعــاء املوافــق ‪1434/2/27‬ه ـ‬\n      ‫الســتالم صــورة مــن صــك احلكــم لالعتــراض عليه خالل مــدة ال تتجاوز‬\n      ‫ثالثــن يومــا مــن تاريــخ املوعــد احملــدد الســتالم الصــك فــإن تأخــر عــن‬\n      ‫ذلــك ســقط حقــه يف تقــدمي الالئحــة االعتراضيــة واكتســب احلكــم‬\n      ‫القطعيــة ‪،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/26‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/06/06‬ه ـ‬\n      ‫وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف بالريــاض وقــد همــش‬\n      ‫علــى ظهــر الصــك مبــا نصــه ( تظهيــرات دائــرة األحــوال الشــخصية‬\n                                   ‫واإلنهــاءات مبحكمــة االســتئناف بالريــاض‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪3449875‬‬\n      ‫وتاريــخ ‪1434/02/27‬ه ـ الصــادر مــن فضيلــة القاضــي يف احملكمــة‬\n      ‫الشــيخ وأصدرنــا القــرار رقــم ‪ 34216424‬وتاريــخ ‪1434/05/19‬ه ـ‬\n      ‫املتضمــن بأنــه لــم يظهــر مــا يوجــب االعتــراض‪ ،‬واهلل املوفــق‪ .‬قاضــي‬\n      ‫اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس‬\n      ‫الدائــرة ختمــه وتوقيعــه) وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                 ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/06/06‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتمييــز‬\n      ‫قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف بالرياض‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n      ‫املســاعد برقــم ‪ 34/664673‬وتاريــخ ‪1434/4/20‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ /‬املســجل برقــم‬\n\n\n‫‪215‬‬\n\f‫‪ 3449875‬وتاريــخ ‪1434/2/27‬ه ـ اخلــاص بدعــوى‪ ..........‬ضــد‪..........‬‬\n‫بشــأن حضانــة أوالد ‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه ‪ .‬حيــث ســبقت دراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n‫فضيلــة القاضــي وأحلقــه علــى الصــك وصــورة ضبطــه بنــاء علــى قرارنــا‬\n‫رقــم ‪ 34173908‬وتاريــخ ‪1434/3/28‬ه ـ لــم يظهــر ما يوجب االعتراض‬\n     ‫‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪216‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":213,"source_page_end":216,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9f15b67cc65ba77f114792d64bc7d6a392827f84e1bb14b4fbc40f8162a187f7","normalized_text_hash":"7996ac7217b6cede0b57bf6ba0b1987879bbe6eedf949c6c130b54f796769ab6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p213-3449875"},{"id":"218c917e-0713-5c47-86a6-4c02f7c10fd0","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب حضانة أوالد -طلب تسليم شهادة مياد وأوراق ثبوتية -األم أحق باحلضانة ما لم تتزوج -عدم حضور املدعى عليه مع تبلغه باملوعد -احلكم لأم بحضانة األوالد دون البلوغ -رد الدعوى بخصوص حضانة األوالد البالغن -اإللزام بتسليم شهادة املياد واألوراق الثبوتية -املطالبة بحضانة البالغ -املطالبة بحضانة من هو دون البلوغ.","document_number":"3455782","case_number":"3332588","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/4","year":"1434","subject":"حضانة -طلب حضانة أوالد -طلب تسليم شهادة مياد وأوراق ثبوتية -األم أحق باحلضانة ما لم تتزوج -عدم حضور املدعى عليه مع تبلغه باملوعد -احلكم لأم بحضانة األوالد دون البلوغ -رد الدعوى بخصوص حضانة األوالد البالغن -اإللزام بتسليم شهادة املياد واألوراق الثبوتية -املطالبة بحضانة البالغ -املطالبة بحضانة من هو دون البلوغ.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3455782 :‬تاريخه ‪1434/3/4 :‬هـ‬\n                         ‫رقم الدعوى ‪3332588:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34268217‬تاريخه‪1434/07/15:‬هـ‬\n\n\n      ‫حضانــة ‪ -‬طلــب حضانــة أوالد ‪ -‬طلــب تســليم شــهادة ميــاد وأوراق‬\n      ‫ثبوتيــة ‪ -‬األم أحــق باحلضانــة مــا لــم تتــزوج ‪ -‬عــدم حضــور املدعــى‬\n      ‫عليــه مــع تبلغــه باملوعــد ‪ -‬احلكــم لــأم بحضانــة األوالد دون البلــوغ‬\n      ‫‪ -‬رد الدعــوى بخصــوص حضانــة األوالد البالغــن ‪ -‬اإللــزام بتســليم‬\n      ‫شــهادة امليــاد واألوراق الثبوتيــة ‪ -‬املطالبــة بحضانــة البالــغ ‪ -‬املطالبــة‬\n                                                   ‫بحضانــة مــن هــو دون البلــوغ‪.‬‬\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم للمــرأة التــي ســألته ‪ ( :‬يــا رســول اهلل أن‬\n      ‫ابنــي هــذا كان بطنــي لــه حــواء وثــدي لــه ســقاء وإن أبــاه طلقنــي وأراد‬\n      ‫أن ينزعــه منــي قــال ‪ ( :‬أنــت أحــق بــه مــا لــم تنكحــي ) رواه أبــو داود عــن‬\n                                             ‫عمــرو بــن شــعيب عــن أبيــه عــن جــده ‪.‬‬\n                     ‫‪ .2‬املادة ( ‪ -10/34‬فقرة هـ ) من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة أنهــا كانــت زوج ـ ًا للمدعــى عليــه وأجنبــت منــه علــى‬\n      ‫فــراش الزوجيــة خمســة أوالد وهــؤالء األوالد بحضانــة املدعــى عليــه‬\n      ‫ســوى األخيــرة وتطلــب حضانــة أوالدهــا كمــا تطلــب تســليم شــهادة‬\n      ‫امليــاد البنتهــا ‪ ...‬وأوراقهــا الثبوتيــة‪ ،‬لــم يحضــر املدعــى عليــه اجللســة‬\n\n‫‪217‬‬\n\f‫مــع تبلغــه مبوعــد اجللســة وتوقيعــه بعلمــه بهــا‪ ،‬ســمعت دعــوى املدعيــة يف‬\n‫مقــر إقامتهــا وجــرى إرســال صــورة مــن ضبــط الدعــوى حملكمــة البلــد‬\n‫الــذي يقيــم فيــه املدعــي عليــه وقــد مت إرســال عدة تعقيبات‪،‬قــررت املرأة‬\n‫تضررهــا مــن ترددهــا علــى احملكمــة بــدون حكــم‪ ،‬مت ســؤال املرأة هل‬\n‫أنــت متزوجــة فأجابــت بقولهــا ال ‪ ،‬ومت ســؤالها هــل ‪ ...‬و‪ ...‬بلغــوا فأجابــت‬\n‫بقولهــا نعــم ومــن دونهــم لــم يبلغــوا‪ ،‬مت ســؤالها مــا هــي األوراق الثبوتيــة‬\n‫التــي تطالــب بهــا فأجابــت شــهادة امليــاد وشــهادة التطعيــم وصــورة مــن‬\n‫ســجل العائلــة‪ ،‬احلكــم بحضانــة ‪ ...‬و‪ ...‬للمدعيــة‪ ،‬رد دعــوى املدعيــة‬\n‫طلــب حضانــة ‪ ...‬و‪ ...‬لبلوغهــم‪ ،‬علــى املدعــى عليــه تســليم شــهادة امليــاد‬\n‫البنتيــه ‪ ...‬وشــهادة التطعيــم وصــورة مــن ســجل العائلــة للمدعيــة‪ ،‬اعتبــار‬\n‫احلكــم حضوريـ ًا نظــر ًا لتبلــغ املدعــى عليــه لشــخصه إلحــدى جلســاته‪،‬‬\n‫بلــغ املدعــى عليــه بنســخة مــن صــورة احلكــم وإفهامــه مــدة االعتــراض‬\n‫النظاميــة وهــي ثالثــون يوم ـ ًا مــن تاريــخ اســتالمه للحكــم‪ ،‬صــدق‬\n                                          ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 3332588‬وتاريــخ‬\n‫‪1433/01/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3383373‬وتاريــخ‬\n‫‪1433/01/12‬ه ـ حضــرت ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم وانتظــر املدعــى عليــه ولــم يحضــر وقــد وردنــا خطــاب امــن‬\n‫احملكمــة العامــة بالدمــام برقــم ‪ 33351832‬يف ‪1433/3/2‬ه ـ ومفــاده‬\n\n                                                                                       ‫‪218‬‬\n\f      ‫مت ابــاغ املدعــى عليــه باحلضــور يف جلســة ‪1433/2/27‬ه ـ وبســؤال‬\n      ‫املدعيــة عــن دعواهــا قالــت ان املدعــى عليــه كان زوجــا لــي واجنبــت‬\n      ‫منــه علــى فــراش الزوجيــة خمســة اوالد وهــم املولــود يف ‪1418/7/19‬ه ـ‬\n      ‫و املولــود يف ‪1420/10/18‬ه ـ و املولــودة يف ‪1422/1/8‬ه ـ و وعمــره‬\n      ‫ســبع ســنوات و وقــد طلقنــي مــن ســنه واالوالد املذكــورون يف حضانتــه‬\n      ‫ســوى األخيــرة فهــي يف حضانتــي اطلــب احلكــم لــي بحضانــة االوالد‬\n      ‫األربعــة املذكوريــن وتســليمي شــهادة ميــاد واوراقهــا الثبوتيــة هــذه‬\n      ‫دعــواي واملدعــى عليــه يقيــم بالدمــام ويعمــل برتبــة عريــف يف الدفــاع‬\n      ‫املدنــي بحــي العدامــة وجوالــه هــو لــذا قــررت بعــث صــورة الضبــط الــى‬\n      ‫محكمــة الدمــام ألخــذ اجابــة املدعــى عليــه حســب الالئحــة هــ‪10/34/‬‬\n      ‫لنظــام املرافعــات الشــرعية ويف جلســة أخــرى حضــرت املدعيــة وقــد‬\n      ‫جــرت الكتابــة الــى محكمــة الدمــام بخطابنــا رقــم ‪ 33662098‬يف‬\n      ‫‪1433/4/11‬ه ـ لســماع اجابــة املدعــى عليــه ولــم يردنــا جوابهــم حتــى‬\n      ‫االن واضافــت املدعيــة بقولهــا ان املدعــى عليــه قــد جعــل اوالدي‬\n      ‫املدعــى بحضانتهــم عنــد عمتهــم وال يهتــم بشــئونهم وال يقــوم بأمورهــم‬\n      ‫وقــد كلمونــي قريبــا وشــكوا الــى حالهــم هكــذا قالــت لــذا قــررت‬\n      ‫التعقيــب علــى خطابنــا الســابق ويف جلســة أخــرى حضــرت املدعيــة‬\n      ‫وانتظــر املدعــى عليــه ولــم يحضــر ولــم يردنــا مــن محكمــة الدمــام‬\n      ‫اجلــواب علــى اســتخالفنا مــع أنــه جــرى التعقيــب علــى ذلــك بخطابنــا رقــم‬\n      ‫‪ 33/1122513‬يف ‪1433/6/16‬ه ـ لــذا ســيجري التعقيــب عليــه مــرة‬\n      ‫أخــرى ويف جلســة أخــرى حضــرت املدعية وقد جرت مخاطبة احملكمة‬\n      ‫العامــة بالدمــام بخطابنــا رقــم ‪ 332272134‬يف ‪1433/12/29‬ه ـ ولــم‬\n      ‫يردنــا رد حتــى االن ثــم قالــت املدعيــة اننــي تضــررت مــن جــراء تــرددي‬\n\n\n‫‪219‬‬\n\f‫علــى احملكمــة لــذا اطلــب احلكــم يف القضيــة ولــو لــم يحضــر املدعــى‬\n‫عليــه ثــم ســالتها عــن اوالدهــا هــل بلغــوا فقالــت نعــم ومــن دونهــم لــم يبلــغ‬\n‫ثــم ســالتها هــل انــت متزوجــه حاليــا فقالــت ال لــم اتــزوج فســالتها ماهــي‬\n‫االوراق الثبوتيــة التــي تطالــب بهــا فقالــت شــهادة ميــاد ابنتــه وشــهادة‬\n‫التطعيــم لهــا وصــورة مــن ســجل العائلــة لــه الــذي يحتــوي علــى اســمها‬\n‫وبعــد النظــر يف الدعــوى ونظــرا لكــون املدعــى عليــه قــد تبلــغ اول مــره‬\n‫ولــم يحضــر دون عــذر مقبــول ونظــرا ملــا طلبتــه املدعيــة مــن احلكــم يف‬\n‫القضيــة والن االصــح مــن اقــوال اهــل العلــم ان االم احــق باحلضانــة مالــم‬\n‫تتــزوج او يبلــغ احملضــون فيختــار لنفســه تأسيســا علــى قولــه صلــى اهلل‬\n‫عليــه وســلم للمــرأة التــي ســالته يــا رســول اهلل ان ابنــي هــذا كان بطنــي‬\n‫لــه حــواء وثــدي لــه ســقاء وان ابــاه طلقنــي واراد ان ينزعــه منــي قــال (انــت‬\n‫احــق بــه مالــم تنكحــي) رواه ابــو داود عــن عمــرو بــن شــعيب عــن ابيــه‬\n‫عــن جــده وامــا البالــغ فانــه يختــار لنفســه فــا يلــزم ان يكــون مــع أي مــن‬\n‫ابويــه والن املدعيــة قــررت انهــا لــم تتــزوج وان ولديهــا الزالــوا لــم يبلغــوا‬\n‫وامــا فقــد بلغــوا فــا يتوجــه االلــزام بشــأنهم يف احلضانــة والن مصلحــة‬\n‫احملضونــة ولوازمهــا تســليم شــهادة امليــاد والتطعيــم وصــورة مصدقــه‬\n‫مــن ســجل العائلــة للمدعــى عليــه الــذي فيــه اســم ابنتــه لذلــك كلــه‬\n‫فقــد حكمــت علــى املدعــى عليــه ان يســلم ولديــه للمدعيــة لتحضنهــم‬\n‫وعليــه ان يســلمها شــهادة ميــاد ابنتــه ‪ ...‬وشــهادة التطعيــم لهــا وصــورة‬\n‫مــن ســجل العائلــة لــه الــذي يحتــوي علــى اســم ابنتــه وردت دعــوى املدعيــة‬\n‫بحضانــة لبلوغهــم وبعرضــه علــى املدعيــة قــررت القناعــة بــه ويعتبــر هــذا‬\n‫احلكــم حضوريــا نظــرا لتبلــغ املدعــى عليــه بشــخصه إلحــدى جلســاته‬\n‫وســوف يبلــغ بنســخة منــه إلبــداء اعتراضــه عليــه ان رغــب ذلــك ويفهــم‬\n\n\n                                                                                           ‫‪220‬‬\n\f      ‫بتعليمــات االســتئناف ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/30‬ه ـ‬\n      ‫احلمد هلل وحده وبعد ففي يوم السبت املوافق‪ 1434/06/24‬هـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 10.5‬وفيهــا حضــرت املدعيــة وقــد وردتنــا املعاملــة مــن‬\n      ‫محكمــة االســتئناف بخطابهــا رقــم ‪ 3383373‬يف ‪1434/6/11‬ه ـ‬\n      ‫مرفــق بــه القــرار رقــم ‪ 34234363‬يف ‪1434/6/7‬ه ـ ونــص احلاجــة منــه‬\n      ‫بعــد دراســة القضيــة تقــرر باألكثريــة إعادتهــا حلاكمها لكــون املدعى‬\n      ‫عليــه ذكــر أنــه يوجــد أبنــاء ألخــت املدعيــة يف املنــزل نفســه وهــم كبــار‬\n      ‫يف الســن وال يطمئــن علــى ابنتــه مــن التعــدي مــن قبــل هــؤالء األبنــاء‬\n      ‫أ‪.‬ه ـ وبعرضــه علــى املدعيــة قالــت إن أختــي تســكن يف بيــت مســتقل‬\n      ‫بجانــب بيتــي وقــد أســكننا والدنــا كل واحــده يف بيــت شــعبي مســتقل‬\n      ‫مبنافعــه وأختــي ال تســكن معــي يف البيــت نفســه وليــس لهــا إال ابنــان‬\n      ‫فقــط أحدهمــا وعمــره عشــر ســنوات والثانــي وعمــره خمــس ســنوات‬\n      ‫وبقيــة أوالدهــا بنــات هكــذا قــررت لــذا لــم يظهــر لــي خــاف مــا قضيــت‬\n      ‫بــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف ‪1434/06/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/07/30‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12.15‬وفيهــا فقــد عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف برقــم ‪ 3383373‬يف ‪1434/7/22‬ه ـ وبرفقهــا‬\n      ‫القــرار رقــم ‪ 34268217‬يف ‪1434/7/15‬ه ـ واملــدون علــى ظهــر الصــك‬\n      ‫باملوافقــة علــى احلكــم لــذا جــرى إحلاقــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/30‬هـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n\n\n‫‪221‬‬\n\f‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 3383373‬وتاريــخ ‪1434/7/8‬هـ ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ ..........‬القاضــي باحملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم‪ 3455782‬وتاريــخ ‪1434/3/4‬ه ــ‪،‬‬\n‫املتضمــن دعــوى املــرأة ضــد بشــأن حضانــة األوالد‪ ،‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة‪ ،‬تقــررت املوافقــة علــى احلكــم‬\n‫بعــد اإلحلــاق األخيــر املبنــي علــى قــرار املالحظــة ‪ ،‬واهلل املوفــق ‪ .‬وصلــى‬\n                        ‫اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪222‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":217,"source_page_end":222,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1cd704a0bf537991fb2db62be79044ad0d74360ddd5a7b89c088b905f0aafe19","normalized_text_hash":"d5b13d1db9955dd56cd3cbf1ee5b1e85d21c1c9447efc17f28ee0012ca1a3924","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p217-3455782"},{"id":"97a0812a-a4d2-5fa5-b0c4-eb4d46c80130","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -حضانة من دون السابعة -طلب األم حضانة األوالد - األم أحق باحلضانة ما لم تنكح -احلكم بأحقية األم باحلضانة -احلكم بحضانة ابن عمره سبع سنوات لوالدته من دون تخيير بن األب و األم لصالحية األم خالف ا لقاعدة التخيير .","document_number":"34228116","case_number":"3464499","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/3","year":"1434","subject":"حضانة -حضانة من دون السابعة -طلب األم حضانة األوالد - األم أحق باحلضانة ما لم تنكح -احلكم بأحقية األم باحلضانة -احلكم بحضانة ابن عمره سبع سنوات لوالدته من دون تخيير بن األب و األم لصالحية األم خالف ا لقاعدة التخيير .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34228116 :‬تاريخه ‪1434/6/3 :‬هـ‬\n                          ‫رقم الدعوى ‪3464499:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34237011‬تاريخه‪1434/06/11 :‬هـ‬\n\n\n      ‫حضانــة ‪ -‬حضانــة مــن دون الســابعة ‪ -‬طلــب األم حضانــة األوالد ‪-‬‬\n      ‫األم أحــق باحلضانــة مــا لــم تنكــح ‪ -‬احلكــم بأحقيــة األم باحلضانــة‬\n      ‫‪ -‬احلكــم بحضانــة ابــن عمــره ســبع ســنوات لوالدتــه مــن دون تخييــر‬\n                 ‫بــن األب و األم لصالحيــة األم خالفـ ًـا لقاعــدة التخييــر ‪.‬‬\n\n\n\n\n                   ‫قوله صلى اهلل عليه وسلم ( أنت أحق به ما لم تنكحي ) ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة بأنهــا كانــت زوجــة للمدعــى عليــه ومت فســخ نكاحهــا‬\n      ‫منــه يف تاريــخ ‪1434/6/28‬ه ـ وقــد أجنبــت منــه علــى فــراش الزوجيــة‬\n      ‫أربعــة مــن األوالد األول ذكــر وعمــره ســبع ســنوات والثانــي ذكــر‬\n      ‫وعمــره ســت ســنوات والثالــث بنــت وعمرهــا خمــس ســنوات والرابــع‬\n      ‫ذكــر وعمــره ســنة وأربعــة أشــهر وولديهــا الثالــث والرابــع يف رعايتهــا‬\n      ‫وحضانتهــا منــذ ســنتني وهــي لــم تتــزوج بعــد فســخ نكاحهــا مــن املدعــى‬\n      ‫عليــه وتطلــب يف دعواهــا احلكــم لهــا باحلضانــة‪ ،‬بســؤال املدعــى عليــه‬\n      ‫صــادق علــى مــا ذكرتــه وال يوافــق علــى حضانتهــا لولديهــا املذكوريــن‬\n      ‫وطلــب حضانتهمــا‪ ،‬بعــرض ذلــك علــى املدعيــة قالــت إنــي أطالــب‬\n      ‫بحضانتهمــا لصغــر ســنهما‪ ،‬بنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة‪،‬‬\n\n‫‪223‬‬\n\f‫ونظــر ًا لقولــه صلــى اهلل عليــه وســلم ( أنــت أحــق بــه مــا لــم تنكحــي)‬\n‫وحلصــول التنــازع بينهمــا باحلضانــة‪ ،‬ومطالبة املدعــى عليه بهما‪،‬احلكم‬\n‫بحضانــة الولديــن املذكوريــن للمدعيــة‪ ،‬قــرر املدعــى عليــه اعتراضــه‬\n‫علــى احلكــم بالئحــة اعتراضيــة فأفهــم بتعليمــات االســتئناف‪ ،‬صــدق‬\n                                       ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 3464499‬وتاريــخ ‪ 1434/02/09‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34323270‬وتاريــخ ‪ 1434/02/09‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/06/03‬ه ـ افتتحــت اجللســة الســاعة التاســع‬\n‫وعشــر دقائــق وكان الوقــت احملــدد لهــا هــو الســاعة الثامنــة والنصــف‬\n‫وفيهــا حضــرت‪ .......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬‬\n‫واملعــرف بهــا مــن قبــل أخيهــا ‪.......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ،.......‬وادعــت علــى علــى احلاضــر معهــا ‪.......‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬قائلــة يف دعواهــا ان املدعــى‬\n‫عليــه كان زوجــي مت فســخ نكاحــي منــه يف تاريــخ ‪1433/6/28‬ه ـ‬\n‫وقــد اجنبــت لــه علــى فــراش الزوجيــة أربعــة مــن األوالد ‪.......‬وعمــره ســبع‬\n‫ســنوات والثانــي ‪ .......‬وعمــره ســت ســنوات والثالــث ‪.......‬وعمرهــا خمــس‬\n‫ســنوات والرابــع ‪ .......‬وعمــره ســنة وأربعــة اشــهر وولــدي ‪ .......‬و‪ .......‬يف‬\n‫رعايتــي وحتــت حضانتــي منــذ ســنتني تقريبــا وأنــا لــم اتــزوج بعــد فســخ‬\n‫نكاحــي منــه واننــي أطلــب يف دعــواي هــذه احلكــم لــي بحضانــة ولــدي‬\n\n                                                                                      ‫‪224‬‬\n\f      ‫املذكوريــن ‪.......‬و‪ .......‬هــذه دعــواي وبســؤال املدعــى عليــه قــال كل‬\n      ‫مــا ذكرتــه املدعيــة يف دعواهــا صحيــح وانــا ال أوافــق علــى حضانتهــا‬\n      ‫لهمــا وأطلــب حضانتهمــا لــي هــذا مــا لــدي ‪ ،‬وبعــرض ذلــك علــى املدعيــة‬\n      ‫قالــت اننــي اطالــب بحضانتهمــا لــي لصغــر ســنهما هــذا مــا لــدي ‪ ،‬وبنــاء‬\n      ‫علــى مــا ســبق مــن الدعــوى واالجابــة ‪ ،‬ولقولــه صلــى اهلل عليــه وســلم‪:‬‬\n      ‫(انــت أحــق بــه مــا لــم تنكحــي) ‪ ،‬وحلصــول التنــازع بينهمــا باحلضانــة‬\n      ‫ومطالبــة املدعــى عليــه بهــا ‪ ،‬لذلــك كلــه فقــد حكمــت بحضانــة‬\n      ‫الولديــن املذكوريــن ‪.......‬و‪ .......‬للمدعيــة وبعــرض احلكــم علــى املدعــى‬\n      ‫عليــه ‪ ،‬قــرر عــدم القناعــة وطلــب رفــع املعاملــة إلــى محكمــة االســئناف‬\n      ‫‪ ،‬فأجبتــه إلــى طلبــه وأفهمتــه بــأن ســوف يســلم صــورة مــن نســخة‬\n      ‫احلكــم هــذا اليــوم وأن لــه مهلــة ثالثــن يومــا مــن تاريــخ اســتالمه صــورة‬\n      ‫احلكــم لتقــدمي اعتراضــة ‪ ،‬فــإذا انتهــت املهلــة ولــم يتقــدم باعتراضــه‬\n      ‫ســقط حقــه يف االعتــراض واصبــح احلكــم نافــذا ‪ ،‬وبــه ختمــت اجللســة‬\n      ‫يف متــام الســاعة التاســعة والنصــف ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/03‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/06/20‬ه ـ‬\n      ‫افتتحت اجللســة الســاعة ‪ 12 : 30‬وقد عادت املعاملة إلينا من محكمة‬\n      ‫االســتئناف باخلطــاب رقــم ‪ 341360094‬يف ‪1434/6/14‬ه ـ وبرفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة الثانيــة املختصــة بنظــر قضايــا األحــوال‬\n      ‫الشــخصية واالنهــاءات رقــم ‪ 34237011‬يف ‪1434/6/11‬ه ـ املتضمــن‪:‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫تقــرر الدائــرة املصادقــة علــى احلكــم ‪ .‬وعليــه فجــرى التهميش مبوجبه‪،‬‬\n      ‫وبــه ختمــت اجللســة الســاعة ‪ . 12 : 40‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n\n\n‫‪225‬‬\n\f     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد برقــم ‪ 34323270‬وتاريــخ ‪1434/6/5‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪....... /‬‬\n‫املســجل برقــم ‪34228116‬وتاريــخ ‪1434/6/3‬ه ـ اخلــاص بدعــوى ‪....... /‬‬\n‫ضــد‪ ....... /‬يف قضيــة حضانــة‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫مباهــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ‪،‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":223,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"32b786979a183e56aaccc142afcacb8b5f478fe601a4aa08ff9b4605b43aa8a9","normalized_text_hash":"5aacfa2bee15e084bb671eac7782ef906703f6d0a79760674ec795f76cdc8e2c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p223-34228116"},{"id":"0d955932-b238-5e2e-b23e-1764150080de","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -األم أحق بحضانة األوالد ما لم تتزوج -تقدير األحق باحلضانة وحتديد مدة الزيارة عن طريق قسم اخلبراء -النظر يف طلب عارض بالزيارة والبت فيه -رد الدعوى واحلكم لألم باحلضانة وإلزامها بتمكن املدعى لزيارة ابنتيه املذكورتن .","document_number":"33417800","case_number":"32379563","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/23","year":"1434","subject":"حضانة -األم أحق بحضانة األوالد ما لم تتزوج -تقدير األحق باحلضانة وحتديد مدة الزيارة عن طريق قسم اخلبراء -النظر يف طلب عارض بالزيارة والبت فيه -رد الدعوى واحلكم لألم باحلضانة وإلزامها بتمكن املدعى لزيارة ابنتيه املذكورتن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33417800:‬تاريخه‪1433/9/23:‬هـ‬\n                        ‫رقم الدعوى‪32379563:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34264426‬تاريخه‪1434/7/10:‬هـ‬\n\n\n      ‫حضانــة ‪ -‬األم أحــق بحضانــة األوالد مــا لــم تتــزوج ‪ -‬تقديــر األحــق‬\n      ‫باحلضانــة وحتديــد مــدة الزيــارة عــن طريــق قســم اخلبــراء ‪ -‬النظــر يف‬\n      ‫طلــب عــارض بالزيــارة والبــت فيــه ‪ -‬رد الدعــوى واحلكم لألم باحلضانة‬\n                         ‫وإلزامهــا بتمكــن املدعــى لزيــارة ابنتيــه املذكورتــن ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (أنــت أحــق بــه مــا لــم تنكحــي) أخرجــه‬\n                 ‫أبــو داود واإلمــام أحمــد واحلاكــم وصححــه ووافقــه الذهبــي‪.‬‬\n      ‫‪ .2‬جــاء يف زاد املعــاد ص (‪ )390‬مــا نصــه (أن هــذا احلديــث دل علــى أنــه‬\n      ‫إذا افتــرق األبــوان وبينهمــا ولــد فــاألم أحــق بــه مــن األب مــا لــم يقــم‬\n      ‫بــاألم مــا مينــع تقدميهــا أو بالولــد وصــف يقتضــي تخييــره وهــذا مــا ال‬\n                                                                   ‫يعــرف فيــه نــزاع)‪.‬‬\n                                   ‫‪ .3‬املادة (‪/79‬هـ) من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليهــا بأنــه ســبق أن طلــق املدعــى عليهــا‬\n      ‫طالقــا بائن ـ ًا وقــد رزق منهــا بابنتــن وأنهــا تســكن اآلن لوحدهــا يف‬\n      ‫بيــت ملــك لهــا ومعهــا ابنتاهمــا املذكورتــان آنفــا ويطلــب احلكــم‬\n      ‫لــه بحضانــة هاتــن االبنتــن هكــذا ادعــى‪ ،‬أجابــت املدعــى عليهــا‬\n\n‫‪227‬‬\n\f‫باملصادقــة علــى الطــاق واجنابهــا منــه االبنتــن املذكورتــن وال توافقــه‬\n‫علــى طلبــه حضانتهمــا نظــرا ألنهــا مــا زالــت غيــر متزوجــة وأنهــا امــرأة‬\n‫مســتقيمة وتســكن يف بيــت مملــوك لهــا وأن املدعــي ســوف يســكنهما‬\n‫عنــد زوجــة لــه وتخشــى علــى ابنتيهــا منــه ال ســيما أن أحــد البنتــن بهــا‬\n‫إعاقــة‪ ،‬صــادق املدعــي علــى اإلعاقــة وعلــى أن البنتــن ستســكنان مــع‬\n‫زوجتــه وعلــى أن املدعــى عليهــا لــم تتــزوج‪ ،‬جــرى الكتابــة للمستشــفى‬\n‫لإلفــادة بتقريــر مفصــل عــن حالــة البنــت فــورد جوابهــم بأنهــا تعانــي مــن‬\n‫استســقاء خلقــي بالعمــود الفقــري أدى إلــى شــلل غيــر تــام بالطرفــن‬\n‫الســفليني مــع صعوبــة شــديدة باملشــي مــع وجــود عيــوب بالقلــب وأنهــا‬\n‫حتتــاج إلــى رعايــة خاصــة‪ ،‬ونظــر ًا ألن املدعــى عليهــا لــم تتــزوج وقــد‬\n‫صــادق املدعــي علــى ذلــك‪ ،‬وألن املدعــي لــم يثبــت عــدم صالحيــة‬\n‫املدعــى عليهــا حلضانــة ابنتيهــا ولقــرار هيئــة اخلبــراء (تــرى أن تكــون‬\n‫حضانــة البنتــن لــأم مــا لــم تتــزوج)‪ ،‬وملــا قــرره أهــل العلــم مــن أن أحــق‬\n‫النــاس باحلضانــة هــي األم لقولــه عليــه الصــاة والســام‪ (( :‬أنــت أحــق‬\n‫بــه مــا لــم تنكحــي)) أخرجــه أبــو داود وأحمــد واحلاكــم‪ ،‬وألن املدعــي‬\n‫قــد قــدم طلب ـ ًا عارض ـ ًا يطلــب فيــه حتديــد موعــد لــه لزيــارة ابنتيــه‪ ،‬ملــا‬\n‫تقــدم احلكــم مبــا يلــي أو ًال رد دعــوى املدعــي وقــرر القاضــي أن املدعــى‬\n‫عليهــا هــي األحــق بحضانــة ابنتيهــا مــا لــم يقــم املدعــى عليهــا مــا مينــع مــن‬\n‫تقدميهــا أو بــكل واحــدة مــن هاتــن البنتــن وصــف يقتضــي تخييرهمــا‬\n‫ثاني ـ ًا إلــزام املدعــى عليهــا بتمكــن املدعــي مــن زيــارة ابنتيــه مرتــن‬\n‫يف األســبوع بحيــث يأخذهمــا الســاعة اخلامســة مســاء ويعيدهمــا إلــى‬\n‫والدتهمــا املدعــى عليهــا الســاعة التاســعة مســاء كل يــوم أحــد وأربعــاء‪،‬‬\n                                     ‫اعتــرض املدعــي بالئحــة‪ ،‬صــدق احلكــم‪.‬‬\n\n\n                                                                                            ‫‪228‬‬\n\f      ‫احلمــد هلل وحــده وبعــد يف يــوم اإلثنــن املوافــق ‪1432/10/28‬ه ـ لــدي أنــا‬\n      ‫‪ ...‬القاضــي باحملكمــة العامــة بعنيــزة افتتحــت اجللســة يف وقتهــا احملــدد‬\n      ‫لســماعها يف الســاعة التاســعة صباحــا للنظــر يف الدعــوى املقدمــة مــن ‪...‬‬\n      ‫ضد ‪...‬واملقيدة يف هذه احملكمة برقم ‪ 32/037769‬يف ‪1432/8/11‬هـ‬\n      ‫واحملالــة لنــا بشــرح فضيلــة الرئيــس والتــي ســبق أن صــدر فيهــا صــك‬\n      ‫احلكــم رقــم ‪ 6/47‬يف ‪1431/11/8‬ه ـ والــذي نقــض مــن الدائــرة‬\n      ‫املختصــة بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة‬\n      ‫اإلســتئناف مبنطقــة القصيــم رقــم ‪/597‬ش‪/‬ن يف ‪1432/7/27‬ه ـ‬\n      ‫واملقــرر فيــه أيضــا إحالتهــا إلــى قــاض آخــر للنظــر فيهــا مــن جديــد أ‪.‬هــ‪.‬‬\n      ‫وقــد حضــر فيهــا ‪...‬ســعودي مبوجــب الســجل رقــم ‪...‬وادعــى علــى‬\n      ‫احلاضــرة معــه ‪...‬ســعودية بالســجل رقــم ‪ ...‬واملعــرف بهــا مــن قبــل املدعــي‬\n      ‫قائــا يف حتريــر دعــواه لقــد ســبق أن طلقــت املدعــى عليها هــذه احلاضرة‬\n      ‫طالقــا بائنــا يف ‪1430/5/22‬ه ـ وقــد رزقــت منهــا بابنتــن همــا ‪...‬املولودة‬\n      ‫يف ‪1420/11/14‬ه ـ و‪ ...‬املولــودة يف ‪1425/5/8‬ه ـ وهــي تســكن اآلن‬\n      ‫لوحدهــا يف بيــت ملــك لهــا يف حــي ‪ ...‬بعنيــزة ومعهــا ابنتــاي املذكورتــن‬\n      ‫آنفــا أطلــب احلكــم لــي بحضانــة هاتــن اإلبنتــن هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليهــا عمــا جــاء يف دعــوى املدعــي أجابــت قائلــة ماذكــره‬\n      ‫املدعــي مــن طالقــه لــي وأن لــي منــه اإلبنتــن املذكورتــن يف الدعــوى‬\n      ‫فهــذا صحيــح وأمــا ماطالــب بــه مــن طلبــه احلضانــة لهمــا فأنــا ال أوافــق‬\n      ‫علــى ذلــك ولــن أتخلــى عنهمــا نظــرا ألننــي مازلــت غيــر متزوجــة وأنــا‬\n      ‫امــرأة مســتقيمة وأســكن يف بيــت مملــوك لــي وأمــا املدعــي فإنــه ســوف‬\n\n‫‪229‬‬\n\f‫يســكنهما عنــد زوجــة لــه وأنــا أخشــى علــى ابنتــي منــه ال ســيما أن ابنتي‬\n‫‪...‬معاقــة هكــذا أجابــت وبعــرض ذلــك علــى املدعــي قــال إننــي ال أوافــق‬\n‫علــى أن تكــون املدعــى عليهــا حاضنــة إلبنتــي نظــرا ألنهــا امــرأة ســليطة‬\n‫اللســان وذات شــخصية قويــة وهــذا يؤثــر علــى ابنتــي وعلــى نفســياتهما‬\n‫وأمــا ماذكرتــه املدعــى عليهــا مــن أن ابنتــي ‪...‬معاقــة فهــذا صحيــح‬\n‫كمــا أن ماذكرتــه أيضــا مــن أننــي ســوف أقــوم بإســكانهما عنــد‬\n‫زوجتــي ‪...‬والتــي لــي منهــا عشــرة أوالد فهــذا صحيــح ولكــن لــن يصــل‬\n‫ابنتــي منهــا أي أذى إن شــاء اهلل ثــم رفعــت اجللســة ويف يــوم الســبت‬\n‫املوافــق ‪1433/1/8‬ه ـ افتتحــت اجللســة يف الســاعة العاشــرة صباحــا‬\n‫وفيهــا حضــر املدعــي ولــم حتضــر املدعــى عليهــا وال مــن ينــوب عنهــا ولــم‬\n‫تقــدم عــذرا لذلــك ثــم جــرى االطــاع منــا علــى بطاقــة عائلــة املدعــي‬\n‫فتبني منها أن ميالد ‪...‬يف ‪1425/5/8‬هـ وأن ميالد ‪...‬يف ‪1420/11/14‬هـ‬\n‫ثــم جــرى ســؤال املدعــي عــن نوعيــة إعاقــة ابنتــه ‪...‬فقــال إن لديهــا ضمــور‬\n‫يف قدمهــا اليمنــى وهــي تســتطيع املشــي مــن دون عصــا ثــم رفعــت اجللســة‬\n‫لســؤال املدعــى عليهــا حــن حضورهــا عــن نوعيــة إعاقــة ابنتهــا ‪...‬أيضــا‬\n‫وطلــب تقريــر طبــي منهمــا عــن إعاقتهــا وكــذا ســؤال املدعــى عليهــا هــل‬\n‫هــي متزوجــة أم ال مــع عــرض الصلــح عليهمــا قــدر املســتطاع فــإن لــم‬\n‫يصطلحــا فيســأل املدعــي عــن قدحــه يف املدعــى عليهــا مفصــا ثــم‬\n‫رفعــت اجللســة ويف يــوم األحــد ‪1433/2/7‬هـ افتتحت اجللســة يف الســاعة‬\n‫احلاديــة عشــر صباحــا وفيهــا حضــر املدعــي واملدعــى عليهــا واملعــرف بهــا‬\n‫مــن قبــل املدعــي ثــم جــرى ســؤال املدعــى عليهــا عمــا ذكــره املدعــي عــن‬\n‫اعاقــة ابنتهمــا ‪...‬فقالــت إن ماذكــره املدعــي ‪ ...‬غيــر صحيــح نظــرا ألن‬\n‫ابنتنــا ‪...‬تعانــي مــن مــرض يســمى الصلــب املشــقوق وهــو ضعــف عــام يف‬\n\n\n                                                                                      ‫‪230‬‬\n\f      ‫الظهــر واألطــراف والتســتطيع املشــي إال مبســاعدة مــن أحــد ثــم جــرى‬\n      ‫ســؤالها هــل أنــت متزوجــة حاليــا فقالــت إننــي مازلــت غيــر متزوجــة‬\n      ‫وعنــدي أصــل صــك طالقــي مــن املدعــي مثبــت فيــه أننــي مازلــت مطلقــة‬\n      ‫حيــث لــم يهمــش عليــه بزواجــي مــن أحــد ثــم جــرى عــرض الصلــح علــى‬\n      ‫املتداعيــن قــدر املســتطاع وافهامهمــا بــأن مراعــاة مصلحــة ابنتيهمــا‬\n      ‫أمــر مهــم ومؤثــر مســتقبال عليهــا فأصــر كل واحــد مهمــا علــى موقفــه‬\n      ‫وطلبــه ثــم أفهمتهمــا بضــرورة احضــار تقريــر طبــي إلبنتهمــا ‪...‬وأفهمــت‬\n      ‫املدعــى عليهــا بإحضــار أصــل طــاق املدعــي لهــا ففهمــا ذلــك واســتعدا‬\n      ‫بــه ثــم رفعــت اجللســة ويف يــوم الثالثــاء املوافــق ‪1433/3/15‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة التاســعة صباحــا وفيهــا حضــر املدعــي واملدعــى‬\n      ‫عليهــا واملعــرف بهــا مــن قبــل املدعــي ثــم أبــرزت املدعــى عليهــا صــورة مــن‬\n      ‫صــك الطــاق الصــادر من هــذه احملكمة برقم ‪ 6/8‬يف ‪1430/5/22‬هـ‬\n      ‫املثبت فيه ‪...‬لزوجته ‪...‬طلقة واحدة طالق السنة بتاريخ ‪1430/5/22‬هـ‬\n      ‫وأنهــا الطلقــة الثالثــة وأنهــا بانــت منــه بينونــة كبــرى أ ‪ .‬ه ـ ‪ .‬ثــم طلبــت‬\n      ‫منهــا احضــار أصــل صــك الطــاق فاســتعدت بذلــك وطلبــت امهالهــا إلــى‬\n      ‫جلســة أخــرى وقــررت قائلــة إننــي لــم أســتطع احضــار تقريــر مفصــل عــن‬\n      ‫حالــة ابنتنــا ‪...‬وأطلــب امهالــي إلحضــاره يف اجللســة القادمــة فأجيــب‬\n      ‫لذلــك ثــم رفعــت اجللســة بعــد افهــام املدعــى عليهــا بــأن عليهــا احضــار‬\n      ‫التقريــر الطبــي املطلــوب وأصــل صــك الطــاق وخطــاب محــرر تبــن فيــه‬\n      ‫ســبب امتناعهــا بــأن تكــون احلضانــة للمدعــي وبعــد افهــام املدعــي‬\n      ‫أيضــا بــأن عليــه احضــار خطــاب محــرر يبــن فيــه ســبب امتناعــه بــأن‬\n      ‫تكــون احلضانــة للمدعــى عليهــا ويف يوم الســبت املوافق ‪1433/4/24‬هـ‬\n      ‫افتتحــت اجللســة يف الســاعة التاســعة والنصــف صباحــا وفيهــا حضــر‬\n\n\n‫‪231‬‬\n\f‫املدعــي ولــم حتضــر املدعــى عليهــا ولــم حتضــر املطلــوب منهــا يف اجللســة‬\n‫الســابقة وهــو أصــل صــك طالقهــا وتقريــر طبــي مفصــل عــن حالــة ابنتهــا‬\n‫‪...‬وســبب امتناعهــا بــأن تكــون احلضانــة للمدعــي ثــم رفعــت اجللســة‬\n‫لطلبهــا مــرة أخــرى وبعــد ويف يــوم الثالثــاء املوافــق ‪1433/06/3‬ه ـ‬\n‫افتتحــت اجللســه يف الســاعة التاســعة والنصــف صباح ـ ًا وفيهــا حضــر‬\n‫املدعــي ‪...‬واملدعــى عليهــا ‪...‬ثــم قــررت املدعــى عليهــا قائلــة إن ســبب‬\n‫مطالبتــي بــرد دعــوى املدعــي هــو أن ابنتــي (‪ )...‬و (‪ )...‬منــذ والدتهمــا‬\n‫وهمــا عنــدي وأنــا أنفــق عليهمــا كمــا أننــي لم أتزوج حتــى اآلن ومتفرغة‬\n‫لتربيتهــن وأنــا أولــى مــن والدهمــا ألنــه لــو حكــم باحلضانــة لــه فلــن‬\n‫يراعاهمــا بنفســه بــل ســترعاهما زوجتــه التــي لهــا عشــرة أوالد وســبعة‬\n‫أحفــاد هــذه هــي أســباب مطالبتــي بــرد الدعــوى ثــم أبــرزت املدعــى‬\n‫عليهــا أصــل صــك الطــاق املثبــت نصــه يف اجلســلة املنعقــدة يف‬\n‫‪1433/03/15‬ه ـ فوجدتــه مطابقـ ًا لتلــك الصــورة التــي أبرزتهــا املدعــى‬\n‫عليهــا يف تلــك اجللســة ثــم قــررت قائلــه إننــي لــم أســتطع احلصــول علــى‬\n‫تقريــر طبــي مفصــل عــن حالــة ابنتــي (‪ )...‬حتــى اآلن وقــد طلــب مديــر‬\n‫مستشــفى امللــك ســعود أن يتــم مخاطبتــه رســمي ًا لتزويــد فضيلتكــم‬\n‫بالتقريــر املطلــوب ثــم رفعــت اجللســة ويف يــوم األحــد املوافــق‬\n‫‪1433/7/20‬ه ـ افتتحــت اجللســة يف الســاعة االعاشــرة والنصــف صباح ًا‬\n‫وفيهــا حضــر املدعــي ‪...‬ولــم حتضــر املدعــى عليهــا وال مــن ينــوب عنهــا‬\n‫ولــم تقــدم عــذر ًا لذلــك رغــم تبلغهــا بهــذا املوعــد يف ضبــط القضيــة ثــم‬\n‫رفعــت اجللســة إلحضارهــا بنــاء علــى املــادة (‪ )101‬مــن نظــام املرافعــات‬\n‫الشــرعية ولوائحــه التنفيذيــة ويف يــوم الســبت املوافــق ‪1433/9/23‬ه ـ‬\n‫افتتحت اجللســة يف الســاعة احلادية عشــر صباحا وفيها حضر املدعي‪...‬‬\n\n\n                                                                                     ‫‪232‬‬\n\f      ‫ولــم حتضــر املدعــى عليهــا ‪...‬ولــم يردنــا أي إفــادة مــن شــرطة عنيــزة علــى‬\n      ‫خطابنــا رقــم (‪ )331371701‬يف (‪1433/7/21‬هــ) املطلوب فيه إحضار‬\n      ‫املدعــى عليهــا بنــاء علــى املــادة (‪ )101‬مــن نظــام املرافعــات الشــرعية‬\n      ‫ولوائحــه التنفيذيــة وقــد وردنــا يف هــذه اجللســة خطــاب ســعادة مديــر‬\n      ‫مستشفى امللك سعود بعنيزة رقم ‪/5811‬خ‪ 45/36/‬يف ‪1433/6/22‬هـ‬\n      ‫جوابــا علــى خطابنــا رقــم (‪ )331043960‬يف (‪1433/6/3‬هــ) املطلــوب‬\n      ‫فيــه إفادتنــا بتقريــر مفصــل عــن ‪...‬وقــد أرفــق مــع خطــاب ســعادته‬\n      ‫التقريــر الطبــي بنفــس رقــم اخلطــاب يف ‪1433/6/22‬ه ـ وتبــن أنهــا‬\n      ‫تعانــي مــن استســقاء خلقــي بالعمــود الفقــري أدى إلــى شــلل غيــر تــام‬\n      ‫بالطرفــن الســفليني مــع صعوبــة شــديدة باملشــي مــع وجــود عيــوب‬\n      ‫بالقلــب وأنهــا حتتــاج إلــى رعايــة خاصــة أ‪.‬هــ‪ .‬كمــا قــرر املدعــي ‪...‬طلبــا‬\n      ‫عارضــا مت تقييــده برقــم ‪ 331050503‬يف ‪1433/6/4‬ه ـ مت إرفاقــه‬\n      ‫باملعاملــة يتضمــن مطالبــة بتحديــد موعــد لــه لزيــارة ابنتيــه ‪ ...‬و‪ ...‬فبنــاء‬\n      ‫علــى ماســبق مــن الدعــوى واإلجابــة ونظــرا ألن املدعــى عليهــا لــم تتــزوج‬\n      ‫حتــى اآلن وقــد صــادق املدعــي علــى ذلــك ويؤكــد ذلــك تقدميهــا ألصــل‬\n      ‫الطــاق اخلــاص بهــا مــن زوجهــا املدعــي علــى أن املدعــى عليهــا تســكن‬\n      ‫يف بيــت لوحدهــا ومصادقتــه علــى أنــه لــو حكــم لــه باحلضانــة فإنــه‬\n      ‫ســيجعل ابنتيــه لــدى زوجتــه وألنــه جــرى التأكــد مــن ميــاد هاتــن‬\n      ‫االبنتــن ونوعيــة إعاقــة ‪...‬وألن املدعــي لــم يثبــت عــدم صالحيــة املدعــى‬\n      ‫عليهــا حلضانــة ابنتيهــا وألنــه جــرى عــرض الصلــح عليهمــا فلــم يصطلحــا‬\n      ‫وألنــه ســبق أن قــررت هيئــة اخلبــراء بقرارهــا رقــم (‪/3‬هــ)‬\n      ‫يف(‪1431/1/2‬هـ)أنهــا تــرى أن تكــون حضانــة البنتــن لــأم مــا لــم‬\n      ‫تتــزوج أ‪.‬هــ‪ .‬ونظــر ًا ملــا قــرره أهــل العلــم مــن أن أحــق النــاس باحلضانــة هي‬\n\n\n‫‪233‬‬\n\f‫إالم لقولــه عليــه الصــاة والســام ‪ ((:‬أنــت أحــق بــه مــا لــم تنكحــي))‬\n‫أخرجــه أبــو داود (‪ )2276‬يف (ك الطــاق ‪ /‬بــاب مــن أحــق بالولــد )‬\n‫واإلمــام أحمــد برقــم (‪ )6707‬واحلاكــم (‪ )207/2‬وصححــه ووافقــه‬\n‫الذهبــي وقــد قــرر ابــن القيــم صحــة هــذا احلديــث يف كتابــه زاد املعــاد‬\n‫ص (‪ )389‬ط مؤسســة الرســالة وذكــر أيضـ ًا أن هــذا هــو مذهــب األئمة‬\n‫األربعــة ثــم قــرر رحمــه اهلل يف ص (‪ )390‬مــا نصــه ‪ ((:‬أن هــذا احلديــث‬\n‫دل علــى أنــه إذا افتــرق األبــوان وبينهمــا ولــد فــاألم أحــق بــه مــن األب مــا‬\n‫لــم يقــم بــاألم مــا مينــع تقدميهــا أو بالولــد وصــف يقتضــي تخييــره وهــذا مــا‬\n‫ال يعــرف فيــه نــزاع )) أ‪.‬هــ‪ .‬ونظــر ًا الن املدعــي قــد قــدم طلب ـ ًا عارض ـ ًا‬\n‫يطلــب فيــه حتديــد موعــد لــه لزيــارة ابنتيــه ‪...‬و ‪...‬وقــد لــزم الفصــل فيــه‬\n‫وهــذا ال يحتــاج الــى حتديــد مــن هيئــة اخلبــراء بــل يكفــي فيــه حتديــد‬\n‫ذلــك مــن قبلنــا حســب املصلحــة التــي يراهــا احلاكــم يف هــذه القضيــة‬\n‫لذلــك كلــه فقــد حكمــت مبــا يلــي أو ًال رد دعــوى املدعــي وقــررت أن‬\n‫املدعــى عليهــا هــي األحــق بحضانــة ابنتيهــا ‪...‬و‪...‬مــا لــم يقــم املدعــى‬\n‫عليهــا مــا مينــع مــن تقدميهــا أو بــكل واحــدة مــن هاتــن البنتــن وصــف‬\n‫يقتضــي تخييرهمــا ثاني ـ ًا إلــزام املدعــى عليهــا بتمكــن املدعــي مــن‬\n‫زيــارة ابنتيــه مرتــن يف األســبوع بحيــث يأخذهمــا الســاعة اخلامســة‬\n‫مســاء ويعيدهمــا الــى والدتهمــا املدعــى عليهــا الســاعة التاســعة مســاء‬\n‫كل يــوم أحــد وأربعــاء وبعرضــه علــى املدعــي لــم يقنــع بــه وطالــب‬\n‫بتمييــزه فأجيــب لطلبــه ثــم جــرى تســليمه نســخة احلكــم ومت إفهامــه‬\n‫بــأن عليــه تســليم الئحتــه االعتراضيــة يف مــدة أقصاهــا ثالثــون يومـ ًا مــن‬\n‫تاريــخ هــذا اليــوم وأنــه إذا مضــت هــذه املــدة احملــددة آنف ـ ًا ولــم يقــدم‬\n‫فيهــا اعتراضــه فــان حقــه يف طلــب التمييــز يســقط فقــرر اســتالمه‬\n\n\n                                                                                          ‫‪234‬‬\n\f      ‫لنســخة احلكــم وفهمــه ملــا أفهــم بــه آنف ـ ًا واســتعداده بتقــدمي الئحتــه يف‬\n      ‫املــدة احملــددة نظام ـ ًا كمــا أمــرت بتســليم املدعــى عليهــا ‪...‬نســخة مــن‬\n      ‫هــذا احلكــم عــن طريــق ادارة احملضريــن بهــذه احملكمــة لتقــدمي‬\n      ‫اعتراضهــا علــى احلكــم املتعلــق بالزيــارة إن كان لهــا اعتــراض‬\n      ‫وإفهامهــا بــأن لهــا احلــق يف ذلــك خــال مــدة أقصاهــا ثالثــون يوم ـ ًا مــن‬\n      ‫تاريخ اســتالمها لهذه النســخة وأنه إذا مضت املدة ولم تقدم اعتراضها‬\n      ‫فــان حقهــا يســقط يف طلــب التمييــز وأمــا اكتســاب احلكــم للقطعيــة‬\n      ‫فانــه ال يكتســب القطعيــة إال بتصديــق االســتئناف أو بعــدم تقــدمي‬\n      ‫املتداعيــن جميع ـ ًا لوائحهمــا االعتراضيــة يف املــدة احملــددة نظام ـ ًا‬\n      ‫وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد ‪ ،‬حـ ـ ـ ـ ـ ـ ــرر‬\n                                                                  ‫ف ـ ـ ــي ‪1433/9/23‬هـ ‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد يف يــوم االربعــاء املوافــق ‪1434 / 2/20‬ه ـ‬\n      ‫افتتحــت اجللســة يف الســاعة الثامنــة صباحــا بنــاء علــى ورود املعاملــة مــن‬\n      ‫محكمــة االســتئناف بالقصيــم برقــم (‪ )3480724‬يف ‪1434/1/21‬ه ـ‬\n      ‫مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة املختصــة‬\n      ‫بتدقيــق قضايــا األحــوال الشــخصية واالنهــاءات مبحكمــة االســتئناف‬\n      ‫بالقصيــم رقــم (‪ )3412609‬يف ‪1434/1/14‬ه ـ املقــرر فيــه مــا نــص‬\n      ‫احلاجــة منــه (( وباالطــاع علــى املعاملــة والصــك وصــورة ضبطــه لوحــظ‬\n      ‫أن فضيلتــه لــم يــدون يف الضبــط قــرار الدائــرة ومــا يجيــب بــه عليــه ولــم‬\n      ‫يلحــق خالصــة وافيــة مــن ذلــك يف صــك احلكــم وهــذا مخالــف ملقتضــى‬\n      ‫املــادة (‪ )1/187‬مــن لوائــح نظــام املرافعــات الشــرعية ‪ .‬فعلــى فضيلتــه‬\n      ‫مالحظــة مــا ذكــر وإحلــاق مــا يجريــه بالضبــط والصــك وســجله ثــم‬\n      ‫إعــادة املعاملــة إلكمــال الزمهــا )) أ‪.‬هــ‪ .‬وعليــه أجيــب بأنــه ظهــر لــي مــن‬\n\n\n‫‪235‬‬\n\f‫املعاملــة مــا يلــي أوال أنــه صــدر قــرار الدائــرة املختصــة بتدقيــق األحــوال‬\n‫الشــخصية واالنهــاءات مبحكمــة االســتئناف مبنطقــة القصيــم رقــم‬\n‫(‪ )33476085‬يف (‪1433/12/22‬هــ) املقــرر فيــه أنــه لوحــظ أن صــورة‬\n‫الضبــط ناقصــة حيــث لــم يرفــق بهــا جلســة احلكــم وحيثياتــه املؤرخــة‬\n‫يف (‪1433/9/23‬هــ) ثانيــا أن املعاملــة أعيــدت مــن قبــل فضيلــة رئيــس‬\n‫احملكمــة العامــة بعنيــزة برقــم (‪ )3437187‬يف (‪1434/1/7‬هــ) وقــد‬\n‫كنــت يف الفتــرة مــن (‪1433/12/18‬هــ) وحتــى (‪1434/2/13‬هــ)‬\n‫مكلفــا مــن قبــل معالــي وزيــر العــدل بحضــور الــدورة اجلزائيــة‬\n‫املتخصصــة الثانيــة وال أعلــم ســبب إعادتهــا إلــى محكمــة االســتئناف‬\n‫مــن قبــل رئيــس احملكمــة العامــة بعنيــزة خــال تكليفــي بحضــور تلــك‬\n‫الــدورة وهــذا هــو ســبب عــدم إحلــاق مــا أشــار إليــه أصحــاب الفضيلــة‬\n‫وأنــا لســت مســئوال عمــا يتــم خــال فتــرة تكليفــي مــن قبــل معالــي وزيــر‬\n‫العــدل حفظــه اهلل هــذا مــا لــزم بيانــه وإيضاحــه وأمــا املطلــوب فهــو‬\n‫مرفــق أساســا باملعاملــة ابتــداء وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                                                  ‫نبينــا محمــد ‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1434/3/10‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الواحــدة وخمســة عشــر دقيقــة ظهــرا بنــاء علــى‬\n‫ورود املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم (‪)34455767‬‬\n‫يف ‪1434/3/7‬ه ـ مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف‬\n‫بالدائــرة املختصــة بتدقيــق قضايــا األحــوال الشــخصية و االنهــاءات‬\n‫مبحكمــة اإلســتئناف بالقصيــم رقــم (‪ )3453446‬يف ‪1434/3/2‬ه ـ‬\n‫املقــرر فيــه مــا نــص احلاجــة منــه (( وباالطــاع علــى مــا أجــاب بــه‬\n‫فضيلتــه وأحلقــه بالضبــط والصــك بنــاء علــى قرارنــا رقــم (‪)3412609‬‬\n\n\n                                                                                       ‫‪236‬‬\n\f      ‫وتاريــخ ‪1434/1/14‬ه ـ لوحــظ مايلــي ‪ :‬أوال‪ :‬حكــم فضيلتــه باحلضانــة‬\n      ‫والزيــارة مــع أنــه لــم يــرد بالزيــارة دعــوى مــن املدعــي وإمنــا بنــاء علــى‬\n      ‫الطلــب العــارض املقــدم منــه والــذي لــم يــدون رقــم قيــدة وتاريخــه يف‬\n      ‫الضبــط ‪ ،‬كمــا أن دعــوى الزيــارة ال تعتبــر طلبــا عارضــا وإمنــا هــي‬\n      ‫دعــوى مســتقلة حســبما نصــت عليــه املــادة املضافــة رقــم (‪ )4/39‬مــن‬\n      ‫لوائــح نظــام املرافعــات الشــرعية ‪ .‬ثانيــا ‪ :‬ورد يف الضبــط (( أن املدعــى‬\n      ‫عليهــا جــرى تســليمها نســخة احلكــم ومضــت املــدة النظاميــة ولــم تقــدم‬\n      ‫الئحــة اعتراضيــة ولــذا فــإن احلكــم بالنســبة لهــا يعتبــر قطعيــا)) ولــم‬\n      ‫جنــد أن فضيلتــه دون ذلــك يف صــك احلكــم وهــذا مخالــف ملقتضــى‬\n      ‫املــادة (‪ )178‬مــن نظــام املرافعــات الشــرعية ‪ .‬فعلــى فضيلتــه مالحظــة‬\n      ‫ماذكــر)) ‪.‬أ‪.‬هــ‪ .‬وعليــه أجيــب مشــائخنا أصحــاب الفضيلــة جزاهــم اهلل‬\n      ‫عنــا خيــرا بــأن مــا ورد يف املالحظــة األولــى كان بنــاء علــى الطلــب‬\n      ‫العــارض اخلــاص بالزيــارة قيــد برقــم (‪ )331050503‬يف ‪1433/6/4‬ه ـ‬\n      ‫وأمــا مــا اســتند عليــه مشــائخنا يف قرارهــم وهــي املــادة املضافــة رقــم‬\n      ‫(‪ )4/39‬فإنــه العالقــة لهــا بهــذا املوضــوع ألنهــا تنــص علــى أنــه إذا وردت‬\n      ‫املعاملــة إلــى احملكمــة مــن جهــة رســمية ولــم يرفــق بهــا صحيفــة دعــوى‬\n      ‫فيتــم اســتكمال بيانــات الصحيفــة مــن املدعــي لــدى مكتــب املواعيــد‬\n      ‫أ‪.‬هــ‪ .‬ولعــل مشــائخنا يقصــدون الفقــرة الرابعــة عشــر مــن املــادة التاســعة‬\n      ‫والثالثــن مــن نظــام املرافعــات الشــرعية وهــذه الفقــرة لــم متنــع تقــدمي‬\n      ‫طلــب عــارض بالزيــارة وإمنــا نصــت علــى أن دعــوى الزيــارة إذا قدمــت‬\n      ‫مســتقلة فإنهــا حتــال مــع القضايــا الزوجيــة واخللــع والفســخ والنفقــة‬\n      ‫واحلضانــة إلــى قاضــي واحــد وحتســب لــه إحالــة وأمــا ســبب قبولــي لهــذا‬\n      ‫الطلــب العــارض املتعلــق بالزيــارة يف الدعــوى فهــو ألمريــن أحدهمــا مــا‬\n\n\n‫‪237‬‬\n\f‫جــاء يف املــادة (‪/79‬هــ) مــن نظــام املرافعــات الشــرعية وثانيهمــا هــو‬\n‫ســرعة البــت يف هــذه القضيــة بشــكل يحفــظ بــه حــق املتداعيــن وحــق‬\n‫الطفلتــن وأمــا بالنســبة للمالحظــة الثانيــة فإنــه ســيتم مراعــاة ذلــك‬\n‫مســتقبال إن شــاء اهلل وأشــكر مشــائخنا أصحــاب الفضيلــة علــى هــذا‬\n‫التنبيــه والعمــل ذكــر هــذه املالحظــة واجلــواب عليهــا يغنــي عــن نقــل تلــك‬\n‫اجللســة اخلاصــة باكتســاب احلكــم للقطعيــة بحــق املدعــى عليهــا ألن‬\n‫إدخــال تلــك اجللســة يف الصــك يف محلهــا ســيضطر إلــى إخــراج صــك‬\n‫جديــد كمــا ال يخفــى يف نقــل جلســة ســابقة إلــى الصــك يف النظــام‬\n‫الشــامل هــذا مــا لــزم اجلــواب عليــه وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                 ‫‪ .‬حــرر يف ‪ 1434/03/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1434/7/4‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الثامنــة والنصــف صباحــا بنــاء علــى ورود املعاملــة مــن‬\n‫محكمــة االســتئناف بالقصيــم برقــم ‪ 34644803‬يف ‪1434/4/20‬ه ـ‬\n‫مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واالنهــاءات مبحكمــة االســتئناف‬\n‫بالقصيــم رقــم ‪ 34187931‬يف ‪1434/4/15‬ه ـ املقــرر فيه مانص احلاجة‬\n‫منــه ( وباالطــاع علــى مــا أجاب به فضيلته وأحلقه بالضبط والصك بناء‬\n‫علــى قرارنــا رقــم (‪ )3453446‬وتاريــخ ‪1434/3/2‬ه ـ لوحــظ أن جــواب‬\n‫فضيلتــه علــى املالحظــة األولــى غيــر مقنــع وال مــاق ملــا طلــب منــه ألن‬\n‫دعــوى الزيــارة دعــوى مســتقلة حســب املــادة املضافــة (‪ )14/39‬مــن لوائح‬\n‫نظــام املرافعــات الشــرعية كمــا لــم يــرد يف الضبــط والصــك دعــوى مــن‬\n‫املدعــي بطلــب حتديــد زيــارة ابنتيــه وغنمــا بنــى فضيلتــه حكمــه علــى‬\n‫الطلــب املقــدم مــن املدعــي وحتــى لــو قيــل بقبــول دعــوى الزيــارة بعــد أن‬\n\n\n                                                                                      ‫‪238‬‬\n\f      ‫يدعــي بهــا املدعــي ويطالــب بهــا فــإن حتديدهــا ينبغــي أن يكــون مبنيــا‬\n      ‫علــى قــرار هيئــة النظــر الــذي يكــون معتمدهــم فيــه علــى ماتــراه مــن‬\n      ‫وضــع املتداعيــن ومصلحــة البنتــن وحتــدد فيــه آليــة الزيــارة ومــن يقــوم‬\n      ‫بأخذهمــا وإعادتهمــا فعلــى فضيلتــه مالحظــة ماذكــر وإجــراء مايلــزم‬\n      ‫علــى وفــق ماذكــر أو الرجــوع عمــا أجــراه بخصــوص ماقــرره مــن زيــارة‬\n      ‫للبنتــن وقصــر احلكــم علــى احلضانــة وإجــراء مايلــزم بحضــور الطرفــن‬\n      ‫وإحلــاق مايجريــه يف الضبــط وصورتــه والصــك وســجله ثــم إعــادة املعاملة‬\n      ‫إلكمــال الزمهــا )أ‪.‬هــ‪ .‬وقــد حضــر يف هــذه اجللســة املدعــي ‪...‬كمــا‬\n      ‫حضــرت املدعــى عليهــا ‪...‬والتــي متــت مطابقــة بطاقتهــا مــن قبــل حارســة‬\n      ‫األمــن يف هــذه احملكمــة ‪...‬حســبما يظهــر مــن صــورة البطاقــة املرفقــة‬\n      ‫ثــم قــرر املدعــي قائــا لقــد ســبق أن تقدمــت بطلــب عــارض أطلــب فيــه‬\n      ‫زيــارة أوالدي ومــادام أن أصحــاب الفضيلــة قضــاة االســتئناف قــرروا أنــه‬\n      ‫البــد مــن املطالبــة بــه يف ضبــط القضيــة فإننــي أقــرر مطالبتــي بذلــك‬\n      ‫وهــو نفــس طلبــي العــارض الــذي قدمتــه ســابقا هكــذا قــرر ولــذا فإنــه‬\n      ‫ماقــرره املدعــي هــو الــرد علــى هــذه املالحظــة وأمــا بخصــوص أنــه ينبغــي‬\n      ‫أن يكــون ذلــك بقــرار مــن هيئــة اخلبــراء فإننــي ال أرى وجــوب ذلــك ألن‬\n      ‫النظــر النهائــي يف تقريــر الزيــارة هــو للقاضــي ألن للقاضــي رد قــرار‬\n      ‫اخلبــراء حســبما نــص عليــه النظــام وأمــا كــون جوابــي غيــر مقنــع فــإن‬\n      ‫حســبي االجتهــاد واحلكــم مبــا أراه صوابــا واهلل املوفــق وبعرضــه علــى‬\n      ‫املدعــى عليهــا قــررت قناعتهــا باحلكــم املتضمــن احلكــم باحلضانــة‬\n      ‫والزيــارة وأمــا املدعــي فقــرر أنــه مــازال علــى معارضتــه الســابقة والئحتــه‬\n      ‫االعتراضيــة املقدمــة منــه ســابقا وعليــه جــرى التوقيــع وصلــى اهلل وســلم‬\n                                         ‫علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/7/4‬ه ـ ‪.‬‬\n\n\n‫‪239‬‬\n\f‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة عنيــزة برقــم (‪ )34/644803‬وتاريــخ ‪1434/7/5‬هــ؛‬\n‫املقيــدة لــدى احملكمــة برقــم (‪ )341651535‬وتاريــخ ‪1434/7/9‬هــ؛‬\n‫اخلاصــة بدعــوى‪... /‬ضــد‪... /‬؛ بشــأن مطالبتــه بحضانــة ابنتيــه منهــا‪/‬‬\n‫‪...‬و‪...‬؛ املنتهيــة بالصــك الصــادر مــن فضيلــة الشــيخ‪... /‬القاضــي‬\n‫باحملكمــة؛ املســجل برقــم (‪ )33417800‬وتاريــخ ‪1433/9/23‬هــ؛‬\n‫املتضمــن حكــم فضيلتــه بــرد دعــوى املدعــي وأن األم هــي األحــق‬\n‫بحضانــة البنتــن املذكورتــن وإلــزام املدعــى عليهــا بتمكــن املدعــي‬\n‫مــن زيــارة ابنتيــه املذكورتــن؛ علــى النحــو املفصــل فيــه‪ .‬وقــد ســبق منــا‬\n‫دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‪.‬‬\n‫ـاء‬\n‫وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط والصــك بنـ ً‬\n‫علــى قرارنــا رقــم (‪ )34187931‬وتاريــخ ‪1434/4/15‬ه ـ قررنا املصادقة‬\n‫علــى ماحكــم بــه فضيلتــه بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق‪ ،‬وصلــى‬\n                              ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪240‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":227,"source_page_end":240,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"db7a987a1441fe2597d4c79ce379d3f720b664073d2b757cee13bf5cb8aa606b","normalized_text_hash":"241111f305a082e9f3b649e8adcb74ec81efab1f882f54240b76b4a484311fa3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p227-33417800"},{"id":"ffa4eb0b-414b-5603-bc34-849a7f3fba40","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب اجلدة حضانة بنت ابنتها -إثبات التقرير النفسي رغبة البنت أن تكون عند جدتها ألمها -عماد احلضانة األصلح للمحضون -األحق باحلضانة األم ثم أمهاتها -احلكم بأن اجلدة ألم هي األولى بحضانة بنت ابنتها -األخذ بقول األخصائي النفسي و االجتماعي يف األحق باحلضانة -للقاضي األخذ برأي أهل اخلبرة أو رفضه .","document_number":"33430026","case_number":"3369325","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة يف الرياض وطلب إحالتها ملقر سكن املدعى عليه بجدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/17","year":"1434","subject":"حضانة -طلب اجلدة حضانة بنت ابنتها -إثبات التقرير النفسي رغبة البنت أن تكون عند جدتها ألمها -عماد احلضانة األصلح للمحضون -األحق باحلضانة األم ثم أمهاتها -احلكم بأن اجلدة ألم هي األولى بحضانة بنت ابنتها -األخذ بقول األخصائي النفسي و االجتماعي يف األحق باحلضانة -للقاضي األخذ برأي أهل اخلبرة أو رفضه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33430026 :‬تاريخه ‪1433/10/17 :‬هـ‬\n                            ‫رقم القضية ‪3369325:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3439907‬تاريخه‪1434/02/18 :‬هـ‬\n\n\n       ‫حضانــة‪ -‬طلــب اجلــدة حضانــة بنــت ابنتهــا‪ -‬إثبــات التقريــر النفســي‬\n       ‫رغبــة البنــت أن تكــون عنــد جدتهــا ألمهــا‪ -‬عمــاد احلضانــة األصلــح‬\n       ‫للمحضــون‪ -‬األحــق باحلضانــة األم ثــم أمهاتهــا‪ -‬احلكــم بــأن اجلــدة‬\n       ‫ألم هــي األولــى بحضانــة بنــت ابنتهــا‪ -‬األخــذ بقــول األخصائــي‬\n       ‫النفســي و االجتماعــي يف األحــق باحلضانــة‪ -‬للقاضــي األخــذ بــرأي‬\n                                                         ‫أهــل اخلبــرة أو رفضــه ‪.‬‬\n\n\n\n       ‫‪ .1‬قــال ابــن القيــم ‪ -‬رحمــه اهلل ‪ -‬يف زاد املعــاد ( ‪ ( ) 463/5‬والصــواب‬\n       ‫النظــر واالحتيــاط للطفــل يف األصلــح واألنفــع يف اإلقامــة أو االنتقــال‬\n       ‫ويف احلاضــن فأيهــم كان أنفــع لــه وأصــون وأحفــظ روعــي وال تأثيــر‬\n                                                               ‫إلقامــة وال نقلــة ) ‪.‬‬\n            ‫القاعدة التي تقرر ( أن عماد احلضانة هو األصلح للمحضون ) ‪.‬‬\n                   ‫‪ .2‬ما قرره أهل العلم أن األولى باحلضانة األم ثم أمهاتها ‪.‬‬\n       ‫‪ .3‬املــادة رقــم ‪/10/34‬ه ـ مــن نظــام املرافعــات الشــرعية املعدلــة والتــي‬\n       ‫تضمنــت ( ويســري هــذا احلكــم علــى دعــاوى احلضانــة والزيــارة يف‬\n                                                          ‫األحــوال الشــخصية ) ‪.‬‬\n\n\n\n\n‫‪241‬‬\n\f‫حضــرت اجلــدة ألم وادعــت علــى زوج ابنتهــا ســابق ًا بأنهــا أجنبــت منــه‬\n‫بنتـ ًا اســمها ‪ ............‬مولــودة بتاريــخ ‪1424/8/21‬ه ـ وقــد حصــل طــاق‬\n‫بــن الطرفــن والطفلــة عنــد والدهــا ولكــون والدتهــا متزوجــة طلبــت‬\n‫احلكــم لهــا بحضانــة الطفلــة املذكــورة‪ ،‬دفــع املدعــى عليــه وكالــة‬\n‫بعــدم اختصــاص احملكمــة العامــة يف الريــاض وطلــب إحالتهــا ملقــر‬\n‫ســكن املدعــى عليــه بجــدة‪ ،‬كمــا قــرر أنــه قــد صــدر صــك بــن‬\n‫بنــت املدعيــة وموكلــه أن البنــت تبقــى عنــد والدهــا‪ ،‬جــرت الكتابــة‬\n‫ملستشــفى الصحــة النفســية إلبــداء تقريــر عــن الطفلــة املذكــورة فــورد‬\n‫التقريــر الطبــي أن الطفلــة املذكــورة ال تعانــي مــن اضطــراب نفســي‬\n‫وحالتهــا مســتقرة وتوجــد ضغــوط مــن قبــل الوالديــن تؤثــر عليهــا الختيار‬\n‫مــكان احليــاة أو تفضيــل مــكان علــى آخــر إال أن الطفلــة أبــدت تعلقهــا‬\n‫عاطفي ـ ًا بجدتهــا ألمهــا يف الريــاض وتفضــل احليــاة هنــاك‪ ،‬مت االطــاع‬\n‫علــى الصــك بــن بنــت املدعيــة وزوجهــا ســابق ًا واملتضمــن وجــود اتفــاق‬\n‫وصلــح علــى أن تكــون احلضانــة لوالدتهــا وزيــارة والدهــا يف منــزل‬\n‫زوجتــه ســابق ًا يف الريــاض‪ ،‬مت ســؤال املدعــى عليــه وكالــة هــل تطعــن‬\n‫بحضانــة املدعيــة بشــيء فأجــاب بقولــه أنهــا كبيــرة يف الســن‪ ،‬قــرر‬\n‫املدعــي وكالــة أن البنــت تقعــد عنــد زوجــة والدهــا ووالدهــا مشــغول‬\n‫فاملدعيــة أولــى بهــا‪ ،‬قــرر األخصائــي النفســي أن الطفلــة تشــعر بتفــاوت‬\n‫املعاملــة بينهــا وبــن أختهــا ألبيهــا‪ ،‬ملــا كانــت احلضانــة مــن األمــور‬\n‫املتجــددة واحلكــم الصــادر بــن الزوجــة وزوجهــا ســابق ًا لــم يتضمــن‬\n‫احلكــم للمدعــى عليــه باحلضانــة صراحــة‪ ،‬وحيــث إن عمــاد احلضانــة‬\n\n                                                                                  ‫‪242‬‬\n\f      ‫هــو األصلــح للمحضــون‪ ،‬احلكــم بحضانــة اجلــدة للبنــت وتســليمها‬\n      ‫إياهــا مــع أوراقهــا الثبوتيــة‪ ،‬قــرر املدعــى عليــه اعتراضــه علــى احلكــم‬\n                         ‫بالئحة‪،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض املســاعد برقــم ‪ 3369325‬وتاريــخ ‪1433/01/26‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 33181558‬وتاريــخ ‪ 1433/01/26‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق ‪1433/10/17‬ه ـ حضــر ‪ ...‬ســعودي اجلنســية‬\n      ‫مبوجــب ســجل مدنــي رقــم ‪ ...‬بصفتــه وكيــا عــن ‪ ...‬ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬ينــوب عنهــا يف املطالبــة واملرافعــة‬\n      ‫واملدافعــة واملخاصمــة واإلقــرار واإلنــكار والصلــح وطلــب وقبــول‬\n      ‫احلكــم أو اإلعتــراض عليــه مبوجــب صــك وكالــة صــادر مــن كتابــة‬\n      ‫عــدل محافظــة الدرعيــة برقــم ‪ 32268328‬يف ‪1432/10/19‬ه ـ وأدعــى‬\n      ‫علــى احلاضــر معــه ‪ ...‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪...‬‬\n      ‫بصفتــه وكيــا عــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ...‬ينــوب عنــه يف مراجعــة احملكمــة العامــة وحضــور اجللســات مبوجــب‬\n      ‫صــك وكالــة صــادر مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة‬\n      ‫برقــم ‪ 47908‬يف ‪1433/5/26‬ه ـ قائــا يف حتريــر دعــواه إن املدعــى‬\n      ‫عليــه كان زوجــا البنــة موكلتــي والتــي أجنبــت منــه بنتــا اســمها ‪...‬‬\n      ‫مولــودة يف ‪1424/8/21‬ه ـ وقــد حصــل الطــاق بــن الطرفــن وحيــث‬\n      ‫إن الطفلــة املذكــورة لــدى والدهــا ولكــون والدتهــا متزوجــه فــا حــق‬\n\n‫‪243‬‬\n\f‫لهــا يف احلضانــة لــذا فــإن موكلتــي تطلــب احلكــم لهــا بحضانــة الطفلــة‬\n‫املذكــورة وتســليمها لهــا هــذي دعــواي وبســؤال املدعــى عليــه قــال إن‬\n‫موكلــي يســكن يف محافظــة جــدة وأرغــب أن تكــون الدعــوى هنــاك‬\n‫وموكلــي ســبق أن تداعــى مــع مطلقتــه وصــدر صــك يف املوضــوع يفهــم‬\n‫منــه ان البنــت عنــده وهــو ال يقبــل تولــي املدعيــة للحضانــة هكــذا أجــاب‬\n‫وبعرضــه علــى املدعــي قــال الصــك ال دخــل ملوكلتــي فيــه ولــم يتضمــن‬\n‫احلكــم باحلضانــة للمدعــى عليــه واالختصــاص معقــود حملكمــة‬\n‫الريــاض هكــذا قــال وهنــا جــرى اإلطــاع علــى تاريــخ ميــاد الطفلــة‬\n‫املطابــق ملــا ذكــر كمــا جــرت الكتابــة ملستشــفى الصحــة النفســية‬\n‫بجــدة التــي أفــادت بخطابهــا رقــم ‪ 173‬يف ‪1433/1/12‬ه ـ وقــد تبــن‬\n‫مــن خــال ذلــك أن الطفلــة يف الوقــت احلالــي ال تعانــي مــن أي اضطــراب‬\n‫نفســي وال توجــد اســاءة معاملــة وتوجــد ضغــوط مــن قبــل الوالديــن‬\n‫تؤثــر عليهــا بدرجــة متوســطة وقــد كانــت الطفلــة اجتماعيــة و متعاونــة‬\n‫ومتحفظــة يف بدايــة التقييــم إال أنهــا اســتطاعت بعــد ذلــك التعبيــر‬\n‫عــن نفســه بشــكل جيــد بالــكالم والرســم واوضحــت أن هنــاك‬\n‫بعــض الضغــوط عليهــا مــن والديهــا الختيــار مــكان احليــاة أو تفضيــل‬\n‫مــكان عــن آخــر إال أن الطفلــة أبــدت تعلقهــا عاطفيــا بجدتهــا ألمهــا يف‬\n‫الريــاض وتفضــل احليــاة هنــاك بالرغــم مــن وجــود والديهــا يف جــدة وهــي‬\n‫حتتــاج الســتكمال منوهــا النفســي إلــى توفــر منــوذج األم أو مــن يقــوم‬\n‫مقامهــا والتوصيــة توفيــر منــوذج األم حتــى تنمــو بطريقــة طبيعيــة ووجــوب‬\n‫االهتمــام والرعايــة مــن قبــل األب‪ .‬كمــا جــرى اإلطــاع علــى املــادة‬\n‫‪/10/34‬ه ـ املعدلــة مــن املرافعــات والتــي تضمنــت (ويســري هــذا احلكم‬\n‫علــى دعــاوى احلضانــة والزيــارة يف األحــوال الشــخصية ) واإلطــاع علــى‬\n\n\n                                                                                   ‫‪244‬‬\n\f      ‫الصــك رقــم ‪ 29/137‬يف ‪1429/6/30‬ه ـ واملتضمــن دعــوى ‪ ...‬ضــد ‪...‬‬\n      ‫يف موضــوع زيــارة وآخــره االتفــاق والصلــح علــى أن تكــون احلضانــة‬\n      ‫لوالدتهــا وزيــارة والدهــا يف منــزل املدعــى عليهــا يف الريــاض يف حــال‬\n      ‫البنــت إكمــال البنــت الســابعة يحــق لوالدهــا اســتالمها يف حصــول‬\n      ‫إشــكاليه فاملرجــع للقضــاء انتهــى‪ .‬وهنــا جــرى ســؤال املدعــى عليــه هــل‬\n      ‫لديــه طعــن يف املدعيــة قــال هــي فقــط امــرأة كبيــرة يف الســن وقــال‬\n      ‫املدعــي إن موكلتــي صحيحــه قــادره والطفلــة تقعــد عنــد زوجــة أبيهــا‬\n      ‫ووالدهــا مشــغول فاملدعيــة أولــى بهــا ثــم أبــرز صــورة خطــاب مــن هيئــة‬\n      ‫حقــوق اإلنســان مبنطقــة مكــة يتضمــن أن األخصائــي النفســي قــرر أن‬\n      ‫الطفلــة تشــعر بتفــاوت املعاملــة بينهــا وبــن أختهــا ألبيهــا فبنــاء علــى مــا‬\n      ‫تقــدم وملــا كان احلضانــة مــن األمــور املتجــددة وكذلــك فــإن احلكــم‬\n      ‫املذكــور لــم يتضمــن احلكــم للمدعــى عليــه باحلضانــة صراحــه وحيــث‬\n      ‫إن عمــاد احلضانــة هــو األصلــح للمحضــون قــال ابــن القيــم ( الصــواب‬\n      ‫النظــر واالحتيــاط للطفــل يف األصلــح واألنفــع يف اإلقامــة أو االنتقــال‬\n      ‫ويف احلاضــن فأيهــم كان أنفــع لــه وأصــون وأحفــظ روعــي وال تأثيــر‬\n      ‫إلقامــه وال نقلــه) زاد املعــاد ‪ 463/5‬وملــا قــرره أهــل العلــم ان األولــى‬\n      ‫باحلضانــة األم ثــم امهاتهــا لذلــك كلــه وملــا ســبق فقــد ثبــت لــدي أن‬\n      ‫املدعيــة ‪ ...‬أولــى بحضانــة ‪ ... ...‬وأنــه يلــزم املدعــى عليــه تســليمها مــع‬\n      ‫نســخة مــن اوراقهــا الثبوتيــة للمدعيــة ومبــا ســبق حكمــت وبعرضــه‬\n      ‫علــى املدعــى عليــه قــرر املعارضــة وطلــب اإلســتئناف فأجيــب لطلبــه‬\n      ‫وســلم صــورة احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا فــإن‬\n      ‫مضــت املــدة ولــم يتقــدم بالئحــة اعتراضــه ســقط حقــه يف اإلعتــراض‬\n      ‫واكتســب احلكــم القطعيــة وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n‫‪245‬‬\n\f           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي القائــم بعمــل‬\n‫فضيلــة الشــيخ ‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/04/13‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 30‬‬\n‫وكانــت املعاملــة قــد عــادت مــن محكمــة اإلســتئناف برفقهــا القــرار‬\n‫رقــم ‪ 3439907‬وتاريــخ ‪1434/2/18‬ه ـ الصــادر مــن دائــرة األحــوال‬\n‫الشــخصية األولــى املتضمــن وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫اإلعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب اإلعتــراض أ‪.‬ه ـ وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪ 1434/04/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتمييــز قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد برقــم ‪ 34/62278‬وتاريــخ ‪1434/1/7‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...‬املســجل‬\n‫برقــم ‪ 33430026‬وتاريــخ ‪1433/10/17‬ه ـ اخلــاص بدعــوى ‪ ...‬الوكيــل‬\n‫عــن ‪ ...‬ضــد ‪ ...‬الوكيــل عــن ‪ ...‬بشــأن حضانــة أوالد وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب‬\n‫االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪246‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":241,"source_page_end":246,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"caac87c6649cbd7e37b7d82df9063cfa1089e42dd21e59afe9f7eaf49b740591","normalized_text_hash":"75a25feeb0048a44b8d323cd866846befe67a37b26da513a06b5829aeb90abfe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p241-33430026"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"5af13e6a-1e2c-55e0-a713-fcf41abe47f4","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب اجلد حضانة أوالد ابنه -زواج املرأة -موافقة زوجها على حضانتها ألوالدها من الزوج السابق -النظر يف احلضانة ملصلحة احملضون -صرف النظر عن طلب اجلد حضانة أوالد ابنه.","document_number":"34271962","case_number":"3441277","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/18","year":"1434","subject":"حضانة -طلب اجلد حضانة أوالد ابنه -زواج املرأة -موافقة زوجها على حضانتها ألوالدها من الزوج السابق -النظر يف احلضانة ملصلحة احملضون -صرف النظر عن طلب اجلد حضانة أوالد ابنه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34271962 :‬تاريخه ‪1434/7/18 :‬هـ‬\n                     ‫رقم الدعوى ‪3441277:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34294900‬تاريخه‪1434/8/13 :‬هـ‬\n\n\n‫حضانــة ‪ -‬طلــب اجلــد حضانــة أوالد ابنــه ‪ -‬زواج املــرأة ‪ -‬موافقــة زوجهــا‬\n‫علــى حضانتهــا ألوالدهــا مــن الــزوج الســابق ‪ -‬النظــر يف احلضانــة‬\n‫ملصلحــة احملضــون ‪ -‬صــرف النظــر عــن طلــب اجلــد حضانــة أوالد ابنــه‪.‬‬\n\n\n\n\n‫‪ .1‬قــال ابــن القيــم ‪ -‬رحمــه اهلل ‪ -‬يف زاد املعــاد ( ‪ ( : ) 484/5‬أن الــزوج إذا‬\n‫رضــي باحلضانــة وآثــر كــون الطفــل يف حجــره لــم تســقط احلضانــة‬\n                                                         ‫هــذا هــو الصحيــح )‪.‬‬\n                                   ‫‪ .2‬قاعدة‪ ( :‬احلضانة حق للمحضون )‪.‬‬\n\n\n\n\n‫حضــر اجلــد ويطلــب حضانــة أوالد ابنــه املتوفــى وهــم ‪ ...‬و‪ ...‬و‪ ...‬وقــد تــويف‬\n‫والدهــم واألوالد يف حضانــة أمهــم املدعــى عليهــا وقــد تزوجــت ويطلــب‬\n‫نقــل احلضانــة إليــه ‪ -‬أقــرت املدعــى عليهــا بأنهــا كانــت زوج ـ ًة البــن‬\n‫املدعــي وأن األوالد الذيــن ذكرهــم هــم أوالدهــا منــه وأقــرت بالــزواج‬\n‫مــن رجــل آخــر ولكــن رفضــت نقــل احلضانــة إلــى املدعــي نظــر ًا لكبــر‬\n‫ســنه وال يســتطيع إدارة شــوؤنهم‪ ،‬مت ســؤال املدعــي هــل تطعــن بحضانــة‬\n‫األم بشــيء فأجــاب بقولــه ال‪ ،‬حضــر زوج املدعــى عليهــا وقــرر أنــه ال‬\n‫مانــع مــن بقــاء أوالد زوجتــه عنــده وحتــت حضانــة أمهــم ‪ -‬ظهــر للقاضــي‬\n\n                                                                                       ‫‪208‬‬\n\f      ‫أن بقــاء األوالد مجتمعــن عنــد أمهــم فيــه مصلحــة لهــم‪ ،‬احلكــم بصرف‬\n      ‫النظــر عــن دعــوى املدعــي وبقــاء حضانــة األوالد للمدعــى عليهــا‪ ،‬قــرر‬\n      ‫املدعــي اعتراضــه علــى احلكــم بالئحــة اعتراضيــة‪ ،‬صــدق احلكــم مــن‬\n                                                          ‫محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 3441277‬وتاريــخ‬\n      ‫‪ 1434/01/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34201473‬وتاريــخ‬\n      ‫‪ 1434/01/24‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/07/10‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي ‪ .......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ .......‬وحضــرت حلضــوره املدعــى عليهــا‬\n      ‫‪ .......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬وادعــى‬\n      ‫املدعــي قائــا ان املدعــى عليهــا كانــت زوج ابنــي ‪ .......‬وقــد اجنبــت‬\n      ‫منــه ثالثــة اوالد وهــم ‪ ...‬املولــودة يف ‪1426/10/17‬ه ـ ‪ .......‬املولــود يف‬\n      ‫‪1429/10/17‬ه ـ ‪ .......‬املولــودة يف ‪1431/9/9‬ه ـ ال وارث لــه ســواهم‬\n      ‫وقــد تــويف ابنــي بتاريــخ ‪1432/8/16‬ه ـ مبوجــب صــك حصــر الورثــة‬\n      ‫رقــم ‪ .......‬وتاريــخ ‪1432/9/17‬ه ـ الصــادر مــن هــذه احملكمــة ومنــذ‬\n      ‫وفــاة ابنــي واالوالد عنــد امهــم وقــد تزوجــت بتاريــخ ‪1434/01/29‬ه ـ‬\n      ‫اطلــب نقــل حضانهــم لــي هــذه دعــواى وبعــرض ذلــك علــى املدعــى عليهــا‬\n      ‫اجابــت قائلــة ماذكــره املدعــي مــن أن ابنــه كان زوجــي وأنــي اجنبــت‬\n      ‫مــن ابنــه ثالثــة أوالد هــم املذكــورون اعــاه وانــي تزوجــت بعــد وفــاة‬\n\n‫‪209‬‬\n\f‫ابنــه فصحيــح واوالدي عنــدي منــذ وفــاة ابيهــم وأنــا املســؤلة عنهــم ووليــة‬\n‫عليهــم ايضــا مبوجــب صــك الواليــة رقــم ‪ .......‬وتاريــخ ‪1432/10/09‬ه ـ‬\n‫الصــادرة مــن احملكمــة العامــة بجــدة واملدعــي جدهــم كبيــر يف‬\n‫الســن واليســتطيع ادارة شــؤونهم مثلــي لــذا اطلــب بقــاء حضانــة اوالدي‬\n‫عنــدي هكــذا اجابــت وبســؤال املدعــي هــل تطعــن يف حضانــة املدعــى‬\n‫عليهــا بشــئ اجــاب قائــا ال اطعــن فيهــا بشــىء واريــد حضانتهــم عنــدي‬\n‫هكــذا اجــاب والجــل التأمــل رفعــت اجللســة وبــاهلل التوفيــق ‪ ،‬ويف‬\n‫جلســة اخــرى حضــر املدعــي ‪ .......‬وحضــرت حلضــوره املدعــى عليهــا‬\n‫‪ .......‬برفقــة والدهــا ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ .......‬كمــا حضــر زوج املدعــى عليهــا ‪ .......‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ .......‬وقــرر أنــه ال مانــع مــن بقــاء اوالد زوجتــه عنــده‬\n‫وحتــت حضانــة أمهــم فبنــاء علــى ماتقــدم مــن الدعــوى واالجابــة ومبــا ان‬\n‫املدعــي وهــو جدهــم يطالــب بحضانــة أوالد أبنــه ومبــا أن احلضانــة ينظــر‬\n‫فيهــا إلــى مصلحــة احملضــون فقــط ومصلحــة االوالد بقاؤهــم مجتمعــن‬\n‫عنــد أمهــم حتافــظ عليهــم وترعــى شــئونهم وحيــث قــد حضــر زوج االم‬\n‫وقــرر موافقتــه علــى بقــاء االوالد حتــت حضانــة زوجتــه ويف بيتــه ومبــا أن‬\n‫املدعــي جدهــم كبيــر يف الســن وال يســتطيع القيــام علــى شــئونهم مثــل‬\n‫أمهــم قــال أبــن القيــم رحمــه اهلل بعــد ذكــره لبعــض األحــكام املأخــوذة‬\n‫مــن حديــث البــراء بــن عــازب يف قصــة ابنــة حمــزة‪ .‬الثالثــة ( أن الــزوج إذا‬\n‫رضــي باحلضانــة واثــر كــون الطفــل عنــده يف حجــره لــم تســقط احلضانــة‬\n‫هــذا هــو الصحيــح ) زاد املعــاد ‪ 484/5‬لــذا فقــد صرفــت النظــر عــن‬\n‫دعــوى املدعــي وأبقيــت حضانــة االوالد عنــد أمهــم وأفهمــت املدعــي أن‬\n‫لــه حــق الزيــارة فقــط هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى‬\n\n\n                                                                                         ‫‪210‬‬\n\f      ‫املدعــي قــرر عــدم قناعتــه باحلكــم واســتعد بتقــدمي الئحتــه االعتراضيــة‬\n      ‫خــال املــدة النظاميــة وهــي ثالثــون يومــا وافهمتــه بتعليمــات االســتئناف‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف ‪1434/07/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 3441277‬وتاريــخ‬\n      ‫‪ 1434/01/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34201473‬وتاريــخ‬\n      ‫‪ 1434/01/24‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/07/30‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 12.00‬فقــد مت اإلطــاع علــى الالئحــة اإلعتراضيــة‬\n      ‫املقدمــة مــن املدعــي ‪ .......‬واملكونــة مــن ورقــة واحــدة ولــم أجــد مايؤثــر‬\n      ‫علــى ماحكمــت بــه لــذا قــررت رفــع املعاملــة حملكمــة اإلســتئناف‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                  ‫‪1434/07/30‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمة العامة مبحافظة جدة برقم ‪ 3441277‬وتاريخ ‪1434/01/24‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 34201473‬وتاريــخ ‪ 1434/01/24‬ه ـ‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف بخطــاب رئيســها رقــم‬\n      ‫‪ 34201473‬وتاريــخ ‪1434/08/22‬ه ـ املرفــق بــه قــرار التصديــق رقــم‬\n      ‫‪ 34294900‬وتاريــخ ‪1434/08/13‬ه ـ بخصــوص دعــوى ‪ .......‬ضــد‬\n      ‫‪ .......‬املتضمــن‪ :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم بصــرف النظــر عــن طلــب املدعــي واهلل‬\n\n\n‫‪211‬‬\n\f‫املوفــق وصلــى اهلل وســلم علــى ســيدنا محمــد وعلــى الــه وصحبــه وســلم‬\n‫‪ ،،،،‬انته ـ ـ ـ ــى وللواقــع جــرى إثباتــه وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/28‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 34/201473‬وتاريــخ ‪1434/8/2‬ه ـ‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ .......‬القاضي باحملكمة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 34271962‬وتاريــخ ‪1434/7/18‬هــ‪،‬‬\n‫املتضمــن دعــوى ‪ .......‬ضــد املــرأة ‪ .......‬يف حضانــة أوالد املدعــى عليهــا‪،‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم بصــرف النظــر عــن طلــب املدعــي‪ ،‬واهلل املوفــق ‪ .‬وصلــى‬\n                          ‫اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪212‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":208,"source_page_end":212,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5bc8ca269340ba22211fcbadc4180dee562e3caed2e9cf8970f26670323cc7ba","normalized_text_hash":"dbd3010658259dc23421e5501e6e8969c6076dc08778a43473f692807448526c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p208-34271962"},{"id":"21b856fe-72de-56e3-801f-a88d03ff2952","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب األم حضانة األوالد مع بقاء عقد الزوجية -وجود األوالد مع األب -األم أحق باحلضانة ما لم تنكح -األم أشفق على أوالدها -أحقية األم باحلضانة واإللزام بالتسليم -احلكم بالنفاذ املعجل يف احلضانة .","document_number":"3449875","case_number":"14695","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":"الدائرة ختمه وتوقيعه) وباهلل التوفيق وصلى اهلل وسلم على نبينا","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/27","year":"1434","subject":"حضانة -طلب األم حضانة األوالد مع بقاء عقد الزوجية -وجود األوالد مع األب -األم أحق باحلضانة ما لم تنكح -األم أشفق على أوالدها -أحقية األم باحلضانة واإللزام بالتسليم -احلكم بالنفاذ املعجل يف احلضانة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3449875 :‬تاريخه ‪1434/2/27 :‬هـ‬\n                            ‫رقم الدعوى ‪14695 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34216424‬تاريخه‪1434/05/19 :‬هـ‬\n\n\n      ‫حضانــة ‪ -‬طلــب األم حضانــة األوالد مــع بقــاء عقــد الزوجيــة‪ -‬وجــود‬\n      ‫األوالد مــع األب‪ -‬األم أحــق باحلضانــة مــا لــم تنكــح‪ -‬األم أشــفق علــى‬\n      ‫أوالدهــا‪ -‬أحقيــة األم باحلضانــة واإللــزام بالتســليم‪ -‬احلكــم بالنفــاذ‬\n                                                          ‫املعجــل يف احلضانــة ‪.‬‬\n\n\n\n                ‫‪ .1‬قوله صلى اهلل عليه وسلم ( أنت أحق به ما لم تنكحي ) ‪.‬‬\n                              ‫‪ .2‬املادة ( ‪ ) 199‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n      ‫ادعــت املدعيــة بأنهــا زوجــة للمدعــى عليــه وقــد ســاءت العشــرة بينهمــا‬\n      ‫وقــد خرجــت مــن بيــت زوجهــا ولهــا منــه ثالثــة أوالد ‪ :‬بنــت وعمرهــا‬\n      ‫ســبع ســنوات ‪ ،‬وابــن وعمــره ثــاث ســنوات‪ ،‬وبنــت وعمرهــا ســنة‬\n      ‫واحــدة وتطلــب احلكــم لهــا بحضانــة أوالدهــا‪ ،‬صــادق املدعــى عليــه‬\n      ‫علــى دعــوى املــرأة وأن األوالد اآلن عنــده وهــو غيــر مســتعد إلعادتهــم‬\n      ‫لوالدتهــم املدعيــة‪ ،‬ونظــر ًا لقولــه صلــى اهلل عليــه وســلم (أنــت أحــق بــه‬\n      ‫مــا لــم تنكحــي)‪ ،‬ولكــون األم أشــفق علــى أوالدهــا‪ ،‬احلكــم للمدعيــة‬\n      ‫بحضانــة أوالدهــا املذكوريــن يف الدعــوى واحلكــم علــى املدعــى عليــه‬\n      ‫بتســليمهم للمدعيــة مــع النفــاذ املعجــل‪ ،‬قرر املدعــى عليه اعتراضه على‬\n\n‫‪213‬‬\n\f‫احلكــم بالئحــة اعتراضيــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بالرياض‬\n‫ففــي يــوم الثالثــاء املوافــق‪ 1434/02/26‬ه ـ حضــرت ســعودية اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم () واملعــرف بهــا مــن قبــل أخيهــا حامــل‬\n‫الســجل املدنــي رقــم‪ :‬وادعــت علــى احلاضــر معهــا حامــل الســجل املدنــي‬\n‫رقــم‪ :‬قائلــة يف دعواهــا‪ :‬إن املدعــى عليــه زوجــي وقــد ســاءت العشــرة‬\n‫بيننــا فخرجــت مــن بيتــه قبــل شــهرين ومعــي أوالده منــه ‪ ....‬وعمرهــا‬\n‫ســبع ســنوات ‪ ....‬وعمــره ثــاث ســنوات ‪ ....‬وعمرهــا ســنة وقــد أخذهــم‬\n‫منــي بالقــوة وأطلــب احلكــم لــي بحضانــة أوالدي املذكوريــن وإلزامــه‬\n‫بتســليمهم لــي هــذه دعــواي وباســتجواب املدعــى عليــه قــال‪ :‬مــا ذكرتــه‬\n‫املدعيــة مــن أننــي زوجهــا وأن لــي منهــا األوالد املذكوريــن وأنهــم عنــدي‬\n‫حاليــا فصحيــح ومــا ذكرتــه مــن أنهــا خرجــت مــن بيتي قبل شــهرين وأن‬\n‫العشــرة بيننــا قــد ســاءت وأنــي أخــذت أوالدي منهــا بالقــوة فغيــر صحيــح‬\n‫والصحيــح أنهــا خرجــت مــن بيتــي قبــل ثالثــة أســابيع وأخــذت أوالدي‬\n‫معهــا ثــم ســلمتهم لــي ولســت مســتعدا بإعادتهــم لهــا‪ ،‬هكــذا أجــاب‪،‬‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولقــول النبــي صلــى اهلل عليــه‬\n‫وســلم(أنت أحــق بــه مالــم تنكحــي) ولكــون األم أشــفق علــى أوالدهــا‬\n‫وهــي التــي تعلــم بناتهــا أمــور النســاء وبنــاء علــى املــادة التاســعة والتســعني‬\n‫بعــد املائــة مــن نظــام املرافعــات الشــرعية لــذا فقــد حكمــت للمدعيــة‬\n‫بحضانــة أوالدهــا املذكوريــن يف الدعــوى وحكمــت علــى املدعــى عليــه‬\n‫بتســليمهم للمدعيــة مــع النفــاذ املعجــل بــدون كفالــة وبعــرض احلكــم‬\n\n                                                                                           ‫‪214‬‬\n\f      ‫علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب االســتئناف فأجبتــه لطلبــه‬\n      ‫وأفهمتــه بــأن عليــه املراجعــة يــوم األربعــاء املوافــق ‪1434/2/27‬ه ـ‬\n      ‫الســتالم صــورة مــن صــك احلكــم لالعتــراض عليه خالل مــدة ال تتجاوز‬\n      ‫ثالثــن يومــا مــن تاريــخ املوعــد احملــدد الســتالم الصــك فــإن تأخــر عــن‬\n      ‫ذلــك ســقط حقــه يف تقــدمي الالئحــة االعتراضيــة واكتســب احلكــم‬\n      ‫القطعيــة ‪،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/26‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/06/06‬ه ـ‬\n      ‫وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف بالريــاض وقــد همــش‬\n      ‫علــى ظهــر الصــك مبــا نصــه ( تظهيــرات دائــرة األحــوال الشــخصية‬\n                                   ‫واإلنهــاءات مبحكمــة االســتئناف بالريــاض‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪3449875‬‬\n      ‫وتاريــخ ‪1434/02/27‬ه ـ الصــادر مــن فضيلــة القاضــي يف احملكمــة‬\n      ‫الشــيخ وأصدرنــا القــرار رقــم ‪ 34216424‬وتاريــخ ‪1434/05/19‬ه ـ‬\n      ‫املتضمــن بأنــه لــم يظهــر مــا يوجــب االعتــراض‪ ،‬واهلل املوفــق‪ .‬قاضــي‬\n      ‫اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس‬\n      ‫الدائــرة ختمــه وتوقيعــه) وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                 ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/06/06‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتمييــز‬\n      ‫قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف بالرياض‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n      ‫املســاعد برقــم ‪ 34/664673‬وتاريــخ ‪1434/4/20‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ /‬املســجل برقــم‬\n\n\n‫‪215‬‬\n\f‫‪ 3449875‬وتاريــخ ‪1434/2/27‬ه ـ اخلــاص بدعــوى‪ ..........‬ضــد‪..........‬‬\n‫بشــأن حضانــة أوالد ‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه ‪ .‬حيــث ســبقت دراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه‬\n‫فضيلــة القاضــي وأحلقــه علــى الصــك وصــورة ضبطــه بنــاء علــى قرارنــا‬\n‫رقــم ‪ 34173908‬وتاريــخ ‪1434/3/28‬ه ـ لــم يظهــر ما يوجب االعتراض‬\n     ‫‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                 ‫‪216‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":213,"source_page_end":216,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9f15b67cc65ba77f114792d64bc7d6a392827f84e1bb14b4fbc40f8162a187f7","normalized_text_hash":"7996ac7217b6cede0b57bf6ba0b1987879bbe6eedf949c6c130b54f796769ab6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p213-3449875"},{"id":"218c917e-0713-5c47-86a6-4c02f7c10fd0","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب حضانة أوالد -طلب تسليم شهادة مياد وأوراق ثبوتية -األم أحق باحلضانة ما لم تتزوج -عدم حضور املدعى عليه مع تبلغه باملوعد -احلكم لأم بحضانة األوالد دون البلوغ -رد الدعوى بخصوص حضانة األوالد البالغن -اإللزام بتسليم شهادة املياد واألوراق الثبوتية -املطالبة بحضانة البالغ -املطالبة بحضانة من هو دون البلوغ.","document_number":"3455782","case_number":"3332588","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/4","year":"1434","subject":"حضانة -طلب حضانة أوالد -طلب تسليم شهادة مياد وأوراق ثبوتية -األم أحق باحلضانة ما لم تتزوج -عدم حضور املدعى عليه مع تبلغه باملوعد -احلكم لأم بحضانة األوالد دون البلوغ -رد الدعوى بخصوص حضانة األوالد البالغن -اإللزام بتسليم شهادة املياد واألوراق الثبوتية -املطالبة بحضانة البالغ -املطالبة بحضانة من هو دون البلوغ.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3455782 :‬تاريخه ‪1434/3/4 :‬هـ‬\n                         ‫رقم الدعوى ‪3332588:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34268217‬تاريخه‪1434/07/15:‬هـ‬\n\n\n      ‫حضانــة ‪ -‬طلــب حضانــة أوالد ‪ -‬طلــب تســليم شــهادة ميــاد وأوراق‬\n      ‫ثبوتيــة ‪ -‬األم أحــق باحلضانــة مــا لــم تتــزوج ‪ -‬عــدم حضــور املدعــى‬\n      ‫عليــه مــع تبلغــه باملوعــد ‪ -‬احلكــم لــأم بحضانــة األوالد دون البلــوغ‬\n      ‫‪ -‬رد الدعــوى بخصــوص حضانــة األوالد البالغــن ‪ -‬اإللــزام بتســليم‬\n      ‫شــهادة امليــاد واألوراق الثبوتيــة ‪ -‬املطالبــة بحضانــة البالــغ ‪ -‬املطالبــة‬\n                                                   ‫بحضانــة مــن هــو دون البلــوغ‪.‬‬\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم للمــرأة التــي ســألته ‪ ( :‬يــا رســول اهلل أن‬\n      ‫ابنــي هــذا كان بطنــي لــه حــواء وثــدي لــه ســقاء وإن أبــاه طلقنــي وأراد‬\n      ‫أن ينزعــه منــي قــال ‪ ( :‬أنــت أحــق بــه مــا لــم تنكحــي ) رواه أبــو داود عــن‬\n                                             ‫عمــرو بــن شــعيب عــن أبيــه عــن جــده ‪.‬‬\n                     ‫‪ .2‬املادة ( ‪ -10/34‬فقرة هـ ) من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة أنهــا كانــت زوج ـ ًا للمدعــى عليــه وأجنبــت منــه علــى‬\n      ‫فــراش الزوجيــة خمســة أوالد وهــؤالء األوالد بحضانــة املدعــى عليــه‬\n      ‫ســوى األخيــرة وتطلــب حضانــة أوالدهــا كمــا تطلــب تســليم شــهادة‬\n      ‫امليــاد البنتهــا ‪ ...‬وأوراقهــا الثبوتيــة‪ ،‬لــم يحضــر املدعــى عليــه اجللســة‬\n\n‫‪217‬‬\n\f‫مــع تبلغــه مبوعــد اجللســة وتوقيعــه بعلمــه بهــا‪ ،‬ســمعت دعــوى املدعيــة يف‬\n‫مقــر إقامتهــا وجــرى إرســال صــورة مــن ضبــط الدعــوى حملكمــة البلــد‬\n‫الــذي يقيــم فيــه املدعــي عليــه وقــد مت إرســال عدة تعقيبات‪،‬قــررت املرأة‬\n‫تضررهــا مــن ترددهــا علــى احملكمــة بــدون حكــم‪ ،‬مت ســؤال املرأة هل‬\n‫أنــت متزوجــة فأجابــت بقولهــا ال ‪ ،‬ومت ســؤالها هــل ‪ ...‬و‪ ...‬بلغــوا فأجابــت‬\n‫بقولهــا نعــم ومــن دونهــم لــم يبلغــوا‪ ،‬مت ســؤالها مــا هــي األوراق الثبوتيــة‬\n‫التــي تطالــب بهــا فأجابــت شــهادة امليــاد وشــهادة التطعيــم وصــورة مــن‬\n‫ســجل العائلــة‪ ،‬احلكــم بحضانــة ‪ ...‬و‪ ...‬للمدعيــة‪ ،‬رد دعــوى املدعيــة‬\n‫طلــب حضانــة ‪ ...‬و‪ ...‬لبلوغهــم‪ ،‬علــى املدعــى عليــه تســليم شــهادة امليــاد‬\n‫البنتيــه ‪ ...‬وشــهادة التطعيــم وصــورة مــن ســجل العائلــة للمدعيــة‪ ،‬اعتبــار‬\n‫احلكــم حضوريـ ًا نظــر ًا لتبلــغ املدعــى عليــه لشــخصه إلحــدى جلســاته‪،‬‬\n‫بلــغ املدعــى عليــه بنســخة مــن صــورة احلكــم وإفهامــه مــدة االعتــراض‬\n‫النظاميــة وهــي ثالثــون يوم ـ ًا مــن تاريــخ اســتالمه للحكــم‪ ،‬صــدق‬\n                                          ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 3332588‬وتاريــخ‬\n‫‪1433/01/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3383373‬وتاريــخ‬\n‫‪1433/01/12‬ه ـ حضــرت ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم وانتظــر املدعــى عليــه ولــم يحضــر وقــد وردنــا خطــاب امــن‬\n‫احملكمــة العامــة بالدمــام برقــم ‪ 33351832‬يف ‪1433/3/2‬ه ـ ومفــاده‬\n\n                                                                                       ‫‪218‬‬\n\f      ‫مت ابــاغ املدعــى عليــه باحلضــور يف جلســة ‪1433/2/27‬ه ـ وبســؤال‬\n      ‫املدعيــة عــن دعواهــا قالــت ان املدعــى عليــه كان زوجــا لــي واجنبــت‬\n      ‫منــه علــى فــراش الزوجيــة خمســة اوالد وهــم املولــود يف ‪1418/7/19‬ه ـ‬\n      ‫و املولــود يف ‪1420/10/18‬ه ـ و املولــودة يف ‪1422/1/8‬ه ـ و وعمــره‬\n      ‫ســبع ســنوات و وقــد طلقنــي مــن ســنه واالوالد املذكــورون يف حضانتــه‬\n      ‫ســوى األخيــرة فهــي يف حضانتــي اطلــب احلكــم لــي بحضانــة االوالد‬\n      ‫األربعــة املذكوريــن وتســليمي شــهادة ميــاد واوراقهــا الثبوتيــة هــذه‬\n      ‫دعــواي واملدعــى عليــه يقيــم بالدمــام ويعمــل برتبــة عريــف يف الدفــاع‬\n      ‫املدنــي بحــي العدامــة وجوالــه هــو لــذا قــررت بعــث صــورة الضبــط الــى‬\n      ‫محكمــة الدمــام ألخــذ اجابــة املدعــى عليــه حســب الالئحــة هــ‪10/34/‬‬\n      ‫لنظــام املرافعــات الشــرعية ويف جلســة أخــرى حضــرت املدعيــة وقــد‬\n      ‫جــرت الكتابــة الــى محكمــة الدمــام بخطابنــا رقــم ‪ 33662098‬يف‬\n      ‫‪1433/4/11‬ه ـ لســماع اجابــة املدعــى عليــه ولــم يردنــا جوابهــم حتــى‬\n      ‫االن واضافــت املدعيــة بقولهــا ان املدعــى عليــه قــد جعــل اوالدي‬\n      ‫املدعــى بحضانتهــم عنــد عمتهــم وال يهتــم بشــئونهم وال يقــوم بأمورهــم‬\n      ‫وقــد كلمونــي قريبــا وشــكوا الــى حالهــم هكــذا قالــت لــذا قــررت‬\n      ‫التعقيــب علــى خطابنــا الســابق ويف جلســة أخــرى حضــرت املدعيــة‬\n      ‫وانتظــر املدعــى عليــه ولــم يحضــر ولــم يردنــا مــن محكمــة الدمــام‬\n      ‫اجلــواب علــى اســتخالفنا مــع أنــه جــرى التعقيــب علــى ذلــك بخطابنــا رقــم‬\n      ‫‪ 33/1122513‬يف ‪1433/6/16‬ه ـ لــذا ســيجري التعقيــب عليــه مــرة‬\n      ‫أخــرى ويف جلســة أخــرى حضــرت املدعية وقد جرت مخاطبة احملكمة‬\n      ‫العامــة بالدمــام بخطابنــا رقــم ‪ 332272134‬يف ‪1433/12/29‬ه ـ ولــم‬\n      ‫يردنــا رد حتــى االن ثــم قالــت املدعيــة اننــي تضــررت مــن جــراء تــرددي‬\n\n\n‫‪219‬‬\n\f‫علــى احملكمــة لــذا اطلــب احلكــم يف القضيــة ولــو لــم يحضــر املدعــى‬\n‫عليــه ثــم ســالتها عــن اوالدهــا هــل بلغــوا فقالــت نعــم ومــن دونهــم لــم يبلــغ‬\n‫ثــم ســالتها هــل انــت متزوجــه حاليــا فقالــت ال لــم اتــزوج فســالتها ماهــي‬\n‫االوراق الثبوتيــة التــي تطالــب بهــا فقالــت شــهادة ميــاد ابنتــه وشــهادة‬\n‫التطعيــم لهــا وصــورة مــن ســجل العائلــة لــه الــذي يحتــوي علــى اســمها‬\n‫وبعــد النظــر يف الدعــوى ونظــرا لكــون املدعــى عليــه قــد تبلــغ اول مــره‬\n‫ولــم يحضــر دون عــذر مقبــول ونظــرا ملــا طلبتــه املدعيــة مــن احلكــم يف‬\n‫القضيــة والن االصــح مــن اقــوال اهــل العلــم ان االم احــق باحلضانــة مالــم‬\n‫تتــزوج او يبلــغ احملضــون فيختــار لنفســه تأسيســا علــى قولــه صلــى اهلل‬\n‫عليــه وســلم للمــرأة التــي ســالته يــا رســول اهلل ان ابنــي هــذا كان بطنــي‬\n‫لــه حــواء وثــدي لــه ســقاء وان ابــاه طلقنــي واراد ان ينزعــه منــي قــال (انــت‬\n‫احــق بــه مالــم تنكحــي) رواه ابــو داود عــن عمــرو بــن شــعيب عــن ابيــه‬\n‫عــن جــده وامــا البالــغ فانــه يختــار لنفســه فــا يلــزم ان يكــون مــع أي مــن‬\n‫ابويــه والن املدعيــة قــررت انهــا لــم تتــزوج وان ولديهــا الزالــوا لــم يبلغــوا‬\n‫وامــا فقــد بلغــوا فــا يتوجــه االلــزام بشــأنهم يف احلضانــة والن مصلحــة‬\n‫احملضونــة ولوازمهــا تســليم شــهادة امليــاد والتطعيــم وصــورة مصدقــه‬\n‫مــن ســجل العائلــة للمدعــى عليــه الــذي فيــه اســم ابنتــه لذلــك كلــه‬\n‫فقــد حكمــت علــى املدعــى عليــه ان يســلم ولديــه للمدعيــة لتحضنهــم‬\n‫وعليــه ان يســلمها شــهادة ميــاد ابنتــه ‪ ...‬وشــهادة التطعيــم لهــا وصــورة‬\n‫مــن ســجل العائلــة لــه الــذي يحتــوي علــى اســم ابنتــه وردت دعــوى املدعيــة‬\n‫بحضانــة لبلوغهــم وبعرضــه علــى املدعيــة قــررت القناعــة بــه ويعتبــر هــذا‬\n‫احلكــم حضوريــا نظــرا لتبلــغ املدعــى عليــه بشــخصه إلحــدى جلســاته‬\n‫وســوف يبلــغ بنســخة منــه إلبــداء اعتراضــه عليــه ان رغــب ذلــك ويفهــم‬\n\n\n                                                                                           ‫‪220‬‬\n\f      ‫بتعليمــات االســتئناف ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/30‬ه ـ‬\n      ‫احلمد هلل وحده وبعد ففي يوم السبت املوافق‪ 1434/06/24‬هـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 10.5‬وفيهــا حضــرت املدعيــة وقــد وردتنــا املعاملــة مــن‬\n      ‫محكمــة االســتئناف بخطابهــا رقــم ‪ 3383373‬يف ‪1434/6/11‬ه ـ‬\n      ‫مرفــق بــه القــرار رقــم ‪ 34234363‬يف ‪1434/6/7‬ه ـ ونــص احلاجــة منــه‬\n      ‫بعــد دراســة القضيــة تقــرر باألكثريــة إعادتهــا حلاكمها لكــون املدعى‬\n      ‫عليــه ذكــر أنــه يوجــد أبنــاء ألخــت املدعيــة يف املنــزل نفســه وهــم كبــار‬\n      ‫يف الســن وال يطمئــن علــى ابنتــه مــن التعــدي مــن قبــل هــؤالء األبنــاء‬\n      ‫أ‪.‬ه ـ وبعرضــه علــى املدعيــة قالــت إن أختــي تســكن يف بيــت مســتقل‬\n      ‫بجانــب بيتــي وقــد أســكننا والدنــا كل واحــده يف بيــت شــعبي مســتقل‬\n      ‫مبنافعــه وأختــي ال تســكن معــي يف البيــت نفســه وليــس لهــا إال ابنــان‬\n      ‫فقــط أحدهمــا وعمــره عشــر ســنوات والثانــي وعمــره خمــس ســنوات‬\n      ‫وبقيــة أوالدهــا بنــات هكــذا قــررت لــذا لــم يظهــر لــي خــاف مــا قضيــت‬\n      ‫بــه‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم ‪ .‬حــرر يف ‪1434/06/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/07/30‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 12.15‬وفيهــا فقــد عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف برقــم ‪ 3383373‬يف ‪1434/7/22‬ه ـ وبرفقهــا‬\n      ‫القــرار رقــم ‪ 34268217‬يف ‪1434/7/15‬ه ـ واملــدون علــى ظهــر الصــك‬\n      ‫باملوافقــة علــى احلكــم لــذا جــرى إحلاقــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/30‬هـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n\n\n‫‪221‬‬\n\f‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 3383373‬وتاريــخ ‪1434/7/8‬هـ ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪ ..........‬القاضــي باحملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم‪ 3455782‬وتاريــخ ‪1434/3/4‬ه ــ‪،‬‬\n‫املتضمــن دعــوى املــرأة ضــد بشــأن حضانــة األوالد‪ ،‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة‪ ،‬تقــررت املوافقــة علــى احلكــم‬\n‫بعــد اإلحلــاق األخيــر املبنــي علــى قــرار املالحظــة ‪ ،‬واهلل املوفــق ‪ .‬وصلــى‬\n                        ‫اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪222‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":217,"source_page_end":222,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1cd704a0bf537991fb2db62be79044ad0d74360ddd5a7b89c088b905f0aafe19","normalized_text_hash":"d5b13d1db9955dd56cd3cbf1ee5b1e85d21c1c9447efc17f28ee0012ca1a3924","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p217-3455782"},{"id":"97a0812a-a4d2-5fa5-b0c4-eb4d46c80130","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -حضانة من دون السابعة -طلب األم حضانة األوالد - األم أحق باحلضانة ما لم تنكح -احلكم بأحقية األم باحلضانة -احلكم بحضانة ابن عمره سبع سنوات لوالدته من دون تخيير بن األب و األم لصالحية األم خالف ا لقاعدة التخيير .","document_number":"34228116","case_number":"3464499","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/3","year":"1434","subject":"حضانة -حضانة من دون السابعة -طلب األم حضانة األوالد - األم أحق باحلضانة ما لم تنكح -احلكم بأحقية األم باحلضانة -احلكم بحضانة ابن عمره سبع سنوات لوالدته من دون تخيير بن األب و األم لصالحية األم خالف ا لقاعدة التخيير .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34228116 :‬تاريخه ‪1434/6/3 :‬هـ‬\n                          ‫رقم الدعوى ‪3464499:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34237011‬تاريخه‪1434/06/11 :‬هـ‬\n\n\n      ‫حضانــة ‪ -‬حضانــة مــن دون الســابعة ‪ -‬طلــب األم حضانــة األوالد ‪-‬‬\n      ‫األم أحــق باحلضانــة مــا لــم تنكــح ‪ -‬احلكــم بأحقيــة األم باحلضانــة‬\n      ‫‪ -‬احلكــم بحضانــة ابــن عمــره ســبع ســنوات لوالدتــه مــن دون تخييــر‬\n                 ‫بــن األب و األم لصالحيــة األم خالفـ ًـا لقاعــدة التخييــر ‪.‬‬\n\n\n\n\n                   ‫قوله صلى اهلل عليه وسلم ( أنت أحق به ما لم تنكحي ) ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة بأنهــا كانــت زوجــة للمدعــى عليــه ومت فســخ نكاحهــا‬\n      ‫منــه يف تاريــخ ‪1434/6/28‬ه ـ وقــد أجنبــت منــه علــى فــراش الزوجيــة‬\n      ‫أربعــة مــن األوالد األول ذكــر وعمــره ســبع ســنوات والثانــي ذكــر‬\n      ‫وعمــره ســت ســنوات والثالــث بنــت وعمرهــا خمــس ســنوات والرابــع‬\n      ‫ذكــر وعمــره ســنة وأربعــة أشــهر وولديهــا الثالــث والرابــع يف رعايتهــا‬\n      ‫وحضانتهــا منــذ ســنتني وهــي لــم تتــزوج بعــد فســخ نكاحهــا مــن املدعــى‬\n      ‫عليــه وتطلــب يف دعواهــا احلكــم لهــا باحلضانــة‪ ،‬بســؤال املدعــى عليــه‬\n      ‫صــادق علــى مــا ذكرتــه وال يوافــق علــى حضانتهــا لولديهــا املذكوريــن‬\n      ‫وطلــب حضانتهمــا‪ ،‬بعــرض ذلــك علــى املدعيــة قالــت إنــي أطالــب‬\n      ‫بحضانتهمــا لصغــر ســنهما‪ ،‬بنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة‪،‬‬\n\n‫‪223‬‬\n\f‫ونظــر ًا لقولــه صلــى اهلل عليــه وســلم ( أنــت أحــق بــه مــا لــم تنكحــي)‬\n‫وحلصــول التنــازع بينهمــا باحلضانــة‪ ،‬ومطالبة املدعــى عليه بهما‪،‬احلكم‬\n‫بحضانــة الولديــن املذكوريــن للمدعيــة‪ ،‬قــرر املدعــى عليــه اعتراضــه‬\n‫علــى احلكــم بالئحــة اعتراضيــة فأفهــم بتعليمــات االســتئناف‪ ،‬صــدق‬\n                                       ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 3464499‬وتاريــخ ‪ 1434/02/09‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34323270‬وتاريــخ ‪ 1434/02/09‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/06/03‬ه ـ افتتحــت اجللســة الســاعة التاســع‬\n‫وعشــر دقائــق وكان الوقــت احملــدد لهــا هــو الســاعة الثامنــة والنصــف‬\n‫وفيهــا حضــرت‪ .......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬‬\n‫واملعــرف بهــا مــن قبــل أخيهــا ‪.......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ،.......‬وادعــت علــى علــى احلاضــر معهــا ‪.......‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬قائلــة يف دعواهــا ان املدعــى‬\n‫عليــه كان زوجــي مت فســخ نكاحــي منــه يف تاريــخ ‪1433/6/28‬ه ـ‬\n‫وقــد اجنبــت لــه علــى فــراش الزوجيــة أربعــة مــن األوالد ‪.......‬وعمــره ســبع‬\n‫ســنوات والثانــي ‪ .......‬وعمــره ســت ســنوات والثالــث ‪.......‬وعمرهــا خمــس‬\n‫ســنوات والرابــع ‪ .......‬وعمــره ســنة وأربعــة اشــهر وولــدي ‪ .......‬و‪ .......‬يف‬\n‫رعايتــي وحتــت حضانتــي منــذ ســنتني تقريبــا وأنــا لــم اتــزوج بعــد فســخ‬\n‫نكاحــي منــه واننــي أطلــب يف دعــواي هــذه احلكــم لــي بحضانــة ولــدي‬\n\n                                                                                      ‫‪224‬‬\n\f      ‫املذكوريــن ‪.......‬و‪ .......‬هــذه دعــواي وبســؤال املدعــى عليــه قــال كل‬\n      ‫مــا ذكرتــه املدعيــة يف دعواهــا صحيــح وانــا ال أوافــق علــى حضانتهــا‬\n      ‫لهمــا وأطلــب حضانتهمــا لــي هــذا مــا لــدي ‪ ،‬وبعــرض ذلــك علــى املدعيــة‬\n      ‫قالــت اننــي اطالــب بحضانتهمــا لــي لصغــر ســنهما هــذا مــا لــدي ‪ ،‬وبنــاء‬\n      ‫علــى مــا ســبق مــن الدعــوى واالجابــة ‪ ،‬ولقولــه صلــى اهلل عليــه وســلم‪:‬‬\n      ‫(انــت أحــق بــه مــا لــم تنكحــي) ‪ ،‬وحلصــول التنــازع بينهمــا باحلضانــة‬\n      ‫ومطالبــة املدعــى عليــه بهــا ‪ ،‬لذلــك كلــه فقــد حكمــت بحضانــة‬\n      ‫الولديــن املذكوريــن ‪.......‬و‪ .......‬للمدعيــة وبعــرض احلكــم علــى املدعــى‬\n      ‫عليــه ‪ ،‬قــرر عــدم القناعــة وطلــب رفــع املعاملــة إلــى محكمــة االســئناف‬\n      ‫‪ ،‬فأجبتــه إلــى طلبــه وأفهمتــه بــأن ســوف يســلم صــورة مــن نســخة‬\n      ‫احلكــم هــذا اليــوم وأن لــه مهلــة ثالثــن يومــا مــن تاريــخ اســتالمه صــورة‬\n      ‫احلكــم لتقــدمي اعتراضــة ‪ ،‬فــإذا انتهــت املهلــة ولــم يتقــدم باعتراضــه‬\n      ‫ســقط حقــه يف االعتــراض واصبــح احلكــم نافــذا ‪ ،‬وبــه ختمــت اجللســة‬\n      ‫يف متــام الســاعة التاســعة والنصــف ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/03‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/06/20‬ه ـ‬\n      ‫افتتحت اجللســة الســاعة ‪ 12 : 30‬وقد عادت املعاملة إلينا من محكمة‬\n      ‫االســتئناف باخلطــاب رقــم ‪ 341360094‬يف ‪1434/6/14‬ه ـ وبرفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة الثانيــة املختصــة بنظــر قضايــا األحــوال‬\n      ‫الشــخصية واالنهــاءات رقــم ‪ 34237011‬يف ‪1434/6/11‬ه ـ املتضمــن‪:‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫تقــرر الدائــرة املصادقــة علــى احلكــم ‪ .‬وعليــه فجــرى التهميش مبوجبه‪،‬‬\n      ‫وبــه ختمــت اجللســة الســاعة ‪ . 12 : 40‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n\n\n‫‪225‬‬\n\f     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/20‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد برقــم ‪ 34323270‬وتاريــخ ‪1434/6/5‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪....... /‬‬\n‫املســجل برقــم ‪34228116‬وتاريــخ ‪1434/6/3‬ه ـ اخلــاص بدعــوى ‪....... /‬‬\n‫ضــد‪ ....... /‬يف قضيــة حضانــة‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫مباهــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ‪،‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":223,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"32b786979a183e56aaccc142afcacb8b5f478fe601a4aa08ff9b4605b43aa8a9","normalized_text_hash":"5aacfa2bee15e084bb671eac7782ef906703f6d0a79760674ec795f76cdc8e2c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p223-34228116"},{"id":"0d955932-b238-5e2e-b23e-1764150080de","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -األم أحق بحضانة األوالد ما لم تتزوج -تقدير األحق باحلضانة وحتديد مدة الزيارة عن طريق قسم اخلبراء -النظر يف طلب عارض بالزيارة والبت فيه -رد الدعوى واحلكم لألم باحلضانة وإلزامها بتمكن املدعى لزيارة ابنتيه املذكورتن .","document_number":"33417800","case_number":"32379563","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/23","year":"1434","subject":"حضانة -األم أحق بحضانة األوالد ما لم تتزوج -تقدير األحق باحلضانة وحتديد مدة الزيارة عن طريق قسم اخلبراء -النظر يف طلب عارض بالزيارة والبت فيه -رد الدعوى واحلكم لألم باحلضانة وإلزامها بتمكن املدعى لزيارة ابنتيه املذكورتن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33417800:‬تاريخه‪1433/9/23:‬هـ‬\n                        ‫رقم الدعوى‪32379563:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34264426‬تاريخه‪1434/7/10:‬هـ‬\n\n\n      ‫حضانــة ‪ -‬األم أحــق بحضانــة األوالد مــا لــم تتــزوج ‪ -‬تقديــر األحــق‬\n      ‫باحلضانــة وحتديــد مــدة الزيــارة عــن طريــق قســم اخلبــراء ‪ -‬النظــر يف‬\n      ‫طلــب عــارض بالزيــارة والبــت فيــه ‪ -‬رد الدعــوى واحلكم لألم باحلضانة‬\n                         ‫وإلزامهــا بتمكــن املدعــى لزيــارة ابنتيــه املذكورتــن ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (أنــت أحــق بــه مــا لــم تنكحــي) أخرجــه‬\n                 ‫أبــو داود واإلمــام أحمــد واحلاكــم وصححــه ووافقــه الذهبــي‪.‬‬\n      ‫‪ .2‬جــاء يف زاد املعــاد ص (‪ )390‬مــا نصــه (أن هــذا احلديــث دل علــى أنــه‬\n      ‫إذا افتــرق األبــوان وبينهمــا ولــد فــاألم أحــق بــه مــن األب مــا لــم يقــم‬\n      ‫بــاألم مــا مينــع تقدميهــا أو بالولــد وصــف يقتضــي تخييــره وهــذا مــا ال‬\n                                                                   ‫يعــرف فيــه نــزاع)‪.‬‬\n                                   ‫‪ .3‬املادة (‪/79‬هـ) من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليهــا بأنــه ســبق أن طلــق املدعــى عليهــا‬\n      ‫طالقــا بائن ـ ًا وقــد رزق منهــا بابنتــن وأنهــا تســكن اآلن لوحدهــا يف‬\n      ‫بيــت ملــك لهــا ومعهــا ابنتاهمــا املذكورتــان آنفــا ويطلــب احلكــم‬\n      ‫لــه بحضانــة هاتــن االبنتــن هكــذا ادعــى‪ ،‬أجابــت املدعــى عليهــا‬\n\n‫‪227‬‬\n\f‫باملصادقــة علــى الطــاق واجنابهــا منــه االبنتــن املذكورتــن وال توافقــه‬\n‫علــى طلبــه حضانتهمــا نظــرا ألنهــا مــا زالــت غيــر متزوجــة وأنهــا امــرأة‬\n‫مســتقيمة وتســكن يف بيــت مملــوك لهــا وأن املدعــي ســوف يســكنهما‬\n‫عنــد زوجــة لــه وتخشــى علــى ابنتيهــا منــه ال ســيما أن أحــد البنتــن بهــا‬\n‫إعاقــة‪ ،‬صــادق املدعــي علــى اإلعاقــة وعلــى أن البنتــن ستســكنان مــع‬\n‫زوجتــه وعلــى أن املدعــى عليهــا لــم تتــزوج‪ ،‬جــرى الكتابــة للمستشــفى‬\n‫لإلفــادة بتقريــر مفصــل عــن حالــة البنــت فــورد جوابهــم بأنهــا تعانــي مــن‬\n‫استســقاء خلقــي بالعمــود الفقــري أدى إلــى شــلل غيــر تــام بالطرفــن‬\n‫الســفليني مــع صعوبــة شــديدة باملشــي مــع وجــود عيــوب بالقلــب وأنهــا‬\n‫حتتــاج إلــى رعايــة خاصــة‪ ،‬ونظــر ًا ألن املدعــى عليهــا لــم تتــزوج وقــد‬\n‫صــادق املدعــي علــى ذلــك‪ ،‬وألن املدعــي لــم يثبــت عــدم صالحيــة‬\n‫املدعــى عليهــا حلضانــة ابنتيهــا ولقــرار هيئــة اخلبــراء (تــرى أن تكــون‬\n‫حضانــة البنتــن لــأم مــا لــم تتــزوج)‪ ،‬وملــا قــرره أهــل العلــم مــن أن أحــق‬\n‫النــاس باحلضانــة هــي األم لقولــه عليــه الصــاة والســام‪ (( :‬أنــت أحــق‬\n‫بــه مــا لــم تنكحــي)) أخرجــه أبــو داود وأحمــد واحلاكــم‪ ،‬وألن املدعــي‬\n‫قــد قــدم طلب ـ ًا عارض ـ ًا يطلــب فيــه حتديــد موعــد لــه لزيــارة ابنتيــه‪ ،‬ملــا‬\n‫تقــدم احلكــم مبــا يلــي أو ًال رد دعــوى املدعــي وقــرر القاضــي أن املدعــى‬\n‫عليهــا هــي األحــق بحضانــة ابنتيهــا مــا لــم يقــم املدعــى عليهــا مــا مينــع مــن‬\n‫تقدميهــا أو بــكل واحــدة مــن هاتــن البنتــن وصــف يقتضــي تخييرهمــا‬\n‫ثاني ـ ًا إلــزام املدعــى عليهــا بتمكــن املدعــي مــن زيــارة ابنتيــه مرتــن‬\n‫يف األســبوع بحيــث يأخذهمــا الســاعة اخلامســة مســاء ويعيدهمــا إلــى‬\n‫والدتهمــا املدعــى عليهــا الســاعة التاســعة مســاء كل يــوم أحــد وأربعــاء‪،‬‬\n                                     ‫اعتــرض املدعــي بالئحــة‪ ،‬صــدق احلكــم‪.‬‬\n\n\n                                                                                            ‫‪228‬‬\n\f      ‫احلمــد هلل وحــده وبعــد يف يــوم اإلثنــن املوافــق ‪1432/10/28‬ه ـ لــدي أنــا‬\n      ‫‪ ...‬القاضــي باحملكمــة العامــة بعنيــزة افتتحــت اجللســة يف وقتهــا احملــدد‬\n      ‫لســماعها يف الســاعة التاســعة صباحــا للنظــر يف الدعــوى املقدمــة مــن ‪...‬‬\n      ‫ضد ‪...‬واملقيدة يف هذه احملكمة برقم ‪ 32/037769‬يف ‪1432/8/11‬هـ‬\n      ‫واحملالــة لنــا بشــرح فضيلــة الرئيــس والتــي ســبق أن صــدر فيهــا صــك‬\n      ‫احلكــم رقــم ‪ 6/47‬يف ‪1431/11/8‬ه ـ والــذي نقــض مــن الدائــرة‬\n      ‫املختصــة بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة‬\n      ‫اإلســتئناف مبنطقــة القصيــم رقــم ‪/597‬ش‪/‬ن يف ‪1432/7/27‬ه ـ‬\n      ‫واملقــرر فيــه أيضــا إحالتهــا إلــى قــاض آخــر للنظــر فيهــا مــن جديــد أ‪.‬هــ‪.‬‬\n      ‫وقــد حضــر فيهــا ‪...‬ســعودي مبوجــب الســجل رقــم ‪...‬وادعــى علــى‬\n      ‫احلاضــرة معــه ‪...‬ســعودية بالســجل رقــم ‪ ...‬واملعــرف بهــا مــن قبــل املدعــي‬\n      ‫قائــا يف حتريــر دعــواه لقــد ســبق أن طلقــت املدعــى عليها هــذه احلاضرة‬\n      ‫طالقــا بائنــا يف ‪1430/5/22‬ه ـ وقــد رزقــت منهــا بابنتــن همــا ‪...‬املولودة‬\n      ‫يف ‪1420/11/14‬ه ـ و‪ ...‬املولــودة يف ‪1425/5/8‬ه ـ وهــي تســكن اآلن‬\n      ‫لوحدهــا يف بيــت ملــك لهــا يف حــي ‪ ...‬بعنيــزة ومعهــا ابنتــاي املذكورتــن‬\n      ‫آنفــا أطلــب احلكــم لــي بحضانــة هاتــن اإلبنتــن هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليهــا عمــا جــاء يف دعــوى املدعــي أجابــت قائلــة ماذكــره‬\n      ‫املدعــي مــن طالقــه لــي وأن لــي منــه اإلبنتــن املذكورتــن يف الدعــوى‬\n      ‫فهــذا صحيــح وأمــا ماطالــب بــه مــن طلبــه احلضانــة لهمــا فأنــا ال أوافــق‬\n      ‫علــى ذلــك ولــن أتخلــى عنهمــا نظــرا ألننــي مازلــت غيــر متزوجــة وأنــا‬\n      ‫امــرأة مســتقيمة وأســكن يف بيــت مملــوك لــي وأمــا املدعــي فإنــه ســوف‬\n\n‫‪229‬‬\n\f‫يســكنهما عنــد زوجــة لــه وأنــا أخشــى علــى ابنتــي منــه ال ســيما أن ابنتي‬\n‫‪...‬معاقــة هكــذا أجابــت وبعــرض ذلــك علــى املدعــي قــال إننــي ال أوافــق‬\n‫علــى أن تكــون املدعــى عليهــا حاضنــة إلبنتــي نظــرا ألنهــا امــرأة ســليطة‬\n‫اللســان وذات شــخصية قويــة وهــذا يؤثــر علــى ابنتــي وعلــى نفســياتهما‬\n‫وأمــا ماذكرتــه املدعــى عليهــا مــن أن ابنتــي ‪...‬معاقــة فهــذا صحيــح‬\n‫كمــا أن ماذكرتــه أيضــا مــن أننــي ســوف أقــوم بإســكانهما عنــد‬\n‫زوجتــي ‪...‬والتــي لــي منهــا عشــرة أوالد فهــذا صحيــح ولكــن لــن يصــل‬\n‫ابنتــي منهــا أي أذى إن شــاء اهلل ثــم رفعــت اجللســة ويف يــوم الســبت‬\n‫املوافــق ‪1433/1/8‬ه ـ افتتحــت اجللســة يف الســاعة العاشــرة صباحــا‬\n‫وفيهــا حضــر املدعــي ولــم حتضــر املدعــى عليهــا وال مــن ينــوب عنهــا ولــم‬\n‫تقــدم عــذرا لذلــك ثــم جــرى االطــاع منــا علــى بطاقــة عائلــة املدعــي‬\n‫فتبني منها أن ميالد ‪...‬يف ‪1425/5/8‬هـ وأن ميالد ‪...‬يف ‪1420/11/14‬هـ‬\n‫ثــم جــرى ســؤال املدعــي عــن نوعيــة إعاقــة ابنتــه ‪...‬فقــال إن لديهــا ضمــور‬\n‫يف قدمهــا اليمنــى وهــي تســتطيع املشــي مــن دون عصــا ثــم رفعــت اجللســة‬\n‫لســؤال املدعــى عليهــا حــن حضورهــا عــن نوعيــة إعاقــة ابنتهــا ‪...‬أيضــا‬\n‫وطلــب تقريــر طبــي منهمــا عــن إعاقتهــا وكــذا ســؤال املدعــى عليهــا هــل‬\n‫هــي متزوجــة أم ال مــع عــرض الصلــح عليهمــا قــدر املســتطاع فــإن لــم‬\n‫يصطلحــا فيســأل املدعــي عــن قدحــه يف املدعــى عليهــا مفصــا ثــم‬\n‫رفعــت اجللســة ويف يــوم األحــد ‪1433/2/7‬هـ افتتحت اجللســة يف الســاعة‬\n‫احلاديــة عشــر صباحــا وفيهــا حضــر املدعــي واملدعــى عليهــا واملعــرف بهــا‬\n‫مــن قبــل املدعــي ثــم جــرى ســؤال املدعــى عليهــا عمــا ذكــره املدعــي عــن‬\n‫اعاقــة ابنتهمــا ‪...‬فقالــت إن ماذكــره املدعــي ‪ ...‬غيــر صحيــح نظــرا ألن‬\n‫ابنتنــا ‪...‬تعانــي مــن مــرض يســمى الصلــب املشــقوق وهــو ضعــف عــام يف‬\n\n\n                                                                                      ‫‪230‬‬\n\f      ‫الظهــر واألطــراف والتســتطيع املشــي إال مبســاعدة مــن أحــد ثــم جــرى‬\n      ‫ســؤالها هــل أنــت متزوجــة حاليــا فقالــت إننــي مازلــت غيــر متزوجــة‬\n      ‫وعنــدي أصــل صــك طالقــي مــن املدعــي مثبــت فيــه أننــي مازلــت مطلقــة‬\n      ‫حيــث لــم يهمــش عليــه بزواجــي مــن أحــد ثــم جــرى عــرض الصلــح علــى‬\n      ‫املتداعيــن قــدر املســتطاع وافهامهمــا بــأن مراعــاة مصلحــة ابنتيهمــا‬\n      ‫أمــر مهــم ومؤثــر مســتقبال عليهــا فأصــر كل واحــد مهمــا علــى موقفــه‬\n      ‫وطلبــه ثــم أفهمتهمــا بضــرورة احضــار تقريــر طبــي إلبنتهمــا ‪...‬وأفهمــت‬\n      ‫املدعــى عليهــا بإحضــار أصــل طــاق املدعــي لهــا ففهمــا ذلــك واســتعدا‬\n      ‫بــه ثــم رفعــت اجللســة ويف يــوم الثالثــاء املوافــق ‪1433/3/15‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة التاســعة صباحــا وفيهــا حضــر املدعــي واملدعــى‬\n      ‫عليهــا واملعــرف بهــا مــن قبــل املدعــي ثــم أبــرزت املدعــى عليهــا صــورة مــن‬\n      ‫صــك الطــاق الصــادر من هــذه احملكمة برقم ‪ 6/8‬يف ‪1430/5/22‬هـ‬\n      ‫املثبت فيه ‪...‬لزوجته ‪...‬طلقة واحدة طالق السنة بتاريخ ‪1430/5/22‬هـ‬\n      ‫وأنهــا الطلقــة الثالثــة وأنهــا بانــت منــه بينونــة كبــرى أ ‪ .‬ه ـ ‪ .‬ثــم طلبــت‬\n      ‫منهــا احضــار أصــل صــك الطــاق فاســتعدت بذلــك وطلبــت امهالهــا إلــى‬\n      ‫جلســة أخــرى وقــررت قائلــة إننــي لــم أســتطع احضــار تقريــر مفصــل عــن‬\n      ‫حالــة ابنتنــا ‪...‬وأطلــب امهالــي إلحضــاره يف اجللســة القادمــة فأجيــب‬\n      ‫لذلــك ثــم رفعــت اجللســة بعــد افهــام املدعــى عليهــا بــأن عليهــا احضــار‬\n      ‫التقريــر الطبــي املطلــوب وأصــل صــك الطــاق وخطــاب محــرر تبــن فيــه‬\n      ‫ســبب امتناعهــا بــأن تكــون احلضانــة للمدعــي وبعــد افهــام املدعــي‬\n      ‫أيضــا بــأن عليــه احضــار خطــاب محــرر يبــن فيــه ســبب امتناعــه بــأن‬\n      ‫تكــون احلضانــة للمدعــى عليهــا ويف يوم الســبت املوافق ‪1433/4/24‬هـ‬\n      ‫افتتحــت اجللســة يف الســاعة التاســعة والنصــف صباحــا وفيهــا حضــر‬\n\n\n‫‪231‬‬\n\f‫املدعــي ولــم حتضــر املدعــى عليهــا ولــم حتضــر املطلــوب منهــا يف اجللســة‬\n‫الســابقة وهــو أصــل صــك طالقهــا وتقريــر طبــي مفصــل عــن حالــة ابنتهــا‬\n‫‪...‬وســبب امتناعهــا بــأن تكــون احلضانــة للمدعــي ثــم رفعــت اجللســة‬\n‫لطلبهــا مــرة أخــرى وبعــد ويف يــوم الثالثــاء املوافــق ‪1433/06/3‬ه ـ‬\n‫افتتحــت اجللســه يف الســاعة التاســعة والنصــف صباح ـ ًا وفيهــا حضــر‬\n‫املدعــي ‪...‬واملدعــى عليهــا ‪...‬ثــم قــررت املدعــى عليهــا قائلــة إن ســبب‬\n‫مطالبتــي بــرد دعــوى املدعــي هــو أن ابنتــي (‪ )...‬و (‪ )...‬منــذ والدتهمــا‬\n‫وهمــا عنــدي وأنــا أنفــق عليهمــا كمــا أننــي لم أتزوج حتــى اآلن ومتفرغة‬\n‫لتربيتهــن وأنــا أولــى مــن والدهمــا ألنــه لــو حكــم باحلضانــة لــه فلــن‬\n‫يراعاهمــا بنفســه بــل ســترعاهما زوجتــه التــي لهــا عشــرة أوالد وســبعة‬\n‫أحفــاد هــذه هــي أســباب مطالبتــي بــرد الدعــوى ثــم أبــرزت املدعــى‬\n‫عليهــا أصــل صــك الطــاق املثبــت نصــه يف اجلســلة املنعقــدة يف‬\n‫‪1433/03/15‬ه ـ فوجدتــه مطابقـ ًا لتلــك الصــورة التــي أبرزتهــا املدعــى‬\n‫عليهــا يف تلــك اجللســة ثــم قــررت قائلــه إننــي لــم أســتطع احلصــول علــى‬\n‫تقريــر طبــي مفصــل عــن حالــة ابنتــي (‪ )...‬حتــى اآلن وقــد طلــب مديــر‬\n‫مستشــفى امللــك ســعود أن يتــم مخاطبتــه رســمي ًا لتزويــد فضيلتكــم‬\n‫بالتقريــر املطلــوب ثــم رفعــت اجللســة ويف يــوم األحــد املوافــق‬\n‫‪1433/7/20‬ه ـ افتتحــت اجللســة يف الســاعة االعاشــرة والنصــف صباح ًا‬\n‫وفيهــا حضــر املدعــي ‪...‬ولــم حتضــر املدعــى عليهــا وال مــن ينــوب عنهــا‬\n‫ولــم تقــدم عــذر ًا لذلــك رغــم تبلغهــا بهــذا املوعــد يف ضبــط القضيــة ثــم‬\n‫رفعــت اجللســة إلحضارهــا بنــاء علــى املــادة (‪ )101‬مــن نظــام املرافعــات‬\n‫الشــرعية ولوائحــه التنفيذيــة ويف يــوم الســبت املوافــق ‪1433/9/23‬ه ـ‬\n‫افتتحت اجللســة يف الســاعة احلادية عشــر صباحا وفيها حضر املدعي‪...‬‬\n\n\n                                                                                     ‫‪232‬‬\n\f      ‫ولــم حتضــر املدعــى عليهــا ‪...‬ولــم يردنــا أي إفــادة مــن شــرطة عنيــزة علــى‬\n      ‫خطابنــا رقــم (‪ )331371701‬يف (‪1433/7/21‬هــ) املطلوب فيه إحضار‬\n      ‫املدعــى عليهــا بنــاء علــى املــادة (‪ )101‬مــن نظــام املرافعــات الشــرعية‬\n      ‫ولوائحــه التنفيذيــة وقــد وردنــا يف هــذه اجللســة خطــاب ســعادة مديــر‬\n      ‫مستشفى امللك سعود بعنيزة رقم ‪/5811‬خ‪ 45/36/‬يف ‪1433/6/22‬هـ‬\n      ‫جوابــا علــى خطابنــا رقــم (‪ )331043960‬يف (‪1433/6/3‬هــ) املطلــوب‬\n      ‫فيــه إفادتنــا بتقريــر مفصــل عــن ‪...‬وقــد أرفــق مــع خطــاب ســعادته‬\n      ‫التقريــر الطبــي بنفــس رقــم اخلطــاب يف ‪1433/6/22‬ه ـ وتبــن أنهــا‬\n      ‫تعانــي مــن استســقاء خلقــي بالعمــود الفقــري أدى إلــى شــلل غيــر تــام‬\n      ‫بالطرفــن الســفليني مــع صعوبــة شــديدة باملشــي مــع وجــود عيــوب‬\n      ‫بالقلــب وأنهــا حتتــاج إلــى رعايــة خاصــة أ‪.‬هــ‪ .‬كمــا قــرر املدعــي ‪...‬طلبــا‬\n      ‫عارضــا مت تقييــده برقــم ‪ 331050503‬يف ‪1433/6/4‬ه ـ مت إرفاقــه‬\n      ‫باملعاملــة يتضمــن مطالبــة بتحديــد موعــد لــه لزيــارة ابنتيــه ‪ ...‬و‪ ...‬فبنــاء‬\n      ‫علــى ماســبق مــن الدعــوى واإلجابــة ونظــرا ألن املدعــى عليهــا لــم تتــزوج‬\n      ‫حتــى اآلن وقــد صــادق املدعــي علــى ذلــك ويؤكــد ذلــك تقدميهــا ألصــل‬\n      ‫الطــاق اخلــاص بهــا مــن زوجهــا املدعــي علــى أن املدعــى عليهــا تســكن‬\n      ‫يف بيــت لوحدهــا ومصادقتــه علــى أنــه لــو حكــم لــه باحلضانــة فإنــه‬\n      ‫ســيجعل ابنتيــه لــدى زوجتــه وألنــه جــرى التأكــد مــن ميــاد هاتــن‬\n      ‫االبنتــن ونوعيــة إعاقــة ‪...‬وألن املدعــي لــم يثبــت عــدم صالحيــة املدعــى‬\n      ‫عليهــا حلضانــة ابنتيهــا وألنــه جــرى عــرض الصلــح عليهمــا فلــم يصطلحــا‬\n      ‫وألنــه ســبق أن قــررت هيئــة اخلبــراء بقرارهــا رقــم (‪/3‬هــ)‬\n      ‫يف(‪1431/1/2‬هـ)أنهــا تــرى أن تكــون حضانــة البنتــن لــأم مــا لــم‬\n      ‫تتــزوج أ‪.‬هــ‪ .‬ونظــر ًا ملــا قــرره أهــل العلــم مــن أن أحــق النــاس باحلضانــة هي‬\n\n\n‫‪233‬‬\n\f‫إالم لقولــه عليــه الصــاة والســام ‪ ((:‬أنــت أحــق بــه مــا لــم تنكحــي))‬\n‫أخرجــه أبــو داود (‪ )2276‬يف (ك الطــاق ‪ /‬بــاب مــن أحــق بالولــد )‬\n‫واإلمــام أحمــد برقــم (‪ )6707‬واحلاكــم (‪ )207/2‬وصححــه ووافقــه‬\n‫الذهبــي وقــد قــرر ابــن القيــم صحــة هــذا احلديــث يف كتابــه زاد املعــاد‬\n‫ص (‪ )389‬ط مؤسســة الرســالة وذكــر أيضـ ًا أن هــذا هــو مذهــب األئمة‬\n‫األربعــة ثــم قــرر رحمــه اهلل يف ص (‪ )390‬مــا نصــه ‪ ((:‬أن هــذا احلديــث‬\n‫دل علــى أنــه إذا افتــرق األبــوان وبينهمــا ولــد فــاألم أحــق بــه مــن األب مــا‬\n‫لــم يقــم بــاألم مــا مينــع تقدميهــا أو بالولــد وصــف يقتضــي تخييــره وهــذا مــا‬\n‫ال يعــرف فيــه نــزاع )) أ‪.‬هــ‪ .‬ونظــر ًا الن املدعــي قــد قــدم طلب ـ ًا عارض ـ ًا‬\n‫يطلــب فيــه حتديــد موعــد لــه لزيــارة ابنتيــه ‪...‬و ‪...‬وقــد لــزم الفصــل فيــه‬\n‫وهــذا ال يحتــاج الــى حتديــد مــن هيئــة اخلبــراء بــل يكفــي فيــه حتديــد‬\n‫ذلــك مــن قبلنــا حســب املصلحــة التــي يراهــا احلاكــم يف هــذه القضيــة‬\n‫لذلــك كلــه فقــد حكمــت مبــا يلــي أو ًال رد دعــوى املدعــي وقــررت أن‬\n‫املدعــى عليهــا هــي األحــق بحضانــة ابنتيهــا ‪...‬و‪...‬مــا لــم يقــم املدعــى‬\n‫عليهــا مــا مينــع مــن تقدميهــا أو بــكل واحــدة مــن هاتــن البنتــن وصــف‬\n‫يقتضــي تخييرهمــا ثاني ـ ًا إلــزام املدعــى عليهــا بتمكــن املدعــي مــن‬\n‫زيــارة ابنتيــه مرتــن يف األســبوع بحيــث يأخذهمــا الســاعة اخلامســة‬\n‫مســاء ويعيدهمــا الــى والدتهمــا املدعــى عليهــا الســاعة التاســعة مســاء‬\n‫كل يــوم أحــد وأربعــاء وبعرضــه علــى املدعــي لــم يقنــع بــه وطالــب‬\n‫بتمييــزه فأجيــب لطلبــه ثــم جــرى تســليمه نســخة احلكــم ومت إفهامــه‬\n‫بــأن عليــه تســليم الئحتــه االعتراضيــة يف مــدة أقصاهــا ثالثــون يومـ ًا مــن‬\n‫تاريــخ هــذا اليــوم وأنــه إذا مضــت هــذه املــدة احملــددة آنف ـ ًا ولــم يقــدم‬\n‫فيهــا اعتراضــه فــان حقــه يف طلــب التمييــز يســقط فقــرر اســتالمه‬\n\n\n                                                                                          ‫‪234‬‬\n\f      ‫لنســخة احلكــم وفهمــه ملــا أفهــم بــه آنف ـ ًا واســتعداده بتقــدمي الئحتــه يف‬\n      ‫املــدة احملــددة نظام ـ ًا كمــا أمــرت بتســليم املدعــى عليهــا ‪...‬نســخة مــن‬\n      ‫هــذا احلكــم عــن طريــق ادارة احملضريــن بهــذه احملكمــة لتقــدمي‬\n      ‫اعتراضهــا علــى احلكــم املتعلــق بالزيــارة إن كان لهــا اعتــراض‬\n      ‫وإفهامهــا بــأن لهــا احلــق يف ذلــك خــال مــدة أقصاهــا ثالثــون يوم ـ ًا مــن‬\n      ‫تاريخ اســتالمها لهذه النســخة وأنه إذا مضت املدة ولم تقدم اعتراضها‬\n      ‫فــان حقهــا يســقط يف طلــب التمييــز وأمــا اكتســاب احلكــم للقطعيــة‬\n      ‫فانــه ال يكتســب القطعيــة إال بتصديــق االســتئناف أو بعــدم تقــدمي‬\n      ‫املتداعيــن جميع ـ ًا لوائحهمــا االعتراضيــة يف املــدة احملــددة نظام ـ ًا‬\n      ‫وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد ‪ ،‬حـ ـ ـ ـ ـ ـ ــرر‬\n                                                                  ‫ف ـ ـ ــي ‪1433/9/23‬هـ ‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد يف يــوم االربعــاء املوافــق ‪1434 / 2/20‬ه ـ‬\n      ‫افتتحــت اجللســة يف الســاعة الثامنــة صباحــا بنــاء علــى ورود املعاملــة مــن‬\n      ‫محكمــة االســتئناف بالقصيــم برقــم (‪ )3480724‬يف ‪1434/1/21‬ه ـ‬\n      ‫مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة املختصــة‬\n      ‫بتدقيــق قضايــا األحــوال الشــخصية واالنهــاءات مبحكمــة االســتئناف‬\n      ‫بالقصيــم رقــم (‪ )3412609‬يف ‪1434/1/14‬ه ـ املقــرر فيــه مــا نــص‬\n      ‫احلاجــة منــه (( وباالطــاع علــى املعاملــة والصــك وصــورة ضبطــه لوحــظ‬\n      ‫أن فضيلتــه لــم يــدون يف الضبــط قــرار الدائــرة ومــا يجيــب بــه عليــه ولــم‬\n      ‫يلحــق خالصــة وافيــة مــن ذلــك يف صــك احلكــم وهــذا مخالــف ملقتضــى‬\n      ‫املــادة (‪ )1/187‬مــن لوائــح نظــام املرافعــات الشــرعية ‪ .‬فعلــى فضيلتــه‬\n      ‫مالحظــة مــا ذكــر وإحلــاق مــا يجريــه بالضبــط والصــك وســجله ثــم‬\n      ‫إعــادة املعاملــة إلكمــال الزمهــا )) أ‪.‬هــ‪ .‬وعليــه أجيــب بأنــه ظهــر لــي مــن‬\n\n\n‫‪235‬‬\n\f‫املعاملــة مــا يلــي أوال أنــه صــدر قــرار الدائــرة املختصــة بتدقيــق األحــوال‬\n‫الشــخصية واالنهــاءات مبحكمــة االســتئناف مبنطقــة القصيــم رقــم‬\n‫(‪ )33476085‬يف (‪1433/12/22‬هــ) املقــرر فيــه أنــه لوحــظ أن صــورة‬\n‫الضبــط ناقصــة حيــث لــم يرفــق بهــا جلســة احلكــم وحيثياتــه املؤرخــة‬\n‫يف (‪1433/9/23‬هــ) ثانيــا أن املعاملــة أعيــدت مــن قبــل فضيلــة رئيــس‬\n‫احملكمــة العامــة بعنيــزة برقــم (‪ )3437187‬يف (‪1434/1/7‬هــ) وقــد‬\n‫كنــت يف الفتــرة مــن (‪1433/12/18‬هــ) وحتــى (‪1434/2/13‬هــ)‬\n‫مكلفــا مــن قبــل معالــي وزيــر العــدل بحضــور الــدورة اجلزائيــة‬\n‫املتخصصــة الثانيــة وال أعلــم ســبب إعادتهــا إلــى محكمــة االســتئناف‬\n‫مــن قبــل رئيــس احملكمــة العامــة بعنيــزة خــال تكليفــي بحضــور تلــك‬\n‫الــدورة وهــذا هــو ســبب عــدم إحلــاق مــا أشــار إليــه أصحــاب الفضيلــة‬\n‫وأنــا لســت مســئوال عمــا يتــم خــال فتــرة تكليفــي مــن قبــل معالــي وزيــر‬\n‫العــدل حفظــه اهلل هــذا مــا لــزم بيانــه وإيضاحــه وأمــا املطلــوب فهــو‬\n‫مرفــق أساســا باملعاملــة ابتــداء وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                                                  ‫نبينــا محمــد ‪.‬‬\n‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1434/3/10‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الواحــدة وخمســة عشــر دقيقــة ظهــرا بنــاء علــى‬\n‫ورود املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم (‪)34455767‬‬\n‫يف ‪1434/3/7‬ه ـ مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف‬\n‫بالدائــرة املختصــة بتدقيــق قضايــا األحــوال الشــخصية و االنهــاءات‬\n‫مبحكمــة اإلســتئناف بالقصيــم رقــم (‪ )3453446‬يف ‪1434/3/2‬ه ـ‬\n‫املقــرر فيــه مــا نــص احلاجــة منــه (( وباالطــاع علــى مــا أجــاب بــه‬\n‫فضيلتــه وأحلقــه بالضبــط والصــك بنــاء علــى قرارنــا رقــم (‪)3412609‬‬\n\n\n                                                                                       ‫‪236‬‬\n\f      ‫وتاريــخ ‪1434/1/14‬ه ـ لوحــظ مايلــي ‪ :‬أوال‪ :‬حكــم فضيلتــه باحلضانــة‬\n      ‫والزيــارة مــع أنــه لــم يــرد بالزيــارة دعــوى مــن املدعــي وإمنــا بنــاء علــى‬\n      ‫الطلــب العــارض املقــدم منــه والــذي لــم يــدون رقــم قيــدة وتاريخــه يف‬\n      ‫الضبــط ‪ ،‬كمــا أن دعــوى الزيــارة ال تعتبــر طلبــا عارضــا وإمنــا هــي‬\n      ‫دعــوى مســتقلة حســبما نصــت عليــه املــادة املضافــة رقــم (‪ )4/39‬مــن‬\n      ‫لوائــح نظــام املرافعــات الشــرعية ‪ .‬ثانيــا ‪ :‬ورد يف الضبــط (( أن املدعــى‬\n      ‫عليهــا جــرى تســليمها نســخة احلكــم ومضــت املــدة النظاميــة ولــم تقــدم‬\n      ‫الئحــة اعتراضيــة ولــذا فــإن احلكــم بالنســبة لهــا يعتبــر قطعيــا)) ولــم‬\n      ‫جنــد أن فضيلتــه دون ذلــك يف صــك احلكــم وهــذا مخالــف ملقتضــى‬\n      ‫املــادة (‪ )178‬مــن نظــام املرافعــات الشــرعية ‪ .‬فعلــى فضيلتــه مالحظــة‬\n      ‫ماذكــر)) ‪.‬أ‪.‬هــ‪ .‬وعليــه أجيــب مشــائخنا أصحــاب الفضيلــة جزاهــم اهلل‬\n      ‫عنــا خيــرا بــأن مــا ورد يف املالحظــة األولــى كان بنــاء علــى الطلــب‬\n      ‫العــارض اخلــاص بالزيــارة قيــد برقــم (‪ )331050503‬يف ‪1433/6/4‬ه ـ‬\n      ‫وأمــا مــا اســتند عليــه مشــائخنا يف قرارهــم وهــي املــادة املضافــة رقــم‬\n      ‫(‪ )4/39‬فإنــه العالقــة لهــا بهــذا املوضــوع ألنهــا تنــص علــى أنــه إذا وردت‬\n      ‫املعاملــة إلــى احملكمــة مــن جهــة رســمية ولــم يرفــق بهــا صحيفــة دعــوى‬\n      ‫فيتــم اســتكمال بيانــات الصحيفــة مــن املدعــي لــدى مكتــب املواعيــد‬\n      ‫أ‪.‬هــ‪ .‬ولعــل مشــائخنا يقصــدون الفقــرة الرابعــة عشــر مــن املــادة التاســعة‬\n      ‫والثالثــن مــن نظــام املرافعــات الشــرعية وهــذه الفقــرة لــم متنــع تقــدمي‬\n      ‫طلــب عــارض بالزيــارة وإمنــا نصــت علــى أن دعــوى الزيــارة إذا قدمــت‬\n      ‫مســتقلة فإنهــا حتــال مــع القضايــا الزوجيــة واخللــع والفســخ والنفقــة‬\n      ‫واحلضانــة إلــى قاضــي واحــد وحتســب لــه إحالــة وأمــا ســبب قبولــي لهــذا‬\n      ‫الطلــب العــارض املتعلــق بالزيــارة يف الدعــوى فهــو ألمريــن أحدهمــا مــا‬\n\n\n‫‪237‬‬\n\f‫جــاء يف املــادة (‪/79‬هــ) مــن نظــام املرافعــات الشــرعية وثانيهمــا هــو‬\n‫ســرعة البــت يف هــذه القضيــة بشــكل يحفــظ بــه حــق املتداعيــن وحــق‬\n‫الطفلتــن وأمــا بالنســبة للمالحظــة الثانيــة فإنــه ســيتم مراعــاة ذلــك‬\n‫مســتقبال إن شــاء اهلل وأشــكر مشــائخنا أصحــاب الفضيلــة علــى هــذا‬\n‫التنبيــه والعمــل ذكــر هــذه املالحظــة واجلــواب عليهــا يغنــي عــن نقــل تلــك‬\n‫اجللســة اخلاصــة باكتســاب احلكــم للقطعيــة بحــق املدعــى عليهــا ألن‬\n‫إدخــال تلــك اجللســة يف الصــك يف محلهــا ســيضطر إلــى إخــراج صــك‬\n‫جديــد كمــا ال يخفــى يف نقــل جلســة ســابقة إلــى الصــك يف النظــام‬\n‫الشــامل هــذا مــا لــزم اجلــواب عليــه وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                 ‫‪ .‬حــرر يف ‪ 1434/03/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1434/7/4‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الثامنــة والنصــف صباحــا بنــاء علــى ورود املعاملــة مــن‬\n‫محكمــة االســتئناف بالقصيــم برقــم ‪ 34644803‬يف ‪1434/4/20‬ه ـ‬\n‫مــزودة بقــرار أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واالنهــاءات مبحكمــة االســتئناف‬\n‫بالقصيــم رقــم ‪ 34187931‬يف ‪1434/4/15‬ه ـ املقــرر فيه مانص احلاجة‬\n‫منــه ( وباالطــاع علــى مــا أجاب به فضيلته وأحلقه بالضبط والصك بناء‬\n‫علــى قرارنــا رقــم (‪ )3453446‬وتاريــخ ‪1434/3/2‬ه ـ لوحــظ أن جــواب‬\n‫فضيلتــه علــى املالحظــة األولــى غيــر مقنــع وال مــاق ملــا طلــب منــه ألن‬\n‫دعــوى الزيــارة دعــوى مســتقلة حســب املــادة املضافــة (‪ )14/39‬مــن لوائح‬\n‫نظــام املرافعــات الشــرعية كمــا لــم يــرد يف الضبــط والصــك دعــوى مــن‬\n‫املدعــي بطلــب حتديــد زيــارة ابنتيــه وغنمــا بنــى فضيلتــه حكمــه علــى‬\n‫الطلــب املقــدم مــن املدعــي وحتــى لــو قيــل بقبــول دعــوى الزيــارة بعــد أن‬\n\n\n                                                                                      ‫‪238‬‬\n\f      ‫يدعــي بهــا املدعــي ويطالــب بهــا فــإن حتديدهــا ينبغــي أن يكــون مبنيــا‬\n      ‫علــى قــرار هيئــة النظــر الــذي يكــون معتمدهــم فيــه علــى ماتــراه مــن‬\n      ‫وضــع املتداعيــن ومصلحــة البنتــن وحتــدد فيــه آليــة الزيــارة ومــن يقــوم‬\n      ‫بأخذهمــا وإعادتهمــا فعلــى فضيلتــه مالحظــة ماذكــر وإجــراء مايلــزم‬\n      ‫علــى وفــق ماذكــر أو الرجــوع عمــا أجــراه بخصــوص ماقــرره مــن زيــارة‬\n      ‫للبنتــن وقصــر احلكــم علــى احلضانــة وإجــراء مايلــزم بحضــور الطرفــن‬\n      ‫وإحلــاق مايجريــه يف الضبــط وصورتــه والصــك وســجله ثــم إعــادة املعاملة‬\n      ‫إلكمــال الزمهــا )أ‪.‬هــ‪ .‬وقــد حضــر يف هــذه اجللســة املدعــي ‪...‬كمــا‬\n      ‫حضــرت املدعــى عليهــا ‪...‬والتــي متــت مطابقــة بطاقتهــا مــن قبــل حارســة‬\n      ‫األمــن يف هــذه احملكمــة ‪...‬حســبما يظهــر مــن صــورة البطاقــة املرفقــة‬\n      ‫ثــم قــرر املدعــي قائــا لقــد ســبق أن تقدمــت بطلــب عــارض أطلــب فيــه‬\n      ‫زيــارة أوالدي ومــادام أن أصحــاب الفضيلــة قضــاة االســتئناف قــرروا أنــه‬\n      ‫البــد مــن املطالبــة بــه يف ضبــط القضيــة فإننــي أقــرر مطالبتــي بذلــك‬\n      ‫وهــو نفــس طلبــي العــارض الــذي قدمتــه ســابقا هكــذا قــرر ولــذا فإنــه‬\n      ‫ماقــرره املدعــي هــو الــرد علــى هــذه املالحظــة وأمــا بخصــوص أنــه ينبغــي‬\n      ‫أن يكــون ذلــك بقــرار مــن هيئــة اخلبــراء فإننــي ال أرى وجــوب ذلــك ألن‬\n      ‫النظــر النهائــي يف تقريــر الزيــارة هــو للقاضــي ألن للقاضــي رد قــرار‬\n      ‫اخلبــراء حســبما نــص عليــه النظــام وأمــا كــون جوابــي غيــر مقنــع فــإن‬\n      ‫حســبي االجتهــاد واحلكــم مبــا أراه صوابــا واهلل املوفــق وبعرضــه علــى‬\n      ‫املدعــى عليهــا قــررت قناعتهــا باحلكــم املتضمــن احلكــم باحلضانــة‬\n      ‫والزيــارة وأمــا املدعــي فقــرر أنــه مــازال علــى معارضتــه الســابقة والئحتــه‬\n      ‫االعتراضيــة املقدمــة منــه ســابقا وعليــه جــرى التوقيــع وصلــى اهلل وســلم‬\n                                         ‫علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/7/4‬ه ـ ‪.‬‬\n\n\n‫‪239‬‬\n\f‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة املختصــة‬\n‫بتدقيــق قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة عنيــزة برقــم (‪ )34/644803‬وتاريــخ ‪1434/7/5‬هــ؛‬\n‫املقيــدة لــدى احملكمــة برقــم (‪ )341651535‬وتاريــخ ‪1434/7/9‬هــ؛‬\n‫اخلاصــة بدعــوى‪... /‬ضــد‪... /‬؛ بشــأن مطالبتــه بحضانــة ابنتيــه منهــا‪/‬‬\n‫‪...‬و‪...‬؛ املنتهيــة بالصــك الصــادر مــن فضيلــة الشــيخ‪... /‬القاضــي‬\n‫باحملكمــة؛ املســجل برقــم (‪ )33417800‬وتاريــخ ‪1433/9/23‬هــ؛‬\n‫املتضمــن حكــم فضيلتــه بــرد دعــوى املدعــي وأن األم هــي األحــق‬\n‫بحضانــة البنتــن املذكورتــن وإلــزام املدعــى عليهــا بتمكــن املدعــي‬\n‫مــن زيــارة ابنتيــه املذكورتــن؛ علــى النحــو املفصــل فيــه‪ .‬وقــد ســبق منــا‬\n‫دراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‪.‬‬\n‫ـاء‬\n‫وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالضبــط والصــك بنـ ً‬\n‫علــى قرارنــا رقــم (‪ )34187931‬وتاريــخ ‪1434/4/15‬ه ـ قررنا املصادقة‬\n‫علــى ماحكــم بــه فضيلتــه بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق‪ ،‬وصلــى‬\n                              ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪240‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":227,"source_page_end":240,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"db7a987a1441fe2597d4c79ce379d3f720b664073d2b757cee13bf5cb8aa606b","normalized_text_hash":"241111f305a082e9f3b649e8adcb74ec81efab1f882f54240b76b4a484311fa3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p227-33417800"},{"id":"ffa4eb0b-414b-5603-bc34-849a7f3fba40","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب اجلدة حضانة بنت ابنتها -إثبات التقرير النفسي رغبة البنت أن تكون عند جدتها ألمها -عماد احلضانة األصلح للمحضون -األحق باحلضانة األم ثم أمهاتها -احلكم بأن اجلدة ألم هي األولى بحضانة بنت ابنتها -األخذ بقول األخصائي النفسي و االجتماعي يف األحق باحلضانة -للقاضي األخذ برأي أهل اخلبرة أو رفضه .","document_number":"33430026","case_number":"3369325","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة يف الرياض وطلب إحالتها ملقر سكن املدعى عليه بجدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/17","year":"1434","subject":"حضانة -طلب اجلدة حضانة بنت ابنتها -إثبات التقرير النفسي رغبة البنت أن تكون عند جدتها ألمها -عماد احلضانة األصلح للمحضون -األحق باحلضانة األم ثم أمهاتها -احلكم بأن اجلدة ألم هي األولى بحضانة بنت ابنتها -األخذ بقول األخصائي النفسي و االجتماعي يف األحق باحلضانة -للقاضي األخذ برأي أهل اخلبرة أو رفضه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33430026 :‬تاريخه ‪1433/10/17 :‬هـ‬\n                            ‫رقم القضية ‪3369325:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3439907‬تاريخه‪1434/02/18 :‬هـ‬\n\n\n       ‫حضانــة‪ -‬طلــب اجلــدة حضانــة بنــت ابنتهــا‪ -‬إثبــات التقريــر النفســي‬\n       ‫رغبــة البنــت أن تكــون عنــد جدتهــا ألمهــا‪ -‬عمــاد احلضانــة األصلــح‬\n       ‫للمحضــون‪ -‬األحــق باحلضانــة األم ثــم أمهاتهــا‪ -‬احلكــم بــأن اجلــدة‬\n       ‫ألم هــي األولــى بحضانــة بنــت ابنتهــا‪ -‬األخــذ بقــول األخصائــي‬\n       ‫النفســي و االجتماعــي يف األحــق باحلضانــة‪ -‬للقاضــي األخــذ بــرأي‬\n                                                         ‫أهــل اخلبــرة أو رفضــه ‪.‬‬\n\n\n\n       ‫‪ .1‬قــال ابــن القيــم ‪ -‬رحمــه اهلل ‪ -‬يف زاد املعــاد ( ‪ ( ) 463/5‬والصــواب‬\n       ‫النظــر واالحتيــاط للطفــل يف األصلــح واألنفــع يف اإلقامــة أو االنتقــال‬\n       ‫ويف احلاضــن فأيهــم كان أنفــع لــه وأصــون وأحفــظ روعــي وال تأثيــر‬\n                                                               ‫إلقامــة وال نقلــة ) ‪.‬‬\n            ‫القاعدة التي تقرر ( أن عماد احلضانة هو األصلح للمحضون ) ‪.‬‬\n                   ‫‪ .2‬ما قرره أهل العلم أن األولى باحلضانة األم ثم أمهاتها ‪.‬‬\n       ‫‪ .3‬املــادة رقــم ‪/10/34‬ه ـ مــن نظــام املرافعــات الشــرعية املعدلــة والتــي‬\n       ‫تضمنــت ( ويســري هــذا احلكــم علــى دعــاوى احلضانــة والزيــارة يف‬\n                                                          ‫األحــوال الشــخصية ) ‪.‬‬\n\n\n\n\n‫‪241‬‬\n\f‫حضــرت اجلــدة ألم وادعــت علــى زوج ابنتهــا ســابق ًا بأنهــا أجنبــت منــه‬\n‫بنتـ ًا اســمها ‪ ............‬مولــودة بتاريــخ ‪1424/8/21‬ه ـ وقــد حصــل طــاق‬\n‫بــن الطرفــن والطفلــة عنــد والدهــا ولكــون والدتهــا متزوجــة طلبــت‬\n‫احلكــم لهــا بحضانــة الطفلــة املذكــورة‪ ،‬دفــع املدعــى عليــه وكالــة‬\n‫بعــدم اختصــاص احملكمــة العامــة يف الريــاض وطلــب إحالتهــا ملقــر‬\n‫ســكن املدعــى عليــه بجــدة‪ ،‬كمــا قــرر أنــه قــد صــدر صــك بــن‬\n‫بنــت املدعيــة وموكلــه أن البنــت تبقــى عنــد والدهــا‪ ،‬جــرت الكتابــة‬\n‫ملستشــفى الصحــة النفســية إلبــداء تقريــر عــن الطفلــة املذكــورة فــورد‬\n‫التقريــر الطبــي أن الطفلــة املذكــورة ال تعانــي مــن اضطــراب نفســي‬\n‫وحالتهــا مســتقرة وتوجــد ضغــوط مــن قبــل الوالديــن تؤثــر عليهــا الختيار‬\n‫مــكان احليــاة أو تفضيــل مــكان علــى آخــر إال أن الطفلــة أبــدت تعلقهــا‬\n‫عاطفي ـ ًا بجدتهــا ألمهــا يف الريــاض وتفضــل احليــاة هنــاك‪ ،‬مت االطــاع‬\n‫علــى الصــك بــن بنــت املدعيــة وزوجهــا ســابق ًا واملتضمــن وجــود اتفــاق‬\n‫وصلــح علــى أن تكــون احلضانــة لوالدتهــا وزيــارة والدهــا يف منــزل‬\n‫زوجتــه ســابق ًا يف الريــاض‪ ،‬مت ســؤال املدعــى عليــه وكالــة هــل تطعــن‬\n‫بحضانــة املدعيــة بشــيء فأجــاب بقولــه أنهــا كبيــرة يف الســن‪ ،‬قــرر‬\n‫املدعــي وكالــة أن البنــت تقعــد عنــد زوجــة والدهــا ووالدهــا مشــغول‬\n‫فاملدعيــة أولــى بهــا‪ ،‬قــرر األخصائــي النفســي أن الطفلــة تشــعر بتفــاوت‬\n‫املعاملــة بينهــا وبــن أختهــا ألبيهــا‪ ،‬ملــا كانــت احلضانــة مــن األمــور‬\n‫املتجــددة واحلكــم الصــادر بــن الزوجــة وزوجهــا ســابق ًا لــم يتضمــن‬\n‫احلكــم للمدعــى عليــه باحلضانــة صراحــة‪ ،‬وحيــث إن عمــاد احلضانــة‬\n\n                                                                                  ‫‪242‬‬\n\f      ‫هــو األصلــح للمحضــون‪ ،‬احلكــم بحضانــة اجلــدة للبنــت وتســليمها‬\n      ‫إياهــا مــع أوراقهــا الثبوتيــة‪ ،‬قــرر املدعــى عليــه اعتراضــه علــى احلكــم‬\n                         ‫بالئحة‪،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض املســاعد برقــم ‪ 3369325‬وتاريــخ ‪1433/01/26‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 33181558‬وتاريــخ ‪ 1433/01/26‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق ‪1433/10/17‬ه ـ حضــر ‪ ...‬ســعودي اجلنســية‬\n      ‫مبوجــب ســجل مدنــي رقــم ‪ ...‬بصفتــه وكيــا عــن ‪ ...‬ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬ينــوب عنهــا يف املطالبــة واملرافعــة‬\n      ‫واملدافعــة واملخاصمــة واإلقــرار واإلنــكار والصلــح وطلــب وقبــول‬\n      ‫احلكــم أو اإلعتــراض عليــه مبوجــب صــك وكالــة صــادر مــن كتابــة‬\n      ‫عــدل محافظــة الدرعيــة برقــم ‪ 32268328‬يف ‪1432/10/19‬ه ـ وأدعــى‬\n      ‫علــى احلاضــر معــه ‪ ...‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪...‬‬\n      ‫بصفتــه وكيــا عــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ...‬ينــوب عنــه يف مراجعــة احملكمــة العامــة وحضــور اجللســات مبوجــب‬\n      ‫صــك وكالــة صــادر مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة‬\n      ‫برقــم ‪ 47908‬يف ‪1433/5/26‬ه ـ قائــا يف حتريــر دعــواه إن املدعــى‬\n      ‫عليــه كان زوجــا البنــة موكلتــي والتــي أجنبــت منــه بنتــا اســمها ‪...‬‬\n      ‫مولــودة يف ‪1424/8/21‬ه ـ وقــد حصــل الطــاق بــن الطرفــن وحيــث‬\n      ‫إن الطفلــة املذكــورة لــدى والدهــا ولكــون والدتهــا متزوجــه فــا حــق‬\n\n‫‪243‬‬\n\f‫لهــا يف احلضانــة لــذا فــإن موكلتــي تطلــب احلكــم لهــا بحضانــة الطفلــة‬\n‫املذكــورة وتســليمها لهــا هــذي دعــواي وبســؤال املدعــى عليــه قــال إن‬\n‫موكلــي يســكن يف محافظــة جــدة وأرغــب أن تكــون الدعــوى هنــاك‬\n‫وموكلــي ســبق أن تداعــى مــع مطلقتــه وصــدر صــك يف املوضــوع يفهــم‬\n‫منــه ان البنــت عنــده وهــو ال يقبــل تولــي املدعيــة للحضانــة هكــذا أجــاب‬\n‫وبعرضــه علــى املدعــي قــال الصــك ال دخــل ملوكلتــي فيــه ولــم يتضمــن‬\n‫احلكــم باحلضانــة للمدعــى عليــه واالختصــاص معقــود حملكمــة‬\n‫الريــاض هكــذا قــال وهنــا جــرى اإلطــاع علــى تاريــخ ميــاد الطفلــة‬\n‫املطابــق ملــا ذكــر كمــا جــرت الكتابــة ملستشــفى الصحــة النفســية‬\n‫بجــدة التــي أفــادت بخطابهــا رقــم ‪ 173‬يف ‪1433/1/12‬ه ـ وقــد تبــن‬\n‫مــن خــال ذلــك أن الطفلــة يف الوقــت احلالــي ال تعانــي مــن أي اضطــراب‬\n‫نفســي وال توجــد اســاءة معاملــة وتوجــد ضغــوط مــن قبــل الوالديــن‬\n‫تؤثــر عليهــا بدرجــة متوســطة وقــد كانــت الطفلــة اجتماعيــة و متعاونــة‬\n‫ومتحفظــة يف بدايــة التقييــم إال أنهــا اســتطاعت بعــد ذلــك التعبيــر‬\n‫عــن نفســه بشــكل جيــد بالــكالم والرســم واوضحــت أن هنــاك‬\n‫بعــض الضغــوط عليهــا مــن والديهــا الختيــار مــكان احليــاة أو تفضيــل‬\n‫مــكان عــن آخــر إال أن الطفلــة أبــدت تعلقهــا عاطفيــا بجدتهــا ألمهــا يف‬\n‫الريــاض وتفضــل احليــاة هنــاك بالرغــم مــن وجــود والديهــا يف جــدة وهــي‬\n‫حتتــاج الســتكمال منوهــا النفســي إلــى توفــر منــوذج األم أو مــن يقــوم‬\n‫مقامهــا والتوصيــة توفيــر منــوذج األم حتــى تنمــو بطريقــة طبيعيــة ووجــوب‬\n‫االهتمــام والرعايــة مــن قبــل األب‪ .‬كمــا جــرى اإلطــاع علــى املــادة‬\n‫‪/10/34‬ه ـ املعدلــة مــن املرافعــات والتــي تضمنــت (ويســري هــذا احلكم‬\n‫علــى دعــاوى احلضانــة والزيــارة يف األحــوال الشــخصية ) واإلطــاع علــى‬\n\n\n                                                                                   ‫‪244‬‬\n\f      ‫الصــك رقــم ‪ 29/137‬يف ‪1429/6/30‬ه ـ واملتضمــن دعــوى ‪ ...‬ضــد ‪...‬‬\n      ‫يف موضــوع زيــارة وآخــره االتفــاق والصلــح علــى أن تكــون احلضانــة‬\n      ‫لوالدتهــا وزيــارة والدهــا يف منــزل املدعــى عليهــا يف الريــاض يف حــال‬\n      ‫البنــت إكمــال البنــت الســابعة يحــق لوالدهــا اســتالمها يف حصــول‬\n      ‫إشــكاليه فاملرجــع للقضــاء انتهــى‪ .‬وهنــا جــرى ســؤال املدعــى عليــه هــل‬\n      ‫لديــه طعــن يف املدعيــة قــال هــي فقــط امــرأة كبيــرة يف الســن وقــال‬\n      ‫املدعــي إن موكلتــي صحيحــه قــادره والطفلــة تقعــد عنــد زوجــة أبيهــا‬\n      ‫ووالدهــا مشــغول فاملدعيــة أولــى بهــا ثــم أبــرز صــورة خطــاب مــن هيئــة‬\n      ‫حقــوق اإلنســان مبنطقــة مكــة يتضمــن أن األخصائــي النفســي قــرر أن‬\n      ‫الطفلــة تشــعر بتفــاوت املعاملــة بينهــا وبــن أختهــا ألبيهــا فبنــاء علــى مــا‬\n      ‫تقــدم وملــا كان احلضانــة مــن األمــور املتجــددة وكذلــك فــإن احلكــم‬\n      ‫املذكــور لــم يتضمــن احلكــم للمدعــى عليــه باحلضانــة صراحــه وحيــث‬\n      ‫إن عمــاد احلضانــة هــو األصلــح للمحضــون قــال ابــن القيــم ( الصــواب‬\n      ‫النظــر واالحتيــاط للطفــل يف األصلــح واألنفــع يف اإلقامــة أو االنتقــال‬\n      ‫ويف احلاضــن فأيهــم كان أنفــع لــه وأصــون وأحفــظ روعــي وال تأثيــر‬\n      ‫إلقامــه وال نقلــه) زاد املعــاد ‪ 463/5‬وملــا قــرره أهــل العلــم ان األولــى‬\n      ‫باحلضانــة األم ثــم امهاتهــا لذلــك كلــه وملــا ســبق فقــد ثبــت لــدي أن‬\n      ‫املدعيــة ‪ ...‬أولــى بحضانــة ‪ ... ...‬وأنــه يلــزم املدعــى عليــه تســليمها مــع‬\n      ‫نســخة مــن اوراقهــا الثبوتيــة للمدعيــة ومبــا ســبق حكمــت وبعرضــه‬\n      ‫علــى املدعــى عليــه قــرر املعارضــة وطلــب اإلســتئناف فأجيــب لطلبــه‬\n      ‫وســلم صــورة احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا فــإن‬\n      ‫مضــت املــدة ولــم يتقــدم بالئحــة اعتراضــه ســقط حقــه يف اإلعتــراض‬\n      ‫واكتســب احلكــم القطعيــة وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n\n\n‫‪245‬‬\n\f           ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي القائــم بعمــل‬\n‫فضيلــة الشــيخ ‪ ...‬القاضــي يف احملكمــة العامــة بالريــاض ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/04/13‬ه ـ افتتحــت اجللســة الســاعة ‪12 : 30‬‬\n‫وكانــت املعاملــة قــد عــادت مــن محكمــة اإلســتئناف برفقهــا القــرار‬\n‫رقــم ‪ 3439907‬وتاريــخ ‪1434/2/18‬ه ـ الصــادر مــن دائــرة األحــوال‬\n‫الشــخصية األولــى املتضمــن وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫اإلعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب اإلعتــراض أ‪.‬ه ـ وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪ 1434/04/13‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتمييــز قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد برقــم ‪ 34/62278‬وتاريــخ ‪1434/1/7‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...‬املســجل‬\n‫برقــم ‪ 33430026‬وتاريــخ ‪1433/10/17‬ه ـ اخلــاص بدعــوى ‪ ...‬الوكيــل‬\n‫عــن ‪ ...‬ضــد ‪ ...‬الوكيــل عــن ‪ ...‬بشــأن حضانــة أوالد وقــد تضمــن الصــك‬\n‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب‬\n‫االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                         ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪246‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":241,"source_page_end":246,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"caac87c6649cbd7e37b7d82df9063cfa1089e42dd21e59afe9f7eaf49b740591","normalized_text_hash":"75a25feeb0048a44b8d323cd866846befe67a37b26da513a06b5829aeb90abfe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p241-33430026"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
